INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d8662c6-50dd-419b-b0d6-bacb6a227026', '問張山人疾', '问張山人疾', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["先生沈病意何如，蓬艾門前客轉疎。","不見領徒過絳帳，唯聞與婢削丹書。"]', '["先生沈病意何如，蓬艾门前客轉疎。","不见領徒過絳帳，唯闻與婢削丹书。"]', '诗', 'shi', '', NULL, '問張山人疾 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64df610f-2fd8-479f-8ed5-8f87799e634d', '江上送客', '江上送客', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["故人南去漢江陰，秋雨蕭蕭雲夢深。","江上見人應下淚，由來遠客易傷心。"]', '["故人南去漢江陰，秋雨蕭蕭云梦深。","江上见人應下泪，由来远客易傷心。"]', '诗', 'shi', '', NULL, '江上送客 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4810005b-9113-452a-b336-caafe5709ebe', '閨情', '閨情', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["月落星稀天欲明，孤燈未滅夢難成。","披衣更向門前望，不忿朝來鵲喜聲。"]', '["月落星稀天欲明，孤灯未滅梦难成。","披衣更向门前望，不忿朝来鵲喜声。"]', '诗', 'shi', '', NULL, '閨情 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc8c1156-0d8f-4302-94c5-f63bc3a123dd', '送劉侍郎', '送劉侍郎', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["幾人同去謝宣城，未及酬恩隔死生。","唯有夜猨知客恨，嶧陽溪路第三聲。"]', '["幾人同去謝宣城，未及酬恩隔死生。","唯有夜猨知客恨，嶧陽溪路第三声。"]', '诗', 'shi', '', NULL, '送劉侍郎 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81df0640-9a72-454b-89f9-8ed0008e9188', '重送鄭宥歸蜀因寄何兆', '重送鄭宥归蜀因寄何兆', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["黃花西上路何如，青壁連天雁亦疎。","爲報長卿休滌器，漢家思見茂陵書。"]', '["黄花西上路何如，青壁連天雁亦疎。","爲報长卿休滌器，漢家思见茂陵书。"]', '诗', 'shi', '', NULL, '重送鄭宥歸蜀因寄何兆 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d53959db-c139-454f-a061-f7604a37a823', '宿石澗店聞婦人哭', '宿石澗店闻婦人哭', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["山店門前一婦人，哀哀夜哭向秋雲。","自說夫因征戰死，朝來逢著舊將軍。"]', '["山店门前一婦人，哀哀夜哭向秋云。","自说夫因征戰死，朝来逢著旧將軍。"]', '诗', 'shi', '', NULL, '宿石澗店聞婦人哭 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14d2c040-c7ac-4485-b966-6de812cb7b32', '與道者別', '與道者別', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["聞說滄溟今已淺，何當白鶴更歸來。","舊師唯有先生在，忍見門人掩淚回。"]', '["闻说滄溟今已淺，何當白鹤更归来。","旧師唯有先生在，忍见门人掩泪回。"]', '诗', 'shi', '', NULL, '與道者別 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('954f3f46-87dd-4f9b-b656-d61dae5fb23b', '長門怨', '长门怨', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["金壺漏盡禁門開，飛燕昭陽侍寢回。","隨分獨眠秋殿裏，遙聞語笑自天來。"]', '["金壺漏尽禁门开，飞燕昭陽侍寢回。","隨分独眠秋殿裏，遙闻語笑自天来。"]', '诗', 'shi', '', NULL, '長門怨 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8be14f6-49ea-4e59-ad37-30bcf16e17a6', '憶友懷野寺舊居', '憶友懷野寺旧居', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["自嫌野性共人疎，憶向西林更結廬。","寄謝山陰許都講，昨來頻得遠公書。"]', '["自嫌野性共人疎，憶向西林更結廬。","寄謝山陰許都講，昨来頻得远公书。"]', '诗', 'shi', '', NULL, '憶友懷野寺舊居 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bee2baa5-b40f-4740-a10e-5633dc1250d8', '聽夜雨寄盧綸', '听夜雨寄盧綸', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["暮雨蕭條過鳳城，霏霏颯颯重還輕。","聞君此夜東林宿，聽得荷池幾番聲。"]', '["暮雨蕭條過鳳城，霏霏颯颯重還轻。","闻君此夜东林宿，听得荷池幾番声。"]', '诗', 'shi', '', NULL, '聽夜雨寄盧綸 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d30f7f4-44ac-4dbf-964e-723479e69e1f', '昭君詞', '昭君词', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["李陵初送子卿回，漢月明時惆悵來。","憶著長安舊遊處，千門萬戶玉樓臺。"]', '["李陵初送子卿回，漢月明时惆悵来。","憶著长安旧游处，千门万戶玉楼台。"]', '诗', 'shi', '', NULL, '昭君詞 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca03d740-e7bc-4cbc-9007-c59a3043d798', '春晚游鶴林寺寄使府諸公', '春晚游鹤林寺寄使府諸公', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["野寺尋春花已遲，背巖惟有兩三枝。","明朝攜酒猶堪醉，爲報春風且莫吹。"]', '["野寺尋春花已遲，背巖惟有兩三枝。","明朝携酒猶堪醉，爲報春风且莫吹。"]', '诗', 'shi', '', NULL, '春晚游鶴林寺寄使府諸公 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9d4c055-1dc0-4555-b180-979008c8d0f0', '南充謝郡客遊澧州留贈宇文中丞', '南充謝郡客游澧州留贈宇文中丞', 'bdedfcb3-43d1-4e58-bf48-73f389d5f279', '唐', '["僕本濩落人，辱當州郡使。","量力頗及早，謝歸今即已。","蕭蕭若凌虛，襟帶頓銷靡。","車服率然來，涔陽作遊子。","鬱鬱寡開顏，默默獨行李。","忽逢平生友，一笑方在此。","秋情寧風日，楚思浩雲水。","爲語弋林者，冥冥鴻遠矣。"]', '["僕本濩落人，辱當州郡使。","量力頗及早，謝归今即已。","蕭蕭若凌虛，襟带頓銷靡。","车服率然来，涔陽作游子。","鬱鬱寡开顏，默默独行李。","忽逢平生友，一笑方在此。","秋情寧风日，楚思浩云水。","爲語弋林者，冥冥鴻远矣。"]', '诗', 'shi', '', NULL, '南充謝郡客遊澧州留贈宇文中丞 暢當 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac2183df-331b-4594-a1dd-0498da05e189', '宿報恩寺精舍', '宿報恩寺精舍', 'bdedfcb3-43d1-4e58-bf48-73f389d5f279', '唐', '["鐘梵送沈景，星多露漸光。","風中蘭靡靡，月下樹蒼蒼。","夜殿若山橫，深松如澗涼。","羸然虎溪子，遲我一虛牀。","杳杳空寂舍，濛濛蓮桂香。","擁褐依西壁，紗燈靄中央。"]', '["鐘梵送沈景，星多露漸光。","风中蘭靡靡，月下樹蒼蒼。","夜殿若山橫，深松如澗涼。","羸然虎溪子，遲我一虛牀。","杳杳空寂舍，濛濛蓮桂香。","擁褐依西壁，紗灯靄中央。"]', '诗', 'shi', '', NULL, '宿報恩寺精舍 暢當 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0f6fbf7-0066-4d48-94bf-cb0c06c031a2', '自平陽館赴郡', '自平陽館赴郡', 'bdedfcb3-43d1-4e58-bf48-73f389d5f279', '唐', '["晨興平陽館，見月沈江水。","溶溶山霧披，肅肅沙鷺起。","奉恩謬符竹，伏軾省頑鄙。","何當施教化，愧迎小郡史。","寥落火耕俗，征途青冥裏。","德綏及吾民，不德將鹿矣。","擒姦非性能，多愍會衰齒。","恭承共理詔，恆懼墜諸地。"]', '["晨兴平陽館，见月沈江水。","溶溶山霧披，肅肅沙鷺起。","奉恩謬符竹，伏軾省頑鄙。","何當施教化，愧迎小郡史。","寥落火耕俗，征途青冥裏。","德綏及吾民，不德將鹿矣。","擒姦非性能，多愍會衰齒。","恭承共理詔，恆懼墜諸地。"]', '诗', 'shi', '', NULL, '自平陽館赴郡 暢當 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f54d9c1-76d9-4cca-b20a-17b33225a457', '天柱隱所重荅江州應物', '天柱隐所重荅江州應物', 'bdedfcb3-43d1-4e58-bf48-73f389d5f279', '唐', '["寂寞一悵望，秋風山景清。","此中惟草色，翻意見人行。","荒徑饒松子，深蘿絕鳥聲。","陽崖全帶日，寬嶂偶通耕。","拙昧難容世，貧寒別有情。","煩君瓊玖贈，幽懶百無成。"]', '["寂寞一悵望，秋风山景清。","此中惟草色，翻意见人行。","荒徑饒松子，深蘿絕鸟声。","陽崖全带日，寬嶂偶通耕。","拙昧难容世，貧寒別有情。","煩君瓊玖贈，幽懶百無成。"]', '诗', 'shi', '', NULL, '天柱隱所重荅江州應物 暢當 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cae5034c-32bd-4cd7-9f3b-9ea8ac9ae813', '山居酬韋蘇州見寄', '山居酬韋蘇州见寄', 'bdedfcb3-43d1-4e58-bf48-73f389d5f279', '唐', '["孤柴泄煙處，此中山叟居。","觀雲寧有事，耽酒詎知餘。","水定鶴翻去，松歌峰儼如。","猶煩使君問，更欲結深廬。"]', '["孤柴泄煙处，此中山叟居。","观云寧有事，耽酒詎知餘。","水定鹤翻去，松歌峰儼如。","猶煩使君问，更欲結深廬。"]', '诗', 'shi', '', NULL, '山居酬韋蘇州見寄 暢當 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7637208-b55e-48a0-8c10-12cb7cc30e59', '春日過奉誠園', '春日過奉誠园', 'bdedfcb3-43d1-4e58-bf48-73f389d5f279', '唐', '["帝里陽和日，遊人到御園。","暖催新景氣，春認舊蘭蓀。","詠德先臣沒，成蹊大樹存。","見桐猶近井，看柳尚依門。","獻地非更宅，遺忠永奉恩。","又期攀桂後，來賞百花繁。"]', '["帝里陽和日，游人到御园。","暖催新景氣，春認旧蘭蓀。","詠德先臣沒，成蹊大樹存。","见桐猶近井，看柳尚依门。","獻地非更宅，遺忠永奉恩。","又期攀桂後，来賞百花繁。"]', '诗', 'shi', '', NULL, '春日過奉誠園 暢當 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d8a679a-e8c7-421d-9d83-534a1394c677', '軍中醉飲寄沈八劉叟', '軍中醉饮寄沈八劉叟', 'bdedfcb3-43d1-4e58-bf48-73f389d5f279', '唐', '["酒渴愛江清，餘酣漱晚汀。","軟莎欹坐穩，冷石醉眠醒。","野膳隨行帳，華音發從伶。","數杯君不見，都已遣沈冥。"]', '["酒渴愛江清，餘酣漱晚汀。","軟莎欹坐穩，冷石醉眠醒。","野膳隨行帳，华音發從伶。","數杯君不见，都已遣沈冥。"]', '诗', 'shi', '', NULL, '軍中醉飲寄沈八劉叟 暢當 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e02943e8-20f0-479f-b3ea-db70190ed5b3', '偶宴西蜀摩訶池', '偶宴西蜀摩訶池', 'bdedfcb3-43d1-4e58-bf48-73f389d5f279', '唐', '["珍木鬱清池，風荷左右披。","淺觴寧及醉，慢舸不知移。","蔭簟流光冷，凝簪照影欹。","胡爲獨羈者，雪涕向漣漪。"]', '["珍木鬱清池，风荷左右披。","淺觴寧及醉，慢舸不知移。","蔭簟流光冷，凝簪照影欹。","胡爲独羈者，雪涕向漣漪。"]', '诗', 'shi', '', NULL, '偶宴西蜀摩訶池 暢當 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7df2e6f1-cd80-4543-9f36-2227f421238b', '奉送杜中丞赴洪州', '奉送杜中丞赴洪州', 'bdedfcb3-43d1-4e58-bf48-73f389d5f279', '唐', '["詔出鳳凰宮，新恩連帥雄。","江湖經戰陣，草木待仁風。","豪右貪威愛，紆繁德簡通。","多慙君子顧，攀餞路塵中。"]', '["詔出鳳凰宮，新恩連帥雄。","江湖經戰陣，草木待仁风。","豪右貪威愛，紆繁德簡通。","多慙君子顧，攀餞路塵中。"]', '诗', 'shi', '', NULL, '奉送杜中丞赴洪州 暢當 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbe5917e-3b2f-45ac-b458-bcbf662e1aad', '九日陪皇甫使君泛江宴赤岸亭', '九日陪皇甫使君泛江宴赤岸亭', 'bdedfcb3-43d1-4e58-bf48-73f389d5f279', '唐', '["羈旅逢佳節，逍遙忽見招。","同傾菊花酒，緩櫂木蘭橈。","平楚堪愁思，長江去寂寥。","猿啼不離峽，灘沸鎮如潮。","舉目關山異，傷心鄉國遙。","徒言歡滿座，誰覺客魂消。"]', '["羈旅逢佳節，逍遙忽见招。","同傾菊花酒，緩櫂木蘭橈。","平楚堪愁思，长江去寂寥。","猿啼不離峽，灘沸鎮如潮。","舉目关山異，傷心乡国遙。","徒言歡满座，誰覺客魂消。"]', '诗', 'shi', '', NULL, '九日陪皇甫使君泛江宴赤岸亭 暢當 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c81c43d4-beab-4445-b3e9-d7992ff7b573', '蒲中道中二首 一', '蒲中道中二首 一', 'bdedfcb3-43d1-4e58-bf48-73f389d5f279', '唐', '["蒼蒼中條山，厥形極奇磈。","我欲涉其崖，濯足黃河水。"]', '["蒼蒼中條山，厥形極奇磈。","我欲涉其崖，濯足黄河水。"]', '诗', 'shi', '', NULL, '蒲中道中二首 一 暢當 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7140206-0d47-44c5-a3e2-e325d62c2cc1', '蒲中道中二首 二', '蒲中道中二首 二', 'bdedfcb3-43d1-4e58-bf48-73f389d5f279', '唐', '["古剎棲杮林，綠陰覆蒼瓦。","歲晏來品題，拾葉總堪寫。"]', '["古剎棲杮林，綠陰覆蒼瓦。","歲晏来品題，拾葉總堪寫。"]', '诗', 'shi', '', NULL, '蒲中道中二首 二 暢當 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fac2dc15-b1ab-4d6d-89f0-fab7c805398e', '登鸛雀樓', '登鸛雀楼', 'bdedfcb3-43d1-4e58-bf48-73f389d5f279', '唐', '["逈臨飛鳥上，高出世塵間。","天勢圍平野，河流入斷山。"]', '["逈臨飞鸟上，高出世塵间。","天勢圍平野，河流入斷山。"]', '诗', 'shi', '', NULL, '登鸛雀樓 暢當 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dabec09f-0fd1-4a09-b0c2-c3aae3db4c82', '宿潭上二首 一', '宿潭上二首 一', 'bdedfcb3-43d1-4e58-bf48-73f389d5f279', '唐', '["夜潭有仙舸，與月當水中。","嘉賓愛明月，遊子驚秋風。"]', '["夜潭有仙舸，與月當水中。","嘉賓愛明月，游子驚秋风。"]', '诗', 'shi', '', NULL, '宿潭上二首 一 暢當 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee628ffc-983f-4689-b6be-839ae94a65bf', '宿潭上二首 二', '宿潭上二首 二', 'bdedfcb3-43d1-4e58-bf48-73f389d5f279', '唐', '["青蒲野陂水，白露明月天。","中夜秋風起，心事坐潸然。"]', '["青蒲野陂水，白露明月天。","中夜秋风起，心事坐潸然。"]', '诗', 'shi', '', NULL, '宿潭上二首 二 暢當 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c32bc3e0-3733-4816-b56d-9c72a0e20119', '別盧綸', '別盧綸', 'bdedfcb3-43d1-4e58-bf48-73f389d5f279', '唐', '["故交君獨在，又欲與君離。","我有新秋淚，非關宋玉悲。"]', '["故交君独在，又欲與君離。","我有新秋泪，非关宋玉悲。"]', '诗', 'shi', '', NULL, '別盧綸 暢當 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d14174f4-ac57-479f-b377-5dc1f7a44d9d', '題沈八齋', '題沈八斋', 'bdedfcb3-43d1-4e58-bf48-73f389d5f279', '唐', '["江齋一入何亭亭，因寄淪漣心杳冥。","綠綺琴彈白雪引，烏絲絹勒黃庭經。"]', '["江斋一入何亭亭，因寄淪漣心杳冥。","綠綺琴彈白雪引，烏絲絹勒黄庭經。"]', '诗', 'shi', '', NULL, '題沈八齋 暢當 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff85eb04-4826-4889-95b7-a362b0939f64', '早春', '早春', 'c8a524e9-9b39-4424-a2c0-8d9050501f14', '唐', '["獻歲春猶淺，園林未盡開。","雪和新雨落，風帶舊寒來。","聽鳥聞歸鴈，看花識早梅。","生涯知幾日，更被一年催。"]', '["獻歲春猶淺，园林未尽开。","雪和新雨落，风带旧寒来。","听鸟闻归鴈，看花識早梅。","生涯知幾日，更被一年催。"]', '诗', 'shi', '', NULL, '早春 暢諸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6e0972b-b2c8-4a54-b1ad-255e77cb708d', '曉過南宮聞太常清樂', '晓過南宮闻太常清乐', '08a93454-0a28-49f1-b0fa-85f014582942', '唐', '["南宮聞古樂，拂曙聽初驚。","煙靄遙迷處，絲桐暗辨名。","節隨新律改，聲帶緒風輕。","合雅將移俗，同和自感情。","遠音兼曉漏，餘響過春城。","九奏明初日，寥寥天地清。"]', '["南宮闻古乐，拂曙听初驚。","煙靄遙迷处，絲桐暗辨名。","節隨新律改，声带緒风轻。","合雅將移俗，同和自感情。","远音兼晓漏，餘响過春城。","九奏明初日，寥寥天地清。"]', '诗', 'shi', '', NULL, '曉過南宮聞太常清樂 陸贄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0a74e24-e84f-48cd-a77c-cfdc6fa9a5fd', '禁中春松', '禁中春松', '08a93454-0a28-49f1-b0fa-85f014582942', '唐', '["陰陰清禁裏，蒼翠滿春松。","雨露恩偏近，陽和色更濃。","高枝分曉日，虛吹雜宵鐘。","香助鑪煙遠，形疑蓋影重。","願符千載壽，不羨五株封。","儻得迴天眷，全勝老碧峰。"]', '["陰陰清禁裏，蒼翠满春松。","雨露恩偏近，陽和色更濃。","高枝分晓日，虛吹杂宵鐘。","香助鑪煙远，形疑蓋影重。","願符千載壽，不羨五株封。","儻得迴天眷，全勝老碧峰。"]', '诗', 'shi', '', NULL, '禁中春松 陸贄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7035e601-9fae-45b2-8556-c2645bfc2f33', '賦得御園芳草', '賦得御园芳草', '08a93454-0a28-49f1-b0fa-85f014582942', '唐', '["陰陰御園裏，瑤草日光長。","靃靡含煙霧，依稀帶夕陽。","雨餘荑更密，風暖蕙初香。","擁仗緣馳道，乘輿入建章。","溼煙搖不散，細影亂無行。","恆恐韶光晚，何人辨早芳。"]', '["陰陰御园裏，瑤草日光长。","靃靡含煙霧，依稀带夕陽。","雨餘荑更密，风暖蕙初香。","擁仗緣驰道，乘輿入建章。","溼煙搖不散，細影亂無行。","恆恐韶光晚，何人辨早芳。"]', '诗', 'shi', '', NULL, '賦得御園芳草 陸贄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28503959-b22c-4839-bf8f-6afd22bd3842', '句', '句', '08a93454-0a28-49f1-b0fa-85f014582942', '唐', '["遶堦流㶁㶁，來砌樹陰陰。"]', '["遶堦流㶁㶁，来砌樹陰陰。"]', '诗', 'shi', '', NULL, '句 陸贄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64f8effb-f257-4693-9682-d29cb6c9159b', '曉過南宮聞太常清樂', '晓過南宮闻太常清乐', '3ca7fbf7-7cb6-42b6-affd-4c92f648aac2', '唐', '["玉珂經禮寺，金奏過南宮。","雅調乘清曉，飛聲向遠空。","慢隨飄去雪，輕逐度來風。","迥出重城裏，傍聞九陌中。","應將肆夏比，更與五英同。","一聽南薫曲，因知大舜功。"]', '["玉珂經禮寺，金奏過南宮。","雅調乘清晓，飞声向远空。","慢隨飄去雪，轻逐度来风。","迥出重城裏，傍闻九陌中。","應將肆夏比，更與五英同。","一听南薫曲，因知大舜功。"]', '诗', 'shi', '', NULL, '曉過南宮聞太常清樂 張濛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e10f0a1-a937-48ec-b21b-d50dd5e66007', '禁中春松', '禁中春松', 'e0db62fc-9689-484f-a498-deb5334340c5', '唐', '["映殿松偏好，森森列禁中。","攢柯霑聖澤，疎蓋引皇風。","晚色連秦苑，春香滿漢宮。","操將金石固，材與直臣同。","翠影宜青瑣，蒼枝秀碧空。","還知沐天眷，千載更蔥蘢。"]', '["映殿松偏好，森森列禁中。","攢柯霑聖澤，疎蓋引皇风。","晚色連秦苑，春香满漢宮。","操將金石固，材與直臣同。","翠影宜青瑣，蒼枝秀碧空。","還知沐天眷，千載更蔥蘢。"]', '诗', 'shi', '', NULL, '禁中春松 常沂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0de77f00-258c-4c9b-b8a2-6f79bd0c3c66', '禁中春松', '禁中春松', 'd31bd057-0ca2-43ec-b600-6a74788fb022', '唐', '["幾歲含貞節，青青紫禁中。","日華留偃蓋，雉尾轉春風。","不爲繁霜改，那將衆木同。","千條攢翠色，百尺澹晴空。","影密金莖近，花明鳳沼通。","安知幽澗側，獨與散樗叢。"]', '["幾歲含貞節，青青紫禁中。","日华留偃蓋，雉尾轉春风。","不爲繁霜改，那將衆木同。","千條攢翠色，百尺澹晴空。","影密金莖近，花明鳳沼通。","安知幽澗側，独與散樗叢。"]', '诗', 'shi', '', NULL, '禁中春松 周存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0e3d89d-ec95-4b54-b358-65d5dd40e9c8', '西戎獻馬', '西戎獻马', 'd31bd057-0ca2-43ec-b600-6a74788fb022', '唐', '["天馬從東道，皇威被遠戎。","來參八駿列，不假貳師功。","影別流沙路，嘶流上苑風。","望雲時蹀足，向月每爭雄。","稟異才難狀，標奇志豈同。","驅馳如見許，千里一朝通。"]', '["天马從东道，皇威被远戎。","来參八駿列，不假貳師功。","影別流沙路，嘶流上苑风。","望云时蹀足，向月每爭雄。","稟異才难狀，標奇志豈同。","驱驰如见許，千里一朝通。"]', '诗', 'shi', '', NULL, '西戎獻馬 周存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd0fc773-5fe1-4fcd-bd2a-8e50417fc322', '小苑春望宮池柳色', '小苑春望宮池柳色', 'abb151e3-47d4-4108-981b-92cdce5a0674', '唐', '["上林新柳變，小苑暮天晴。","始望和煙密，遙憐拂水輕。","色承陽氣暖，陰帶御溝清。","不厭隨風弱，仍宜向日明。","垂絲遍閣榭，飛絮觸簾旌。","漸到依依處，思聞出谷鸎。"]', '["上林新柳变，小苑暮天晴。","始望和煙密，遙怜拂水轻。","色承陽氣暖，陰带御溝清。","不厭隨风弱，仍宜向日明。","垂絲遍閣榭，飞絮觸簾旌。","漸到依依处，思闻出谷鸎。"]', '诗', 'shi', '', NULL, '小苑春望宮池柳色 黎逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edae3601-9f65-4bf2-8814-696f1a4c7ec8', '夏首猶清和', '夏首猶清和', 'abb151e3-47d4-4108-981b-92cdce5a0674', '唐', '["早夏宜初景，和光起禁城。","祝融將御節，炎帝啓朱明。","日送殘花晚，風過御苑清。","郊原浮麥氣，池沼發荷英。","樹影臨山動，禽飛入漢輕。","幸逢堯禹化，全勝谷中情。"]', '["早夏宜初景，和光起禁城。","祝融將御節，炎帝啓朱明。","日送殘花晚，风過御苑清。","郊原浮麦氣，池沼發荷英。","樹影臨山动，禽飞入漢轻。","幸逢堯禹化，全勝谷中情。"]', '诗', 'shi', '', NULL, '夏首猶清和 黎逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d97a60f8-4b5a-4f77-a39a-00c869ff0ff3', '小苑春望宮池柳色', '小苑春望宮池柳色', 'e30056f7-459b-4010-b2af-d5ebabedc833', '唐', '["小苑春初至，皇衢日更清。","遙分萬條柳，迴出九重城。","隱映龍池潤，參差鳳闕明。","影宜宮雪曙，色帶禁煙晴。","深淺殘陽變，高低曉吹輕。","年光正堪折，欲寄一枝榮。"]', '["小苑春初至，皇衢日更清。","遙分万條柳，迴出九重城。","隐映龙池潤，參差鳳闕明。","影宜宮雪曙，色带禁煙晴。","深淺殘陽变，高低晓吹轻。","年光正堪折，欲寄一枝榮。"]', '诗', 'shi', '', NULL, '小苑春望宮池柳色 張昔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c7aca84-6bc9-4656-99c3-ce1515a8145e', '小苑春望宮池柳色', '小苑春望宮池柳色', '11344d46-56e7-4fa6-bf2d-aafb4b134b22', '唐', '["小苑春初望，宮池柳色輕。","低昂含曉景，縈轉帶新晴。","似蓋芳初合，如絲蔭漸成。","依依連水暗，嫋嫋出牆明。","雖以陽和發，能令旅思生。","他時花滿路，從此接遷鶯。"]', '["小苑春初望，宮池柳色轻。","低昂含晓景，縈轉带新晴。","似蓋芳初合，如絲蔭漸成。","依依連水暗，嫋嫋出牆明。","雖以陽和發，能令旅思生。","他时花满路，從此接遷鶯。"]', '诗', 'shi', '', NULL, '小苑春望宮池柳色 丁位 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa3870fe-2673-4710-bc94-802dcb4f42fd', '小苑春望宮池柳色', '小苑春望宮池柳色', 'ead4da13-a23f-43b1-9bb6-d86c62328d90', '唐', '["柳色新池遍，春光御苑晴。","葉依青閣密，條向碧流傾。","路暗陰初重，波搖影轉清。","風從垂處度，煙就望中生。","斷續游蜂聚，飄颻戲蝶輕。","怡然變芳節，願及一枝榮。"]', '["柳色新池遍，春光御苑晴。","葉依青閣密，條向碧流傾。","路暗陰初重，波搖影轉清。","风從垂处度，煙就望中生。","斷續游蜂聚，飄颻戲蝶轻。","怡然变芳節，願及一枝榮。"]', '诗', 'shi', '', NULL, '小苑春望宮池柳色 元友直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6ce9316-8ec8-4eb8-b767-d6eb614dbd3d', '小苑春望宮池柳色', '小苑春望宮池柳色', '84b2208c-0580-4193-9618-7e7d21adc3a8', '唐', '["勝游從小苑，宮柳望春晴。","拂地青絲嫩，縈風綠帶輕。","光含煙色遠，影透水文清。","玉笛吟何得，金閨畫豈成。","皇風吹欲斷，聖日映逾明。","願駐高枝上，還同出谷鶯。"]', '["勝游從小苑，宮柳望春晴。","拂地青絲嫩，縈风綠带轻。","光含煙色远，影透水文清。","玉笛吟何得，金閨畫豈成。","皇风吹欲斷，聖日映逾明。","願駐高枝上，還同出谷鶯。"]', '诗', 'shi', '', NULL, '小苑春望宮池柳色 楊系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5878fe4c-3613-461b-ab7e-1444dd2492f8', '小苑春望宮池柳色', '小苑春望宮池柳色', '968f0012-bfab-4454-a677-4ba2a0bb4023', '唐', '["帝京春氣早，御柳已先榮。","嫩葉隨風散，浮光向月明。","悠揚生別意，斷續引芳聲。","積翠連馳道，飄花出禁城。","柔條依水弱，遠色帶煙輕。","南望龍池畔，斜光照晚晴。"]', '["帝京春氣早，御柳已先榮。","嫩葉隨风散，浮光向月明。","悠揚生別意，斷續引芳声。","積翠連驰道，飄花出禁城。","柔條依水弱，远色带煙轻。","南望龙池畔，斜光照晚晴。"]', '诗', 'shi', '', NULL, '小苑春望宮池柳色 崔績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c0bbd24-967c-4c50-a027-50c786d8d576', '小苑春望宮池柳色', '小苑春望宮池柳色', '1beeb177-7c93-458d-b899-6cd9f1cfc605', '唐', '["韶光歸漢苑。","柳色發春城，半見離宮出。","纔分遠水明，青蔥當淑景。","隱映媚新晴，積翠煙初合。","微黃葉未生，迎春看尚嫩。","照日見先榮，倘得辭幽谷。","高枝寄一名。"]', '["韶光归漢苑。","柳色發春城，半见離宮出。","纔分远水明，青蔥當淑景。","隐映媚新晴，積翠煙初合。","微黄葉未生，迎春看尚嫩。","照日见先榮，倘得辞幽谷。","高枝寄一名。"]', '诗', 'shi', '', NULL, '小苑春望宮池柳色 張季略 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d595c63e-48b4-44d0-859e-e8e68f074aff', '小苑春望宮池柳色', '小苑春望宮池柳色', '0f3d0ac2-5e31-4a56-92df-61337397604f', '唐', '["勝遊經小苑，閑望上春城。","御路韶光發，宮池柳色輕。","乍濃含雨潤，微澹帶雲晴。","羃歷殘煙斂，搖揚落照明。","幾條垂廣殿，數樹影高旌。","獨有風塵客，思同雨露榮。"]', '["勝游經小苑，闲望上春城。","御路韶光發，宮池柳色轻。","乍濃含雨潤，微澹带云晴。","羃歷殘煙斂，搖揚落照明。","幾條垂廣殿，數樹影高旌。","独有风塵客，思同雨露榮。"]', '诗', 'shi', '', NULL, '小苑春望宮池柳色 裴達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01199cd7-9a2a-4489-8b81-2a61043b2d01', '南至日太史登臺書雲物', '南至日太史登台书云物', 'b5071798-c41a-403f-aafb-f354b466a21b', '唐', '["圓丘纔展禮，佳氣近初分。","太史新簪筆，高臺紀彩雲。","煙空和縹緲，曉色共氛氳。","道泰資賢輔，年豐荷聖君。","恭惟司國瑞，兼用察人文。","應念懷鉛客，終朝望碧雰。"]', '["圓丘纔展禮，佳氣近初分。","太史新簪笔，高台紀彩云。","煙空和縹緲，晓色共氛氳。","道泰資賢輔，年豐荷聖君。","恭惟司国瑞，兼用察人文。","應念懷鉛客，終朝望碧雰。"]', '诗', 'shi', '', NULL, '南至日太史登臺書雲物 裴逵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b5e6994-a85a-4235-b84a-1d4f24ee0aa1', '小苑春望宮池柳色', '小苑春望宮池柳色', '54277615-cd38-4ef7-a833-5c731250f88b', '唐', '["今來遊上苑，春染柳條輕。","濯濯方含色，依依若有情。","分行臨曲沼，先發媚重城。","拂水枝偏弱，搖風絲已生。","變黃隨淑景，吐翠逐新晴。","佇立徒延首，裴回欲寄誠。"]', '["今来游上苑，春染柳條轻。","濯濯方含色，依依若有情。","分行臨曲沼，先發媚重城。","拂水枝偏弱，搖风絲已生。","变黄隨淑景，吐翠逐新晴。","佇立徒延首，裴回欲寄誠。"]', '诗', 'shi', '', NULL, '小苑春望宮池柳色 沈迴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d936030-f10a-41fa-878c-7d48272a5c96', '長安春夜宿開元觀', '长安春夜宿开元观', '03d8197f-6c0d-4867-9b91-1c1ff7016c24', '唐', '["霓裳下晚煙，留客杏花前。","徧問人寰事，新從洞府天。","長松皆掃月，老鶴不知年。","爲說蓬瀛路，雲濤幾處連。"]', '["霓裳下晚煙，留客杏花前。","徧问人寰事，新從洞府天。","长松皆掃月，老鹤不知年。","爲说蓬瀛路，云濤幾处連。"]', '诗', 'shi', '', NULL, '長安春夜宿開元觀 楊憑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fef4870c-55a7-4c00-aa01-d3416ed33a46', '晚泊江戍', '晚泊江戍', '03d8197f-6c0d-4867-9b91-1c1ff7016c24', '唐', '["旅櫂依遙戍，清湘急晚流。","若爲南浦宿，逢此北風秋。","雲月孤鴻晚，關山幾路愁。","年年不得意，零落對滄洲。"]', '["旅櫂依遙戍，清湘急晚流。","若爲南浦宿，逢此北风秋。","云月孤鴻晚，关山幾路愁。","年年不得意，零落对滄洲。"]', '诗', 'shi', '', NULL, '晚泊江戍 楊憑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c2374ee-4b03-4303-8bed-377a9dfd290a', '巴江雨夜', '巴江雨夜', '03d8197f-6c0d-4867-9b91-1c1ff7016c24', '唐', '["五嶺天無雁，三巴客問津。","紛紛輕漢暮，漠漠暗江春。","青草連湖岸，繁花憶楚人。","芳菲無限路，幾夜月明新。"]', '["五嶺天無雁，三巴客问津。","紛紛轻漢暮，漠漠暗江春。","青草連湖岸，繁花憶楚人。","芳菲無限路，幾夜月明新。"]', '诗', 'shi', '', NULL, '巴江雨夜 楊憑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f71cc1a4-be4f-4cb2-b7da-22d345260d50', '邊塞行', '邊塞行', '03d8197f-6c0d-4867-9b91-1c1ff7016c24', '唐', '["九原臨得水，雙足是重城。","獨許爲儒老，相憐從騎行。","細叢榆塞逈，高點雁山晴。","聖主嗤炎漢，無心自勒兵。"]', '["九原臨得水，雙足是重城。","独許爲儒老，相怜從騎行。","細叢榆塞逈，高点雁山晴。","聖主嗤炎漢，無心自勒兵。"]', '诗', 'shi', '', NULL, '邊塞行 楊憑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3a91124-c4de-429d-be66-a80539dcefcf', '樂遊園望月', '乐游园望月', '03d8197f-6c0d-4867-9b91-1c1ff7016c24', '唐', '["炎靈全盛地，明月半秋時。","今古人同望，盈虧節暗移。","彩凝雙月逈，輪度八川遲。","共惜鳴珂去，金波送酒巵。"]', '["炎靈全盛地，明月半秋时。","今古人同望，盈虧節暗移。","彩凝雙月逈，輪度八川遲。","共惜鳴珂去，金波送酒巵。"]', '诗', 'shi', '', NULL, '樂遊園望月 楊憑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08d0e076-ff46-4c75-b7d2-60a94290dfb6', '千葉桃花', '千葉桃花', '03d8197f-6c0d-4867-9b91-1c1ff7016c24', '唐', '["千葉桃花勝百花，孤榮春晚駐年華。","若教避俗秦人見，知向河源舊侶誇。"]', '["千葉桃花勝百花，孤榮春晚駐年华。","若教避俗秦人见，知向河源旧侶誇。"]', '诗', 'shi', '', NULL, '千葉桃花 楊憑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26915352-6358-4301-a3cb-65813f8ec858', '春中汎舟', '春中汎舟', '03d8197f-6c0d-4867-9b91-1c1ff7016c24', '唐', '["仙郎歸奏過湘東，正值三湘二月中。","惆悵滿川桃杏醉，醉看還與曲江同。"]', '["仙郎归奏過湘东，正值三湘二月中。","惆悵满川桃杏醉，醉看還與曲江同。"]', '诗', 'shi', '', NULL, '春中汎舟 楊憑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c646227d-122c-493c-b1fb-410397eb65f7', '雨中怨秋', '雨中怨秋', '03d8197f-6c0d-4867-9b91-1c1ff7016c24', '唐', '["辭家遠客愴秋風，千里寒雲與斷蓬。","日暮隔山投古寺，鐘聲何處雨濛濛。"]', '["辞家远客愴秋风，千里寒云與斷蓬。","日暮隔山投古寺，鐘声何处雨濛濛。"]', '诗', 'shi', '', NULL, '雨中怨秋 楊憑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f00e57ab-0566-404a-aef0-1762ef4933f7', '秋日獨遊曲江', '秋日独游曲江', '03d8197f-6c0d-4867-9b91-1c1ff7016c24', '唐', '["信馬閑過憶所親，秋山行盡路無塵。","主人莫惜松陰醉，還有千錢沽酒人。"]', '["信马闲過憶所親，秋山行尽路無塵。","主人莫惜松陰醉，還有千錢沽酒人。"]', '诗', 'shi', '', NULL, '秋日獨遊曲江 楊憑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd7b2791-2af0-4dbb-8ad0-36686e015ab9', '寄別', '寄別', '03d8197f-6c0d-4867-9b91-1c1ff7016c24', '唐', '["晚煙洲霧共蒼蒼，河雁驚飛不作行。","廻斾轉舟行數里，歌聲猶自逐清湘。"]', '["晚煙洲霧共蒼蒼，河雁驚飞不作行。","廻斾轉舟行數里，歌声猶自逐清湘。"]', '诗', 'shi', '', NULL, '寄別 楊憑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cbaabf1-7aed-421d-9dec-c8a401ca89c4', '邊情', '邊情', '03d8197f-6c0d-4867-9b91-1c1ff7016c24', '唐', '["新種如今屢請和，玉關邊上幸無他。","欲知北海苦辛處，看取節毛餘幾多。"]', '["新種如今屢請和，玉关邊上幸無他。","欲知北海苦辛处，看取節毛餘幾多。"]', '诗', 'shi', '', NULL, '邊情 楊憑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16a90c1d-52ba-46e1-bb5e-0d447c6a2a72', '早發湘中', '早發湘中', '03d8197f-6c0d-4867-9b91-1c1ff7016c24', '唐', '["按節鳴笳中貴催，紅旌白斾滿船開。","迎愁湓浦登城望，西見荆門積水來。"]', '["按節鳴笳中貴催，紅旌白斾满船开。","迎愁湓浦登城望，西见荆门積水来。"]', '诗', 'shi', '', NULL, '早發湘中 楊憑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5728bd1b-c657-43b4-b3e6-842ae3234a26', '海榴', '海榴', '03d8197f-6c0d-4867-9b91-1c1ff7016c24', '唐', '["海榴殷色透簾櫳，看盛看衰意欲同。","若許三英隨五馬，便將濃豔鬬繁紅。"]', '["海榴殷色透簾櫳，看盛看衰意欲同。","若許三英隨五马，便將濃豔鬬繁紅。"]', '诗', 'shi', '', NULL, '海榴 楊憑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16b22371-368d-4d3c-90ee-dff0c3d16670', '春情', '春情', '03d8197f-6c0d-4867-9b91-1c1ff7016c24', '唐', '["暮雨朝雲幾日歸，如絲如霧濕人衣。","三湘二月春光早，莫逐狂風繚亂飛。"]', '["暮雨朝云幾日归，如絲如霧濕人衣。","三湘二月春光早，莫逐狂风繚亂飞。"]', '诗', 'shi', '', NULL, '春情 楊憑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b8a1a9f-19e7-4b7e-aef4-3078bb3dcbd5', '送客往荆州', '送客往荆州', '03d8197f-6c0d-4867-9b91-1c1ff7016c24', '唐', '["巴丘過日又登城，雲水湘東一日平。","若愛春秋繁露學，正逢元凱鎮南荆。"]', '["巴丘過日又登城，云水湘东一日平。","若愛春秋繁露学，正逢元凱鎮南荆。"]', '诗', 'shi', '', NULL, '送客往荆州 楊憑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c4e7fc5-92f5-4bc5-a882-9e536a9c6dda', '贈馬鍊師', '贈马鍊師', '03d8197f-6c0d-4867-9b91-1c1ff7016c24', '唐', '["心嫌碧落更何從，月帔花冠冰雪容。","行雨若迷歸處路，近南惟見祝融峰。"]', '["心嫌碧落更何從，月帔花冠冰雪容。","行雨若迷归处路，近南惟见祝融峰。"]', '诗', 'shi', '', NULL, '贈馬鍊師 楊憑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6145d26a-df42-47a1-80dd-d6cf5bd50112', '湘江泛舟', '湘江泛舟', '03d8197f-6c0d-4867-9b91-1c1ff7016c24', '唐', '["湘川洛浦三千里，地角天涯南北遙。","除却同傾百壺外，不愁誰奈兩魂銷。"]', '["湘川洛浦三千里，地角天涯南北遙。","除却同傾百壺外，不愁誰奈兩魂銷。"]', '诗', 'shi', '', NULL, '湘江泛舟 楊憑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3848220-b67b-4df1-87ee-30b90a87f507', '送別', '送別', '03d8197f-6c0d-4867-9b91-1c1ff7016c24', '唐', '["江岸梅花雪不如，看君驛馭向南徐。","相聞不必因來雁，雲裏飛輧落素書。"]', '["江岸梅花雪不如，看君驛馭向南徐。","相闻不必因来雁，云裏飞輧落素书。"]', '诗', 'shi', '', NULL, '送別 楊憑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46ca0f44-e7b8-4569-a3d3-325d9724b938', '贈竇牟', '贈竇牟', '03d8197f-6c0d-4867-9b91-1c1ff7016c24', '唐', '["直用天才衆却瞋，應欺李杜久爲塵。","南荒不死中華老，別玉翻同西國人。"]', '["直用天才衆却瞋，應欺李杜久爲塵。","南荒不死中华老，別玉翻同西国人。"]', '诗', 'shi', '', NULL, '贈竇牟 楊憑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6ad68da-ff7c-4611-a38f-e49d2bace84d', '送別', '送別', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["樽酒郵亭暮，雲帆驛使歸。","野鷗寒不起，川雨凍難飛。","吳會家移遍，軒轅夢去稀。","姓楊皆足淚，非是強沾衣。"]', '["樽酒郵亭暮，云帆驛使归。","野鷗寒不起，川雨凍难飞。","吳會家移遍，軒轅梦去稀。","姓楊皆足泪，非是強沾衣。"]', '诗', 'shi', '', NULL, '送別 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('307e9576-89c6-44c5-8b80-0b46dd53da02', '送客東歸', '送客东归', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["君向古營州，邊風戰地愁。","草青縵別路，柳亞拂孤樓。","人意傷難醉，鶯啼咽不流。","芳菲只合樂，離思返如秋。"]', '["君向古營州，邊风戰地愁。","草青縵別路，柳亞拂孤楼。","人意傷难醉，鶯啼咽不流。","芳菲只合乐，離思返如秋。"]', '诗', 'shi', '', NULL, '送客東歸 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('740ef99c-f962-402f-9147-030c2d1664f0', '送客歸湖南', '送客归湖南', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["湖南樹色盡，了了辨潭州。","雨散今爲別，雲飛何處遊。","情來偏似醉，淚迸不成流。","那向蕭條路，緣湘篁竹愁。"]', '["湖南樹色尽，了了辨潭州。","雨散今爲別，云飞何处游。","情来偏似醉，泪迸不成流。","那向蕭條路，緣湘篁竹愁。"]', '诗', 'shi', '', NULL, '送客歸湖南 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0481b35-8972-4676-a749-ab9f209cdf28', '送客歸淮南', '送客归淮南', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["畫舫照河堤，暄風百草齊。","行絲直網蝶，去燕旋遺泥。","郡向高天近，人從別路迷。","非關御溝上，今日各東西。"]', '["畫舫照河堤，暄风百草齊。","行絲直網蝶，去燕旋遺泥。","郡向高天近，人從別路迷。","非关御溝上，今日各东西。"]', '诗', 'shi', '', NULL, '送客歸淮南 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ce33de2-76f5-4cec-8e53-db11a25021db', '春情', '春情', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["舊宅洛川陽，曾遊遊俠場。","水添楊柳色，花絆綺羅香。","趙瑟多愁曲，秦家足豔妝。","江潭遠相憶，春夢不勝長。"]', '["旧宅洛川陽，曾游游俠場。","水添楊柳色，花絆綺羅香。","趙瑟多愁曲，秦家足豔妝。","江潭远相憶，春梦不勝长。"]', '诗', 'shi', '', NULL, '春情 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11c4239f-8784-43e5-87a7-3c2d2109dd22', '秋夜聽擣衣', '秋夜听擣衣', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["砧杵聞秋夜，裁縫寄遠方。","聲微漸濕露，響細未經霜。","蘭牖唯遮樹，風簾不礙涼。","雲中望何處，聽此斷人腸。"]', '["砧杵闻秋夜，裁縫寄远方。","声微漸濕露，响細未經霜。","蘭牖唯遮樹，风簾不礙涼。","云中望何处，听此斷人腸。"]', '诗', 'shi', '', NULL, '秋夜聽擣衣 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89382d30-dbf7-4412-9c1c-fecb7e6876e5', '從軍行', '從軍行', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["都尉出居延，強兵集五千。","還將張博望，直救范祁連。","漢卒悲簫鼓，胡姬濕采旃。","如今意氣盡，流淚挹流泉。"]', '["都尉出居延，強兵集五千。","還將張博望，直救范祁連。","漢卒悲簫鼓，胡姬濕采旃。","如今意氣尽，流泪挹流泉。"]', '诗', 'shi', '', NULL, '從軍行 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('567571c0-a3a0-4e62-aa91-565636b1fd6f', '和直禁省', '和直禁省', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["宵直丹宮近，風傳碧樹涼。","漏稀銀箭滴，月度網軒光。","鳳詔裁多暇，蘭燈夢更長。","此時顏范貴，十步舊連行。"]', '["宵直丹宮近，风傳碧樹涼。","漏稀銀箭滴，月度網軒光。","鳳詔裁多暇，蘭灯梦更长。","此时顏范貴，十步旧連行。"]', '诗', 'shi', '', NULL, '和直禁省 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43f7d5bf-6128-4c4a-97d7-db9b6de9fc15', '留別', '留別', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["玉節隨東閣，金閨別舊僚。","若爲花滿寺，躍馬上河橋。"]', '["玉節隨东閣，金閨別旧僚。","若爲花满寺，躍马上河橋。"]', '诗', 'shi', '', NULL, '留別 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed2e0aab-2ee3-4374-8aef-5a1817948255', '送客往洞庭', '送客往洞庭', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["九江歸路遠，萬里客舟還。","若過巴江水，湘東滿碧煙。"]', '["九江归路远，万里客舟還。","若過巴江水，湘东满碧煙。"]', '诗', 'shi', '', NULL, '送客往洞庭 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff101c4c-b3bd-4aef-8e7e-9de532984840', '別友人', '別友人', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["倦客驚危路，傷禽遶樹枝。","非逢暴公子，不敢涕流離。"]', '["倦客驚危路，傷禽遶樹枝。","非逢暴公子，不敢涕流離。"]', '诗', 'shi', '', NULL, '別友人 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d60a1c3d-f288-4adb-a73f-baab5e6bf0a3', '初渡淮北岸', '初渡淮北岸', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["別夢雖難覺，悲魂最易銷。","慇勤淮北岸，鄉近去家遙。"]', '["別梦雖难覺，悲魂最易銷。","慇勤淮北岸，乡近去家遙。"]', '诗', 'shi', '', NULL, '初渡淮北岸 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6641c4c2-33d9-4acc-bc58-41305dd34f1f', '詠雨', '詠雨', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["塵浥多人路，泥歸足燕家。","可憐繚亂點，濕盡滿宮花。"]', '["塵浥多人路，泥归足燕家。","可怜繚亂点，濕尽满宮花。"]', '诗', 'shi', '', NULL, '詠雨 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5b107aa-c8fe-43b3-a3af-631a839b9a40', '柳絮', '柳絮', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["河畔多楊柳，追遊盡狹斜。","春風一回送，亂入莫愁家。"]', '["河畔多楊柳，追游尽狹斜。","春风一回送，亂入莫愁家。"]', '诗', 'shi', '', NULL, '柳絮 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01bcddd1-4f13-4740-9e1f-d2c510188ab7', '花枕', '花枕', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["席上沈香枕，樓中蕩子妻。","那堪一夜裏，長濕兩行啼。"]', '["席上沈香枕，楼中蕩子妻。","那堪一夜裏，长濕兩行啼。"]', '诗', 'shi', '', NULL, '花枕 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79f78a30-4013-4ecf-ac2f-93fa0b234ecb', '送客往鄜州', '送客往鄜州', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["新參將相事營平，錦帶騂弓結束輕。","曉上關城吟畫角，暗馳羗馬發支兵。","回中地近風常急，鄜畤年多草自生。","近喜扶陽係戎相，從來衞霍笑長纓。"]', '["新參將相事營平，錦带騂弓結束轻。","晓上关城吟畫角，暗驰羗马發支兵。","回中地近风常急，鄜畤年多草自生。","近喜扶陽係戎相，從来衞霍笑长纓。"]', '诗', 'shi', '', NULL, '送客往鄜州 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90c8c16c-b673-456c-b482-d21bad5558c1', '送客往夏州', '送客往夏州', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["憐君此去過居延，古塞黃雲共渺然。","沙闊獨行尋馬跡，路迷遙指戍樓煙。","夜投孤店愁吹笛，朝望行塵避控弦。","聞有故交今從騎，何須著論更言錢。"]', '["怜君此去過居延，古塞黄云共渺然。","沙闊独行尋马跡，路迷遙指戍楼煙。","夜投孤店愁吹笛，朝望行塵避控弦。","闻有故交今從騎，何須著論更言錢。"]', '诗', 'shi', '', NULL, '送客往夏州 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd6fa3c6-5532-48c9-b78f-1357dd6e028f', '春霽晚望', '春霽晚望', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["細雨晴深小苑東，春雲開氣逐光風。","雄兒走馬神光上，靜女看花佛寺中。","書劒學多心欲嬾，田園荒廢望頻空。","南歸路極天連海，惟有相思明月同。"]', '["細雨晴深小苑东，春云开氣逐光风。","雄兒走马神光上，静女看花佛寺中。","书劒学多心欲嬾，田园荒廢望頻空。","南归路極天連海，惟有相思明月同。"]', '诗', 'shi', '', NULL, '春霽晚望 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f167222a-2efe-46c5-8fd7-c0d0bc6b0b7c', '唐昌觀玉蘂花', '唐昌观玉蘂花', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["瑤華瓊蘂種何年，蕭史秦嬴向紫煙。","時控綵鸞過舊邸，摘花持獻玉皇前。"]', '["瑤华瓊蘂種何年，蕭史秦嬴向紫煙。","时控綵鸾過旧邸，摘花持獻玉皇前。"]', '诗', 'shi', '', NULL, '唐昌觀玉蘂花 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('466c6b6d-4fd6-4697-8642-1c50e4b45b79', '別李協', '別李協', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["江邊日暮不勝愁，送客霑衣江上樓。","明月峽添明月照，蛾眉峰似兩眉愁。"]', '["江邊日暮不勝愁，送客霑衣江上楼。","明月峽添明月照，蛾眉峰似兩眉愁。"]', '诗', 'shi', '', NULL, '別李協 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3499130a-78e3-42fb-8295-74bcd068d288', '初次巴陵', '初次巴陵', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["西江浪接洞庭波，積水遙連天上河。","鄉信爲憑誰寄去，汀洲燕雁漸來多。"]', '["西江浪接洞庭波，積水遙連天上河。","乡信爲憑誰寄去，汀洲燕雁漸来多。"]', '诗', 'shi', '', NULL, '初次巴陵 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82b82749-a034-4ad1-97d2-ed361b75885c', '上巳', '上巳', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["帝京元巳足繁華，細管清弦七貴家。","此日風光誰不共，紛紛皆是掖垣花。"]', '["帝京元巳足繁华，細管清弦七貴家。","此日风光誰不共，紛紛皆是掖垣花。"]', '诗', 'shi', '', NULL, '上巳 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('655946f1-eda9-469c-bc5b-da8dc465e9cf', '春怨', '春怨', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["花滿簾櫳欲度春，此時夫壻在咸秦。","綠窗孤寢難成寐，紫燕雙飛似弄人。"]', '["花满簾櫳欲度春，此时夫壻在咸秦。","綠窗孤寢难成寐，紫燕雙飞似弄人。"]', '诗', 'shi', '', NULL, '春怨 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a460c51f-1465-405f-b18b-6a295413054b', '送客歸常州', '送客归常州', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["行到河邊從此辭，寒天日遠暮帆遲。","可憐芳草成衰草，公子歸時過綠時。"]', '["行到河邊從此辞，寒天日远暮帆遲。","可怜芳草成衰草，公子归时過綠时。"]', '诗', 'shi', '', NULL, '送客歸常州 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73c24a9a-197c-4f48-a062-9083b6566ad6', '送別', '送別', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["春愁不盡別愁來，舊淚猶長新淚催。","相思倘寄相思字，君到揚州揚子迴。"]', '["春愁不尽別愁来，旧泪猶长新泪催。","相思倘寄相思字，君到揚州揚子迴。"]', '诗', 'shi', '', NULL, '送別 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f36603e-7e41-4fbe-ab85-1ac0c7ad6ccd', '送客入蜀', '送客入蜀', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["劒閣迢迢夢想間，行人歸路遶梁山。","明朝騎馬搖鞭去，秋雨槐花子午關。"]', '["劒閣迢迢梦想间，行人归路遶梁山。","明朝騎马搖鞭去，秋雨槐花子午关。"]', '诗', 'shi', '', NULL, '送客入蜀 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50438e66-8665-4453-ba9c-3446251de626', '送別', '送別', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["仙花笑盡石門中，石室重重掩綠空。","蹔下雲峰能幾日，却迴煙駕馭春風。"]', '["仙花笑尽石门中，石室重重掩綠空。","蹔下云峰能幾日，却迴煙駕馭春风。"]', '诗', 'shi', '', NULL, '送別 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93be035d-9976-4033-a47f-5330fa8bea20', '殘花', '殘花', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["五馬踟躕在路岐，南來只爲看花枝。","鶯銜蝶弄紅芳盡，此日深閨那得知。"]', '["五马踟躕在路岐，南来只爲看花枝。","鶯銜蝶弄紅芳尽，此日深閨那得知。"]', '诗', 'shi', '', NULL, '殘花 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00701b63-8026-4375-bb72-1163b291e5e3', '戲贈友人', '戲贈友人', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["湘陰直與地陰連，此日相逢憶醉年。","美酒非如平樂貴，十升不用一千錢。"]', '["湘陰直與地陰連，此日相逢憶醉年。","美酒非如平乐貴，十升不用一千錢。"]', '诗', 'shi', '', NULL, '戲贈友人 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29f41c00-2f43-47cc-99dc-b4749beef2fc', '贈同遊', '贈同游', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["此囗風雨後，已覺減年華。","若待皆無事，應難更有花。","管弦臨夜急，榆柳向江斜。","且莫看歸路，同須醉酒家。"]', '["此囗风雨後，已覺減年华。","若待皆無事，應难更有花。","管弦臨夜急，榆柳向江斜。","且莫看归路，同須醉酒家。"]', '诗', 'shi', '', NULL, '贈同遊 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a7a2237-9f1c-485e-a2b7-10d862ff7349', '送人出塞', '送人出塞', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["北風吹雨雪，舉目已悽悽。","戰鬼秋頻哭，征鴻夜不棲。","沙平關路直，磧廣郡樓低。","此去非東魯，人多事鼓鼙。"]', '["北风吹雨雪，舉目已悽悽。","戰鬼秋頻哭，征鴻夜不棲。","沙平关路直，磧廣郡楼低。","此去非东魯，人多事鼓鼙。"]', '诗', 'shi', '', NULL, '送人出塞 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e3da629-3127-4806-a3d9-ffdc1162bfa3', '尋僧元皎因病', '尋僧元皎因病', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["此僧迷友著，因病得尋師。","話盡山中事，歸當月上時。","高松連寺影，亞竹入窗枝。","閑憶草堂路，相逢非素期。"]', '["此僧迷友著，因病得尋師。","話尽山中事，归當月上时。","高松連寺影，亞竹入窗枝。","闲憶草堂路，相逢非素期。"]', '诗', 'shi', '', NULL, '尋僧元皎因病 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af5656ce-7ca5-4e01-b650-6187500120b2', '夜泊渭津', '夜泊渭津', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["飄飄東去客，一宿渭城邊。","遠處星垂岸，中流月滿船。","涼歸夜深簟，秋入雨餘天。","漸覺家山小，殘程尚幾年。"]', '["飄飄东去客，一宿渭城邊。","远处星垂岸，中流月满船。","涼归夜深簟，秋入雨餘天。","漸覺家山小，殘程尚幾年。"]', '诗', 'shi', '', NULL, '夜泊渭津 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4759caa1-7eea-4a67-9fa5-6cc614c69f4a', '晚夏逢友人', '晚夏逢友人', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["一別同袍友，相思已十年。","長安多在客，久病忽聞蟬。","驟雨纔沾地，陰雲不徧天。","微涼堪話舊，移榻晚風前。"]', '["一別同袍友，相思已十年。","长安多在客，久病忽闻蟬。","驟雨纔沾地，陰云不徧天。","微涼堪話旧，移榻晚风前。"]', '诗', 'shi', '', NULL, '晚夏逢友人 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4e287f1-f101-4d55-8448-1f73442ef2f5', '別謫者', '別謫者', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["此地聞猶惡，人言是所之。","一家書絕久，孤驛夢成遲。","八月三湘道，聞猨冒雨時。","不須祠楚相，臣節轉堪疑。"]', '["此地闻猶惡，人言是所之。","一家书絕久，孤驛梦成遲。","八月三湘道，闻猨冒雨时。","不須祠楚相，臣節轉堪疑。"]', '诗', 'shi', '', NULL, '別謫者 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('475caaa3-edca-4365-b4d8-f7dfba41ea1c', '行思', '行思', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["千里豈云去，欲歸如路窮。","人間無暇日，馬上又秋風。","破月銜高岳，流星拂曉空。","此時皆在夢，行色獨怱怱。"]', '["千里豈云去，欲归如路窮。","人间無暇日，马上又秋风。","破月銜高岳，流星拂晓空。","此时皆在梦，行色独怱怱。"]', '诗', 'shi', '', NULL, '行思 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e43784bb-279b-4196-ba5a-1c919ee80aeb', '感懷題從舅宅', '感懷題從舅宅', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["郗家庭樹下，幾度醉春風。","今日花還發，當時事不同。","流言應未息，直道竟難通。","徒遣相思者，悲歌向暮空。"]', '["郗家庭樹下，幾度醉春风。","今日花還發，當时事不同。","流言應未息，直道竟难通。","徒遣相思者，悲歌向暮空。"]', '诗', 'shi', '', NULL, '感懷題從舅宅 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9ed41c1-862e-4dea-af90-f5de5a02e814', '與友人會', '與友人會', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["蟬吟槐蘂落，的的是愁端。","病覺離家遠，貧知處事難。","真交無所隱，深語有餘歡。","未必聞歌吹，羈心得蹔寬。"]', '["蟬吟槐蘂落，的的是愁端。","病覺離家远，貧知处事难。","真交無所隐，深語有餘歡。","未必闻歌吹，羈心得蹔寬。"]', '诗', 'shi', '', NULL, '與友人會 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9de3db08-aaf6-42aa-96f5-a9af3dcb7526', '下第後蒙侍郎示意指於新先輩宣恩感謝', '下第後蒙侍郎示意指於新先輩宣恩感謝', '13d123dd-24ec-4a44-ba33-867392db91d3', '唐', '["才薄命如此，自嗟兼自疑。","遭逢好交日，黜落至公時。","倚玉甘無路，穿楊却未期。","更慙君侍坐，問許可言詩。"]', '["才薄命如此，自嗟兼自疑。","遭逢好交日，黜落至公时。","倚玉甘無路，穿楊却未期。","更慙君侍坐，问許可言诗。"]', '诗', 'shi', '', NULL, '下第後蒙侍郎示意指於新先輩宣恩感謝 楊凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2502eef1-d7b2-4d3d-b4b8-ada2d713b03d', '奉酬韋滁州寄示', '奉酬韋滁州寄示', 'fea2b6c2-6dc5-4fcc-9280-4c1f6da537df', '唐', '["淮揚爲郡暇，坐惜流芳歇。","散懷累榭風，清暑澄潭月。","陪燕辭三楚，戒途綿百越。","非當遠別離，雅奏何由發。"]', '["淮揚爲郡暇，坐惜流芳歇。","散懷累榭风，清暑澄潭月。","陪燕辞三楚，戒途綿百越。","非當远別離，雅奏何由發。"]', '诗', 'shi', '', NULL, '奉酬韋滁州寄示 楊凌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b10851b9-e6cb-41eb-979a-c897ccaac1df', '梅里旅夕', '梅里旅夕', 'fea2b6c2-6dc5-4fcc-9280-4c1f6da537df', '唐', '["滄洲東望路，旅櫂愴羈遊。","楓浦蟬隨岸，沙汀鷗轉流。","露天星上月，水國夜生秋。","誰忍持相憶，南歸一葉舟。"]', '["滄洲东望路，旅櫂愴羈游。","楓浦蟬隨岸，沙汀鷗轉流。","露天星上月，水国夜生秋。","誰忍持相憶，南归一葉舟。"]', '诗', 'shi', '', NULL, '梅里旅夕 楊凌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70ceb718-ac98-4a19-b8c7-652a3d2b6c5f', '鍾陵雪夜詶友人', '鍾陵雪夜詶友人', 'fea2b6c2-6dc5-4fcc-9280-4c1f6da537df', '唐', '["窮臘催年急，陽春怯和歌。","殘燈閃壁盡，夜雪透窗多。","歸路山川險，遊人夢寐過。","龍洲不可泊，歲晚足驚波。"]', '["窮臘催年急，陽春怯和歌。","殘灯閃壁尽，夜雪透窗多。","归路山川險，游人梦寐過。","龙洲不可泊，歲晚足驚波。"]', '诗', 'shi', '', NULL, '鍾陵雪夜詶友人 楊凌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61b7672c-004e-42c9-815d-6b311e1492b6', '潤州水樓', '潤州水楼', 'fea2b6c2-6dc5-4fcc-9280-4c1f6da537df', '唐', '["歸心不可留，雪桂一叢秋。","葉雨空江月，螢飛白露洲。","野蟬依獨樹，水郭帶孤樓。","遙望山川路，相思萬里遊。"]', '["归心不可留，雪桂一叢秋。","葉雨空江月，螢飞白露洲。","野蟬依独樹，水郭带孤楼。","遙望山川路，相思万里游。"]', '诗', 'shi', '', NULL, '潤州水樓 楊凌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae47f2c3-d219-43ed-8fa4-38f376e4ab7e', '江上秋月', '江上秋月', 'fea2b6c2-6dc5-4fcc-9280-4c1f6da537df', '唐', '["隴雁送鄉心，羈情屬歲陰。","驚秋黃葉遍，愁暮碧雲深。","月色吳江上，風聲楚木林。","交親幾重別，歸夢併愁侵。"]', '["隴雁送乡心，羈情屬歲陰。","驚秋黄葉遍，愁暮碧云深。","月色吳江上，风声楚木林。","交親幾重別，归梦併愁侵。"]', '诗', 'shi', '', NULL, '江上秋月 楊凌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1ea1885-1c8e-4c3f-abf4-829c989b8058', '閣前雙槿', '閣前雙槿', 'fea2b6c2-6dc5-4fcc-9280-4c1f6da537df', '唐', '["羣玉開雙槿，丹榮對絳紗。","含煙疑出火，隔雨怪舒霞。","向晚爭辭蘂，迎朝鬬發花。","非關後桃李，爲欲繼年華。"]', '["羣玉开雙槿，丹榮对絳紗。","含煙疑出火，隔雨怪舒霞。","向晚爭辞蘂，迎朝鬬發花。","非关後桃李，爲欲繼年华。"]', '诗', 'shi', '', NULL, '閣前雙槿 楊凌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59df755e-5961-4146-80e9-e15c9cedea8a', '小苑春望宮池柳色', '小苑春望宮池柳色', 'fea2b6c2-6dc5-4fcc-9280-4c1f6da537df', '唐', '["上苑閑游早，東風柳色輕。","儲胥遙掩映，池水隔微明。","春至條偏弱，寒餘葉未成。","和煙變濃淡，轉日異陰晴。","不獨芳菲好，還因雨露榮。","行人望攀折，遠翠暮愁生。"]', '["上苑闲游早，东风柳色轻。","儲胥遙掩映，池水隔微明。","春至條偏弱，寒餘葉未成。","和煙变濃淡，轉日異陰晴。","不独芳菲好，還因雨露榮。","行人望攀折，远翠暮愁生。"]', '诗', 'shi', '', NULL, '小苑春望宮池柳色 楊凌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7d5356c-0563-4a3a-8d01-c363ca8362b0', '送客往睦州', '送客往睦州', 'fea2b6c2-6dc5-4fcc-9280-4c1f6da537df', '唐', '["水闊盡南天，孤舟去渺然。","驚秋路傍客，日暮數聲蟬。"]', '["水闊尽南天，孤舟去渺然。","驚秋路傍客，日暮數声蟬。"]', '诗', 'shi', '', NULL, '送客往睦州 楊凌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e82dfaab-abac-499f-a438-8258a87ac7ce', '送客之蜀', '送客之蜀', 'fea2b6c2-6dc5-4fcc-9280-4c1f6da537df', '唐', '["西蜀三千里，巴南水一方。","曉雲天際斷，夜月峽中長。"]', '["西蜀三千里，巴南水一方。","晓云天際斷，夜月峽中长。"]', '诗', 'shi', '', NULL, '送客之蜀 楊凌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc1c773f-6b56-4f23-a682-0eff52500a4d', '剡溪看花', '剡溪看花', 'fea2b6c2-6dc5-4fcc-9280-4c1f6da537df', '唐', '["花落千廻舞，鶯聲百囀歌。","還同異方樂，不奈客愁多。"]', '["花落千廻舞，鶯声百囀歌。","還同異方乐，不奈客愁多。"]', '诗', 'shi', '', NULL, '剡溪看花 楊凌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbab6661-1d07-4485-86d3-d0b6e6a9159d', '江中風', '江中风', 'fea2b6c2-6dc5-4fcc-9280-4c1f6da537df', '唐', '["白浪暗江中，南泠路不通。","高檣帆自滿，出浦莫呼風。"]', '["白浪暗江中，南泠路不通。","高檣帆自满，出浦莫呼风。"]', '诗', 'shi', '', NULL, '江中風 楊凌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b537a242-f109-4ced-bbba-4cea3b3db597', '詠破扇', '詠破扇', 'fea2b6c2-6dc5-4fcc-9280-4c1f6da537df', '唐', '["粉落空牀棄，塵生故篋留。","先來無一半，情斷不勝愁。"]', '["粉落空牀棄，塵生故篋留。","先来無一半，情斷不勝愁。"]', '诗', 'shi', '', NULL, '詠破扇 楊凌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c24ce06f-f490-4466-92ea-dd991a4ed4ca', '賈客愁', '賈客愁', 'fea2b6c2-6dc5-4fcc-9280-4c1f6da537df', '唐', '["山水路悠悠，逢灘即殢留。","西江風未便，何日到荆州。"]', '["山水路悠悠，逢灘即殢留。","西江风未便，何日到荆州。"]', '诗', 'shi', '', NULL, '賈客愁 楊凌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d98880f6-8f83-4a02-9fc7-94dca8c9fed9', '即事寄人', '即事寄人', 'fea2b6c2-6dc5-4fcc-9280-4c1f6da537df', '唐', '["中禁鳴鐘日欲高，北窗欹枕望頻搔。","相思寂寞青苔合，唯有春風啼伯勞。"]', '["中禁鳴鐘日欲高，北窗欹枕望頻搔。","相思寂寞青苔合，唯有春风啼伯勞。"]', '诗', 'shi', '', NULL, '即事寄人 楊凌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95364c77-2a32-47e0-a5f8-78f13ecdbcf1', '早春雪中', '早春雪中', 'fea2b6c2-6dc5-4fcc-9280-4c1f6da537df', '唐', '["新年雨雪少晴時，屢失尋梅看柳期。","鄉信憶隨回鴈早，江春寒帶故陰遲。"]', '["新年雨雪少晴时，屢失尋梅看柳期。","乡信憶隨回鴈早，江春寒带故陰遲。"]', '诗', 'shi', '', NULL, '早春雪中 楊凌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5770b5d6-3ea9-443a-8159-14d2b05771f6', '北行留別', '北行留別', 'fea2b6c2-6dc5-4fcc-9280-4c1f6da537df', '唐', '["日日山川烽火頻，山河重起舊煙塵。","一生孤負龍泉劒，羞把詩書問故人。"]', '["日日山川烽火頻，山河重起旧煙塵。","一生孤負龙泉劒，羞把诗书问故人。"]', '诗', 'shi', '', NULL, '北行留別 楊凌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32f64e23-40d7-4bd1-a43b-5a94c6d57438', '秋原野望', '秋原野望', 'fea2b6c2-6dc5-4fcc-9280-4c1f6da537df', '唐', '["客鴈秋來次第逢，家書頻寄兩三封。","夕陽天外雲歸盡，亂見青山無數峰。"]', '["客鴈秋来次第逢，家书頻寄兩三封。","夕陽天外云归尽，亂见青山無數峰。"]', '诗', 'shi', '', NULL, '秋原野望 楊凌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7daf85fe-c509-48fd-b923-77dc3b2bb173', '春霽花萼樓南聞宮鶯', '春霽花萼楼南闻宮鶯', 'fea2b6c2-6dc5-4fcc-9280-4c1f6da537df', '唐', '["祥煙瑞氣曉來輕，柳變花開共作晴。","黃鳥遠啼鳷鵲觀，春風流出鳳皇城。"]', '["祥煙瑞氣晓来轻，柳变花开共作晴。","黄鸟远啼鳷鵲观，春风流出鳳皇城。"]', '诗', 'shi', '', NULL, '春霽花萼樓南聞宮鶯 楊凌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8750bb8c-7de6-40b9-9da8-721df21f8573', '明妃怨', '明妃怨', 'fea2b6c2-6dc5-4fcc-9280-4c1f6da537df', '唐', '["漢國明妃去不還，馬馱絃管向陰山。","匣中縱有菱花鏡，羞對單于照舊顏。"]', '["漢国明妃去不還，马馱絃管向陰山。","匣中縱有菱花镜，羞对單于照旧顏。"]', '诗', 'shi', '', NULL, '明妃怨 楊凌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c76b3d42-b78a-45aa-8bf3-642c9573ef01', '句', '句', 'fea2b6c2-6dc5-4fcc-9280-4c1f6da537df', '唐', '["南園桃李花落盡，春風寂寞搖空枝。"]', '["南园桃李花落尽，春风寂寞搖空枝。"]', '诗', 'shi', '', NULL, '句 楊凌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb5923a0-e11c-466e-94ff-1b71c60e7efa', '題玉真觀公主山池院', '題玉真观公主山池院', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["香殿留遺影，春朝玉戶開。","羽衣重素几，珠網儼輕埃。","石自蓬山得，泉經太液來。","柳絲遮綠浪，花粉落青苔。","鏡掩鸞空在，霞消鳳不迴。","唯餘古桃樹，傳是上仙栽。"]', '["香殿留遺影，春朝玉戶开。","羽衣重素几，珠網儼轻埃。","石自蓬山得，泉經太液来。","柳絲遮綠浪，花粉落青苔。","镜掩鸾空在，霞消鳳不迴。","唯餘古桃樹，傳是上仙栽。"]', '诗', 'shi', '', NULL, '題玉真觀公主山池院 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07c96e92-8589-4e1b-9c90-44feedbaca48', '送永陽崔明府', '送永陽崔明府', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["古國羣舒地，前當桐柏關。","連綿江上雨，稠疊楚南山。","沙館行帆息，楓洲候吏還。","乘籃若有暇，精舍在林間。"]', '["古国羣舒地，前當桐柏关。","連綿江上雨，稠叠楚南山。","沙館行帆息，楓洲候吏還。","乘籃若有暇，精舍在林间。"]', '诗', 'shi', '', NULL, '送永陽崔明府 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47f5d0d8-cd03-4b71-a545-eedb1ceac627', '送曹三同猗遊山寺', '送曹三同猗游山寺', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["山蹋青蕪盡，涼秋古寺深。","何時得連策，此夜更聞琴。","窮水雲同穴，過僧虎共林。","殷勤如念我，遺爾挂冠心。"]', '["山蹋青蕪尽，涼秋古寺深。","何时得連策，此夜更闻琴。","窮水云同穴，過僧虎共林。","殷勤如念我，遺爾挂冠心。"]', '诗', 'shi', '', NULL, '送曹三同猗遊山寺 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0659c894-8128-4d41-8136-e7afac1dcc33', '送崔校書赴梓幕', '送崔校书赴梓幕', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["碧峯天柱下，鼓角鎮南軍。","管記催飛檄，蓬萊輟校文。","棧霜朝似雪，江霧晚成雲。","想出褒中望，巴庸方路分。"]', '["碧峯天柱下，鼓角鎮南軍。","管記催飞檄，蓬萊輟校文。","棧霜朝似雪，江霧晚成云。","想出褒中望，巴庸方路分。"]', '诗', 'shi', '', NULL, '送崔校書赴梓幕 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cd63a0f-a484-4880-8a5e-d80ca885d868', '送夔州班使君', '送夔州班使君', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["魚國巴庸路，麾幢漢守過。","曉檣爭市隘，夜鼓祭神多。","雲白當山雨，風清滿峽波。","夷陵舊人吏，猶誦兩岐歌。"]', '["鱼国巴庸路，麾幢漢守過。","晓檣爭市隘，夜鼓祭神多。","云白當山雨，风清满峽波。","夷陵旧人吏，猶誦兩岐歌。"]', '诗', 'shi', '', NULL, '送夔州班使君 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('420fad84-9a0a-4718-a809-493e7845cd9f', '送菊潭王明府', '送菊潭王明府', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["業成洙泗客，皓髮著儒衣。","一與遊人別，仍聞帶印歸。","林多宛地古，雲盡漢山稀。","莫愛潯陽隱，嫌官計亦非。"]', '["業成洙泗客，皓髮著儒衣。","一與游人別，仍闻带印归。","林多宛地古，云尽漢山稀。","莫愛潯陽隐，嫌官計亦非。"]', '诗', 'shi', '', NULL, '送菊潭王明府 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8d8ad3c-2eed-41f8-bf50-6e980e4f4eb4', '送太易上人赴東洛', '送太易上人赴东洛', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["遙見登山處，青蕪雪後春。","雲深岳廟火，寺宿洛陽人。","餌藥將齋折，唯詩與道親。","凡經幾回別，麈尾不離身。"]', '["遙见登山处，青蕪雪後春。","云深岳廟火，寺宿洛陽人。","餌藥將斋折，唯诗與道親。","凡經幾回別，麈尾不離身。"]', '诗', 'shi', '', NULL, '送太易上人赴東洛 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c9a2f78-0607-4a59-a2ee-018a2d391dd3', '和王卿立秋即事', '和王卿立秋即事', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["秋宜何處看，試問白雲官。","暗入蟬鳴樹，微侵蝶繞蘭。","向風涼稍動，近日暑猶殘。","九陌浮埃減，千峯爽氣攢。","換衣防竹暮，沈果訝泉寒。","宮響傳花杵，天清出露盤。","高禽當側弁，遊鮪對憑欄。","一奏招商曲，空令繼唱難。"]', '["秋宜何处看，試问白云官。","暗入蟬鳴樹，微侵蝶繞蘭。","向风涼稍动，近日暑猶殘。","九陌浮埃減，千峯爽氣攢。","換衣防竹暮，沈果訝泉寒。","宮响傳花杵，天清出露盤。","高禽當側弁，游鮪对憑欄。","一奏招商曲，空令繼唱难。"]', '诗', 'shi', '', NULL, '和王卿立秋即事 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b653bd7-8c7e-4265-ab0d-c9fc76da8b1d', '和李員外與舍人詠玫瑰花寄徐侍郎', '和李員外與舍人詠玫瑰花寄徐侍郎', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["仙吏紫薇郎，奇花共翫芳。","攢星排綠蒂，照眼發紅光。","暗妬翻堦藥，遙連直署香。","遊枝蜂繞易，礙刺鳥銜妨。","露溼凝衣粉，風吹散蕊黃。","蒙蘢珠樹合，煥爛錦屏張。","留客勝看竹，思人比愛棠。","如傳採蘋詠，遠思滿瀟湘。"]', '["仙吏紫薇郎，奇花共翫芳。","攢星排綠蒂，照眼發紅光。","暗妬翻堦藥，遙連直署香。","游枝蜂繞易，礙刺鸟銜妨。","露溼凝衣粉，风吹散蕊黄。","蒙蘢珠樹合，煥爛錦屏張。","留客勝看竹，思人比愛棠。","如傳採蘋詠，远思满瀟湘。"]', '诗', 'shi', '', NULL, '和李員外與舍人詠玫瑰花寄徐侍郎 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('154b41e2-072d-4b2d-8c65-97cbed3f25f4', '冬夜耿拾遺王秀才就宿因傷故人', '冬夜耿拾遺王秀才就宿因傷故人', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["舊時聞笛淚，今夜重沾衣。","方恨同人少，何堪相見稀。","竹煙凝澗壑，林雪似芳菲。","多謝勞車馬，應憐獨掩扉。"]', '["旧时闻笛泪，今夜重沾衣。","方恨同人少，何堪相见稀。","竹煙凝澗壑，林雪似芳菲。","多謝勞车马，應怜独掩扉。"]', '诗', 'shi', '', NULL, '冬夜耿拾遺王秀才就宿因傷故人 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac86261f-08ed-47a0-b127-e776f59d0998', '早春遊慈恩南池', '早春游慈恩南池', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["山寺臨池水，春愁望遠生。","蹋橋逢鶴起，尋竹值泉橫。","新柳絲猶短，輕蘋葉未成。","還如虎溪上，日暮伴僧行。"]', '["山寺臨池水，春愁望远生。","蹋橋逢鹤起，尋竹值泉橫。","新柳絲猶短，轻蘋葉未成。","還如虎溪上，日暮伴僧行。"]', '诗', 'shi', '', NULL, '早春遊慈恩南池 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71862ef7-dc20-401d-a624-f079b6a089b9', '雨夜見投之作', '雨夜见投之作', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["出戶繁星盡，池塘暗不開。","動衣涼氣度，遰樹遠聲來。","燈外初行電，城隅偶隱雷。","因知謝文學，曉望比塵埃。"]', '["出戶繁星尽，池塘暗不开。","动衣涼氣度，遰樹远声来。","灯外初行電，城隅偶隐雷。","因知謝文学，晓望比塵埃。"]', '诗', 'shi', '', NULL, '雨夜見投之作 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('648d56c4-71c8-4613-96bb-c1a7e960c20b', '龍池寺望月寄韋使君閻別駕', '龙池寺望月寄韋使君閻別駕', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["清光此夜中，萬古望應同。","當野山沈霧，低城樹有風。","花宮紛共邃，水府皓相空。","遙想高樓上，唯君對庾公。"]', '["清光此夜中，万古望應同。","當野山沈霧，低城樹有风。","花宮紛共邃，水府皓相空。","遙想高楼上，唯君对庾公。"]', '诗', 'shi', '', NULL, '龍池寺望月寄韋使君閻別駕 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03eab4c0-f265-4545-9574-b9ebdda83b98', '秋夜憶興善院寄苗發', '秋夜憶兴善院寄苗發', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["右軍多住寺，此夜後池秋。","自與山僧伴，那因洛客愁。","卷簾霜靄靄，滿目水悠悠。","若有詩相贈，期君憶惠休。"]', '["右軍多住寺，此夜後池秋。","自與山僧伴，那因洛客愁。","卷簾霜靄靄，满目水悠悠。","若有诗相贈，期君憶惠休。"]', '诗', 'shi', '', NULL, '秋夜憶興善院寄苗發 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc7e7b02-fa9a-4405-8922-d2fbcba58136', '病中寄鄭十六兄', '病中寄鄭十六兄', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["倦枕欲徐行，開簾秋月明。","手便筇杖冷，頭喜葛巾輕。","綠草前侵水，黃花半上城。","虛消此塵景，不見十年兄。"]', '["倦枕欲徐行，开簾秋月明。","手便筇杖冷，头喜葛巾轻。","綠草前侵水，黄花半上城。","虛消此塵景，不见十年兄。"]', '诗', 'shi', '', NULL, '病中寄鄭十六兄 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04e6eb11-0b8c-4b26-ae73-2c7dc13845dc', '衞明府寄枇杷葉以詩荅', '衞明府寄枇杷葉以诗荅', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["傾筐呈綠葉，重疊色何鮮。","詎是秋風裏，猶如曉露前。","仙方當見重，消疾本應便。","全勝甘蕉贈，空投謝氏篇。"]', '["傾筐呈綠葉，重叠色何鲜。","詎是秋风裏，猶如晓露前。","仙方當见重，消疾本應便。","全勝甘蕉贈，空投謝氏篇。"]', '诗', 'shi', '', NULL, '衞明府寄枇杷葉以詩荅 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ba99fff-5db9-4e38-9f05-6e4466a2c150', '過慶寶寺', '過慶寶寺', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["黃葉前朝寺，無僧寒殿開。","池晴龜出曝，松暮鶴飛迴。","古井碑橫草，陰廊畫雜苔。","禪宮亦銷歇，塵世轉堪哀。"]', '["黄葉前朝寺，無僧寒殿开。","池晴龟出曝，松暮鹤飞迴。","古井碑橫草，陰廊畫杂苔。","禪宮亦銷歇，塵世轉堪哀。"]', '诗', 'shi', '', NULL, '過慶寶寺 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aff1a3de-cbb5-4c81-bdbb-a49b5526d5d6', '奉和張大夫酬高山人', '奉和張大夫酬高山人', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["野客居鈴閣，重門將校稀。","豸冠親穀弁，龜印識荷衣。","座右寒飆爽，談餘暮角微。","蒼生須太傅，山在豈容歸。"]', '["野客居鈴閣，重门將校稀。","豸冠親穀弁，龟印識荷衣。","座右寒飆爽，談餘暮角微。","蒼生須太傅，山在豈容归。"]', '诗', 'shi', '', NULL, '奉和張大夫酬高山人 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e582786-a770-48c0-b971-06e4a84788dc', '送嚴使君遊山', '送嚴使君游山', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["家楚依三戶，辭州選一錢。","酒杯同寄世，客櫂任銷年。","赤燒兼山遠，青蕪與浪連。","青春明月夜，知上鄂君船。"]', '["家楚依三戶，辞州選一錢。","酒杯同寄世，客櫂任銷年。","赤燒兼山远，青蕪與浪連。","青春明月夜，知上鄂君船。"]', '诗', 'shi', '', NULL, '送嚴使君遊山 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47b2a70e-f226-4aef-9b58-06f835751cab', '送柳震歸蜀', '送柳震归蜀', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["白日雙流靜，西看蜀國春。","桐花能乳鳥，竹節競祠神。","蹇步徒相望，先鞭不可親。","知從江僕射，登榻更何人。"]', '["白日雙流静，西看蜀国春。","桐花能乳鸟，竹節競祠神。","蹇步徒相望，先鞭不可親。","知從江僕射，登榻更何人。"]', '诗', 'shi', '', NULL, '送柳震歸蜀 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a080ba0c-380b-4d9c-abc4-b2f3d092e627', '送樂平苗明府', '送乐平苗明府', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["天際山多處，東安古邑深。","綠田通竹里，白浪隔楓林。","詩有江僧和，門唯越客尋。","應將放魚化，一境表吾心。"]', '["天際山多处，东安古邑深。","綠田通竹里，白浪隔楓林。","诗有江僧和，门唯越客尋。","應將放鱼化，一境表吾心。"]', '诗', 'shi', '', NULL, '送樂平苗明府 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19eabf31-3e26-479c-a0d1-1345d86cca1d', '贈送鄭錢二郎中', '贈送鄭錢二郎中', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["梅含柳已動，昨日起東風。","惆悵心徒壯，無如鬢作翁。","百年飄若水，萬緒盡歸空。","何可宗禪客，遲迴岐路中。"]', '["梅含柳已动，昨日起东风。","惆悵心徒壯，無如鬢作翁。","百年飄若水，万緒尽归空。","何可宗禪客，遲迴岐路中。"]', '诗', 'shi', '', NULL, '贈送鄭錢二郎中 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('299c887a-8188-4e6e-ba09-b0df94161482', '酬鄭十四望驛不得同宿見贈因寄張參軍', '酬鄭十四望驛不得同宿见贈因寄張參軍', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["逢君喜成淚，暫似故鄉中。","謫宦猶多懼，清宵不得終。","月煙高有鶴，宿草淨無蟲。","明日郄超會，應思下客同。"]', '["逢君喜成泪，暫似故乡中。","謫宦猶多懼，清宵不得終。","月煙高有鹤，宿草淨無蟲。","明日郄超會，應思下客同。"]', '诗', 'shi', '', NULL, '酬鄭十四望驛不得同宿見贈因寄張參軍 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('082b82f8-8cf1-4c6b-9eef-384135b4b898', '暮春野望寄錢起', '暮春野望寄錢起', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["草長花落樹，羸病強尋春。","無復少年意，空餘華髮新。","青原高見水，白社靜逢人。","寄謝南宮客，軒車不可親。"]', '["草长花落樹，羸病強尋春。","無复少年意，空餘华髮新。","青原高见水，白社静逢人。","寄謝南宮客，軒车不可親。"]', '诗', 'shi', '', NULL, '暮春野望寄錢起 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8235ff36-99aa-4a40-a364-7a3001c2d0c4', '送王使君小子孝廉登科歸省', '送王使君小子孝廉登科归省', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["年少通經學，登科尚佩觿。","張馮本名士，蔡廓是佳兒。","鞍馬臨岐路，龍鍾對別離。","寄書胡太守，請與故人知。"]', '["年少通經学，登科尚佩觿。","張馮本名士，蔡廓是佳兒。","鞍马臨岐路，龙鍾对別離。","寄书胡太守，請與故人知。"]', '诗', 'shi', '', NULL, '送王使君小子孝廉登科歸省 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('813ba0d9-9978-4a68-b5b1-9cd1e9ee82ff', '雲陽寺石竹花', '云陽寺石竹花', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["一自幽山別，相逢此寺中。","高低俱出葉，深淺不分叢。","野蝶難爭白，庭榴暗讓紅。","誰憐芳最久，春露到秋風。"]', '["一自幽山別，相逢此寺中。","高低俱出葉，深淺不分叢。","野蝶难爭白，庭榴暗讓紅。","誰怜芳最久，春露到秋风。"]', '诗', 'shi', '', NULL, '雲陽寺石竹花 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb1b0816-697c-4727-bd4a-f9392b3c4a88', '送高勝重謁曹王', '送高勝重謁曹王', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["江上青楓岸，陰陰萬里春。","朝辭郢城酒，暮見洞庭人。","興比乘舟訪，恩懷倒屣親。","想君登舊榭，重喜掃芳塵。"]', '["江上青楓岸，陰陰万里春。","朝辞郢城酒，暮见洞庭人。","兴比乘舟訪，恩懷倒屣親。","想君登旧榭，重喜掃芳塵。"]', '诗', 'shi', '', NULL, '送高勝重謁曹王 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f23af48-ed87-40b3-bbfd-2824769aa0ae', '閑園書事招暢當', '闲园书事招暢當', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["聞蟬晝眠後，欹枕對蓬蒿。","羸病嬾尋戴，田園方詠陶。","傍簷蟲挂靜，出樹蝶飛高。","惆悵臨清鏡，思君見鬢毛。"]', '["闻蟬晝眠後，欹枕对蓬蒿。","羸病嬾尋戴，田园方詠陶。","傍簷蟲挂静，出樹蝶飞高。","惆悵臨清镜，思君见鬢毛。"]', '诗', 'shi', '', NULL, '閑園書事招暢當 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c1a6bd0-a7fc-4485-97ce-040b34633957', '過錢員外', '過錢員外', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["爲郎頭已白，跡向市朝稀。","移病居荒宅，安貧著敗衣。","野園隨客醉，雪寺伴僧歸。","自說東峯下，松蘿滿故扉。"]', '["爲郎头已白，跡向市朝稀。","移病居荒宅，安貧著敗衣。","野园隨客醉，雪寺伴僧归。","自说东峯下，松蘿满故扉。"]', '诗', 'shi', '', NULL, '過錢員外 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b3cc904-7ddc-4f52-9bf1-4b222cbe804b', '贈庾侍御', '贈庾侍御', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["年少身無累，相逢憶此時。","雪過雲寺宿，酒向竹園期。","白髮今催老，清琴但起悲。","唯應逐宗炳，內學願爲師。"]', '["年少身無累，相逢憶此时。","雪過云寺宿，酒向竹园期。","白髮今催老，清琴但起悲。","唯應逐宗炳，內学願爲師。"]', '诗', 'shi', '', NULL, '贈庾侍御 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cbfbe28-770f-4a19-ab6d-d97df02d83a7', '贈李端', '贈李端', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["共憶南浮日，登高望若何。","楚田湖草遠，江寺海榴多。","載酒尋山宿，思人帶雪過。","東西幾回別，此會各磋砣。"]', '["共憶南浮日，登高望若何。","楚田湖草远，江寺海榴多。","載酒尋山宿，思人带雪過。","东西幾回別，此會各磋砣。"]', '诗', 'shi', '', NULL, '贈李端 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6be2f191-b7c7-4861-9212-88a2eb7a5723', '送流人', '送流人', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["聞說南中事，悲君重竄身。","山村楓子鬼，江廟石郎神。","童稚留荒宅，圖書託故人。","青門好風景，爲爾一沾巾。"]', '["闻说南中事，悲君重竄身。","山村楓子鬼，江廟石郎神。","童稚留荒宅，圖书託故人。","青门好风景，爲爾一沾巾。"]', '诗', 'shi', '', NULL, '送流人 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7be83d2-4e68-46e2-8fad-dbfafd0e5379', '過胡居士覩王右丞遺文', '過胡居士覩王右丞遺文', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["舊日相知盡，深居獨一身。","閉門空有雪，看竹永無人。","每許前山隱，曾憐陋巷貧。","題詩今尚在，暫爲拂流塵。"]', '["旧日相知尽，深居独一身。","閉门空有雪，看竹永無人。","每許前山隐，曾怜陋巷貧。","題诗今尚在，暫爲拂流塵。"]', '诗', 'shi', '', NULL, '過胡居士覩王右丞遺文 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f66d3849-b32b-41d8-8bc0-8845cb0eb7ed', '送郎使君赴郢州', '送郎使君赴郢州', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["使君持節去，雲水滿前程。","楚寺多連竹，江檣遠暎城。","登樓向月望，賽廟傍山行。","若動思鄉詠，應貽謝步兵。"]', '["使君持節去，云水满前程。","楚寺多連竹，江檣远暎城。","登楼向月望，賽廟傍山行。","若动思乡詠，應貽謝步兵。"]', '诗', 'shi', '', NULL, '送郎使君赴郢州 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c745990-657a-41fe-ba2c-d9cf371ca563', '賊平後送人北歸', '賊平後送人北归', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["世亂同南去，時清獨北還。","他鄉生白髮，舊國見青山。","曉月過殘壘，繁星宿故關。","寒禽與衰草，處處伴愁顏。"]', '["世亂同南去，时清独北還。","他乡生白髮，旧国见青山。","晓月過殘壘，繁星宿故关。","寒禽與衰草，处处伴愁顏。"]', '诗', 'shi', '', NULL, '賊平後送人北歸 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ea9c5d8-c3dd-45cf-911e-e602fca2ff75', '觀獵騎', '观獵騎', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["纏臂繡綸巾，貂裘窄稱身。","射禽風助箭，走馬雪翻塵。","金埒爭開道，香車爲駐輪。","翩翩不知處，傳是霍家親。"]', '["纏臂繡綸巾，貂裘窄稱身。","射禽风助箭，走马雪翻塵。","金埒爭开道，香车爲駐輪。","翩翩不知处，傳是霍家親。"]', '诗', 'shi', '', NULL, '觀獵騎 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47948a17-85bc-4a79-815b-888a7c0a47a4', '同苗員外宿薦福常師房', '同苗員外宿薦福常師房', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["浮生共多故，聚宿喜君同。","人息時聞磬，燈搖乍有風。","霜堦疑水際，夜木似山中。","一願持如意，長來事遠公。"]', '["浮生共多故，聚宿喜君同。","人息时闻磬，灯搖乍有风。","霜堦疑水際，夜木似山中。","一願持如意，长来事远公。"]', '诗', 'shi', '', NULL, '同苗員外宿薦福常師房 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20b23989-2e5d-4587-b486-e8f3b2b100a0', '送喬廣下第歸淮南', '送喬廣下第归淮南', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["遙想長淮盡，荒堤楚路斜。","戍旌標白浪，罟網入青葭。","啼鳥仍臨水，愁人更見花。","東堂一枝在，爲子惜年華。"]', '["遙想长淮尽，荒堤楚路斜。","戍旌標白浪，罟網入青葭。","啼鸟仍臨水，愁人更见花。","东堂一枝在，爲子惜年华。"]', '诗', 'shi', '', NULL, '送喬廣下第歸淮南 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d03165d5-faef-44bc-9e9b-9e3c16cbcb7d', '風箏', '风箏', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["高風吹玉柱，萬籟忽齊飄。","颯樹遲難度，縈空細漸銷。","松泉鹿門夜，笙鶴洛濱朝。","坐與真僧聽，支頤向寂寥。"]', '["高风吹玉柱，万籟忽齊飄。","颯樹遲难度，縈空細漸銷。","松泉鹿门夜，笙鹤洛濱朝。","坐與真僧听，支頤向寂寥。"]', '诗', 'shi', '', NULL, '風箏 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('febd291a-db2c-48d0-9891-249237e794be', '閑居寄苗發', '闲居寄苗發', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["漸向浮生老，前期竟若何。","獨身居處靜，永夜坐時多。","厭逐青林客，休吟白雪歌。","支公有遺寺，重與謝安過。"]', '["漸向浮生老，前期竟若何。","独身居处静，永夜坐时多。","厭逐青林客，休吟白雪歌。","支公有遺寺，重與謝安過。"]', '诗', 'shi', '', NULL, '閑居寄苗發 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc1d4a33-47ed-4e34-b7da-ae8d0347efa9', '送王先生歸南山', '送王先生归南山', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["儒中年最老，獨有濟南生。","愛子方傳業，無官自耦耕。","竹通山舍遠，雲接雪田平。","願作門人去，相隨隱姓名。"]', '["儒中年最老，独有濟南生。","愛子方傳業，無官自耦耕。","竹通山舍远，云接雪田平。","願作门人去，相隨隐姓名。"]', '诗', 'shi', '', NULL, '送王先生歸南山 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee741325-dc51-4625-8bb5-20d477c3efaa', '寄天台秀師', '寄天台秀師', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["天台瀑布寺，傳有白頭師。","幻跡示羸病，空門無住持。","雪晴看鶴去，海夜與龍期。","永願親瓶屨，呈功得問疑。"]', '["天台瀑布寺，傳有白头師。","幻跡示羸病，空门無住持。","雪晴看鹤去，海夜與龙期。","永願親瓶屨，呈功得问疑。"]', '诗', 'shi', '', NULL, '寄天台秀師 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3435bf5-5dcb-4b55-9cf1-216b699c96d0', '送夏侯審赴寧國', '送夏侯審赴寧国', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["青圻連白浪，曉日渡南津。","山疊陵陽樹，舟多建業人。","煙霞高占寺，楓竹暗停神。","如接玄暉集，江丞獨見親。"]', '["青圻連白浪，晓日渡南津。","山叠陵陽樹，舟多建業人。","煙霞高占寺，楓竹暗停神。","如接玄暉集，江丞独见親。"]', '诗', 'shi', '', NULL, '送夏侯審赴寧國 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3138fe30-6cf6-45b0-a441-2d5398107a9a', '雲陽館與韓紳宿別', '云陽館與韓紳宿別', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["故人江海別，幾度隔山川。","乍見翻疑夢，相悲各問年。","孤燈寒照雨，溼竹暗浮煙。","更有明朝恨，離杯惜共傳。"]', '["故人江海別，幾度隔山川。","乍见翻疑梦，相悲各问年。","孤灯寒照雨，溼竹暗浮煙。","更有明朝恨，離杯惜共傳。"]', '诗', 'shi', '', NULL, '雲陽館與韓紳宿別 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2be9ac64-89a2-43ac-a980-16aa2497fe02', '送盧使君赴夔州', '送盧使君赴夔州', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["鐃管隨旌斾，高秋遠上巴。","白波連霧雨，青壁斷蒹葭。","凭几雙童靜，登樓萬井斜。","政成知變俗，當應畫輪車。"]', '["鐃管隨旌斾，高秋远上巴。","白波連霧雨，青壁斷蒹葭。","凭几雙童静，登楼万井斜。","政成知变俗，當應畫輪车。"]', '诗', 'shi', '', NULL, '送盧使君赴夔州 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed7ad319-24c2-47d1-86be-f99ec92feccc', '夜聞回雁', '夜闻回雁', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["雁響天邊過，高高望不分。","颼飀傳細雨，嘹唳隔長雲。","散向誰家盡，歸來幾客聞。","還將今夜意，西海話蘇君。"]', '["雁响天邊過，高高望不分。","颼飀傳細雨，嘹唳隔长云。","散向誰家尽，归来幾客闻。","還將今夜意，西海話蘇君。"]', '诗', 'shi', '', NULL, '夜聞回雁 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db5eca9b-a4c0-4b33-b1d3-629b78362f6c', '賦得的的帆向浦', '賦得的的帆向浦', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["向浦參差去，隨波遠近還。","初移芳草裏，正在夕陽間。","隱暎回孤驛，微明出亂山。","向空看不盡，歸思滿江關。"]', '["向浦參差去，隨波远近還。","初移芳草裏，正在夕陽间。","隐暎回孤驛，微明出亂山。","向空看不尽，归思满江关。"]', '诗', 'shi', '', NULL, '賦得的的帆向浦 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cae6c3b-725f-42f5-95ab-a78b42582b10', '秋思呈尹植裴說', '秋思呈尹植裴说', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["靜向嬾相偶，年將衰共催。","前途懽不集，往事恨空來。","晝景委紅葉，月華銷綠苔。","沈思竟何有，坐結玉琴哀。"]', '["静向嬾相偶，年將衰共催。","前途懽不集，往事恨空来。","晝景委紅葉，月华銷綠苔。","沈思竟何有，坐結玉琴哀。"]', '诗', 'shi', '', NULL, '秋思呈尹植裴說 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2740c24-d6db-4562-81ff-be9f0bfe16e0', '閑園即事寄暕公', '闲园即事寄暕公', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["欲就東林寄一身，尚憐兒女未成人。","柴門客去殘陽在，藥圃蟲喧秋雨頻。","近水方同梅市隱，曝衣多笑阮家貧。","深山蘭若何時到，羨與閑雲作四鄰。"]', '["欲就东林寄一身，尚怜兒女未成人。","柴门客去殘陽在，藥圃蟲喧秋雨頻。","近水方同梅市隐，曝衣多笑阮家貧。","深山蘭若何时到，羨與闲云作四鄰。"]', '诗', 'shi', '', NULL, '閑園即事寄暕公 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99025f97-6135-4fb8-b5dc-0e41106cb643', '題暕上人院', '題暕上人院', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["閉門不出自焚香，擁褐看山歲月長。","雨後綠苔生石井，秋來黃葉遍繩牀。","身閑何處無真性，年老曾言隱故鄉。","更說本師同學在，幾時攜手見衡陽。"]', '["閉门不出自焚香，擁褐看山歲月长。","雨後綠苔生石井，秋来黄葉遍繩牀。","身闲何处無真性，年老曾言隐故乡。","更说本師同学在，幾时携手见衡陽。"]', '诗', 'shi', '', NULL, '題暕上人院 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59da8f38-abd3-4af3-b549-7b9ef4aec01f', '長安曉望寄程補闕', '长安晓望寄程補闕', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["迢遰山河擁帝京，參差宮殿接雲平。","風吹曉漏經長樂，柳帶晴煙出禁城。","天淨笙歌臨路發，日高車馬隔塵行。","獨有淺才甘未達，多慙名在魯諸生。"]', '["迢遰山河擁帝京，參差宮殿接云平。","风吹晓漏經长乐，柳带晴煙出禁城。","天淨笙歌臨路發，日高车马隔塵行。","独有淺才甘未達，多慙名在魯諸生。"]', '诗', 'shi', '', NULL, '長安曉望寄程補闕 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d8d840d-1f94-44da-9b52-18a01cf8ed82', '下第日書情寄上叔父', '下第日书情寄上叔父', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["微才空覺滯京師，末學曾爲叔父知。","雪裏題詩偏見賞，林間飲酒獨令隨。","遊客盡傷春色老，貧居還惜暮陰移。","欲歸江海尋山去，願報何人得桂枝。"]', '["微才空覺滯京師，末学曾爲叔父知。","雪裏題诗偏见賞，林间饮酒独令隨。","游客尽傷春色老，貧居還惜暮陰移。","欲归江海尋山去，願報何人得桂枝。"]', '诗', 'shi', '', NULL, '下第日書情寄上叔父 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('550d7a0c-eb74-46c2-8bd8-7e837642be87', '南原望漢宮', '南原望漢宮', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["荒原空有漢宮名，衰草茫茫雉堞平。","連雁下時秋水在，行人過盡暮煙生。","西陵歌吹何年絕，南陌登臨此日情。","故事悠悠不可問，寒禽野水自縱橫。"]', '["荒原空有漢宮名，衰草茫茫雉堞平。","連雁下时秋水在，行人過尽暮煙生。","西陵歌吹何年絕，南陌登臨此日情。","故事悠悠不可问，寒禽野水自縱橫。"]', '诗', 'shi', '', NULL, '南原望漢宮 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fb9719a-8cb6-4597-9e8a-a3d833addf5b', '早夏寄元校書', '早夏寄元校书', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["獨遊野徑送芳菲，高竹林居接翠微。","綠岸草深蟲入徧，青藂花盡蝶來稀。","珠荷薦果香寒簟，玉柄搖風滿夏衣。","蓬蓽永無車馬到，更當齋夜憶玄暉。"]', '["独游野徑送芳菲，高竹林居接翠微。","綠岸草深蟲入徧，青藂花尽蝶来稀。","珠荷薦果香寒簟，玉柄搖风满夏衣。","蓬蓽永無车马到，更當斋夜憶玄暉。"]', '诗', 'shi', '', NULL, '早夏寄元校書 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdd14fd6-3be3-4f4f-acb7-4c8080ee8c83', '贈衡岳隱禪師', '贈衡岳隐禪師', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["擁褐安居南岳頭，白雲高寺見衡州。","石窗湖水搖寒月，楓樹猨聲報夜秋。","講席舊逢山鳥至，梵經初向竺僧求。","垂垂身老將傳法，因下人間逐北遊。"]', '["擁褐安居南岳头，白云高寺见衡州。","石窗湖水搖寒月，楓樹猨声報夜秋。","講席旧逢山鸟至，梵經初向竺僧求。","垂垂身老將傳法，因下人间逐北游。"]', '诗', 'shi', '', NULL, '贈衡岳隱禪師 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('225e5b02-b302-47a3-b95f-526b2acd82ac', '題凌雲寺', '題凌云寺', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["春山古寺遶滄波，石磴盤空鳥道過。","百丈金身開翠壁，萬龕燈焰隔煙蘿。","雲生客到侵衣溼，花落僧禪覆地多。","不與方袍同結社，下歸塵世竟如何。"]', '["春山古寺遶滄波，石磴盤空鸟道過。","百丈金身开翠壁，万龕灯焰隔煙蘿。","云生客到侵衣溼，花落僧禪覆地多。","不與方袍同結社，下归塵世竟如何。"]', '诗', 'shi', '', NULL, '題凌雲寺 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e00db95a-acd8-4924-84e7-97b8e8adbb46', '晦日益州北池陪宴', '晦日益州北池陪宴', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["臨泛從公日，仙舟翠幕張。","七橋通碧沼，雙樹接花塘。","玉燭收寒氣，金波隱夕光。","野聞歌管思，水靜綺蘿香。","遊騎縈林遠，飛橈截岸長。","郊原懷灞滻，陂溠寫江潢。","常侍傳花詔，偏裨問羽觴。","豈令南峴首，千載播餘芳。"]', '["臨泛從公日，仙舟翠幕張。","七橋通碧沼，雙樹接花塘。","玉燭收寒氣，金波隐夕光。","野闻歌管思，水静綺蘿香。","游騎縈林远，飞橈截岸长。","郊原懷灞滻，陂溠寫江潢。","常侍傳花詔，偏裨问羽觴。","豈令南峴首，千載播餘芳。"]', '诗', 'shi', '', NULL, '晦日益州北池陪宴 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf48fb27-3e4f-4381-901d-e3a806a81e1a', '送曲山人之衡州', '送曲山人之衡州', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["白石先生眉髮光，已分甜雪飲紅漿。","衣巾半染煙霞氣，語笑兼和藥草香。","茅洞玉聲流暗水，衡山碧色暎朝陽。","千年城郭如相問，華表峩峩有夜霜。"]', '["白石先生眉髮光，已分甜雪饮紅漿。","衣巾半染煙霞氣，語笑兼和藥草香。","茅洞玉声流暗水，衡山碧色暎朝陽。","千年城郭如相问，华表峩峩有夜霜。"]', '诗', 'shi', '', NULL, '送曲山人之衡州 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a463ea97-2744-4c09-bf65-d6681e6e4136', '立秋日', '立秋日', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["律變新秋至，蕭條自此初。","花酣蓮報謝，葉在柳呈疎。","澹日非雲暎，清風似雨餘。","卷簾涼暗度，迎扇暑先除。","草靜多翻燕，波澄乍露魚。","今朝散騎省，作賦興何如。"]', '["律变新秋至，蕭條自此初。","花酣蓮報謝，葉在柳呈疎。","澹日非云暎，清风似雨餘。","卷簾涼暗度，迎扇暑先除。","草静多翻燕，波澄乍露鱼。","今朝散騎省，作賦兴何如。"]', '诗', 'shi', '', NULL, '立秋日 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52aff993-0d3e-45d1-9e5c-a6bc5cd8c966', '詠古寺花', '詠古寺花', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["共愛芳菲此樹中，千跗萬萼裹枝紅。","遲遲欲去猶回望，覆地無人滿寺風。"]', '["共愛芳菲此樹中，千跗万萼裹枝紅。","遲遲欲去猶回望，覆地無人满寺风。"]', '诗', 'shi', '', NULL, '詠古寺花 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb725498-003a-4a42-b634-c91f9813b47b', '酬張芬有赦後見贈', '酬張芬有赦後见贈', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["紫鳳朝銜五色書，陽春忽布網羅除。","已將心變寒灰後，豈料光生腐草餘。","建水風煙收客淚，杜陵花竹夢郊居。","勞君故有詩相贈，欲報瓊瑤恨不如。"]', '["紫鳳朝銜五色书，陽春忽布網羅除。","已將心变寒灰後，豈料光生腐草餘。","建水风煙收客泪，杜陵花竹梦郊居。","勞君故有诗相贈，欲報瓊瑤恨不如。"]', '诗', 'shi', '', NULL, '酬張芬有赦後見贈 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('261d8e84-5e2f-4729-abc7-9e3c6730fa80', '哭苗員外呈張參軍', '哭苗員外呈張參軍', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["思君甯家宅，久接竹林期。","嘗值偷琴處，親聞比玉時。","高人不易合，弱冠早相知。","試藝臨諸友，能文即我師。","凌寒松未老，先暮槿何衰。","季子生前別，羊曇醉後悲。","壽堂乖一慟，奠席阻長辭。","因瀝殊方淚，遙成墓下詩。"]', '["思君甯家宅，久接竹林期。","嘗值偷琴处，親闻比玉时。","高人不易合，弱冠早相知。","試藝臨諸友，能文即我師。","凌寒松未老，先暮槿何衰。","季子生前別，羊曇醉後悲。","壽堂乖一慟，奠席阻长辞。","因瀝殊方泪，遙成墓下诗。"]', '诗', 'shi', '', NULL, '哭苗員外呈張參軍 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bba5a88-ee75-4eb5-9ab9-4b6f27402147', '金陵懷古', '金陵懷古', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["輦路江楓暗，宮庭野草春。","傷心庾開府，老作北朝臣。"]', '["輦路江楓暗，宮庭野草春。","傷心庾开府，老作北朝臣。"]', '诗', 'shi', '', NULL, '金陵懷古 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c06e70d-d153-4fb4-bea7-1398ff964273', '發渝州却寄韋判官', '發渝州却寄韋判官', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["紅燭津亭夜見君，繁弦急管兩紛紛。","平明分手空江轉，唯有猨聲滿水雲。"]', '["紅燭津亭夜见君，繁弦急管兩紛紛。","平明分手空江轉，唯有猨声满水云。"]', '诗', 'shi', '', NULL, '發渝州却寄韋判官 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c89eb3c-9aed-4afd-89cd-c424aaf88f86', '送盧徹之太原謁馬尚書', '送盧徹之太原謁马尚书', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["榆落鵰飛關塞秋，黃雲畫角見幷州。","翩翩羽騎雙旌後，上客親隨郭細侯。"]', '["榆落鵰飞关塞秋，黄云畫角见幷州。","翩翩羽騎雙旌後，上客親隨郭細侯。"]', '诗', 'shi', '', NULL, '送盧徹之太原謁馬尚書 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddf96d5e-ba4c-4bbc-9630-f4cc54d871a5', '峽口送友人', '峽口送友人', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["峽口花飛欲盡春，天涯去住淚沾巾。","來時萬里同爲客，今日飜成送故人。"]', '["峽口花飞欲尽春，天涯去住泪沾巾。","来时万里同爲客，今日飜成送故人。"]', '诗', 'shi', '', NULL, '峽口送友人 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12fc2689-c215-415e-bc92-1ea4ea9d2a6a', '故郭婉儀挽歌', '故郭婉儀挽歌', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["一日辭秦鏡，千秋別漢宮。","豈唯泉路掩，長使月輪空。","苦色凝朝露，悲聲切暝風。","婉儀餘舊德，仍載禮經中。"]', '["一日辞秦镜，千秋別漢宮。","豈唯泉路掩，长使月輪空。","苦色凝朝露，悲声切暝风。","婉儀餘旧德，仍載禮經中。"]', '诗', 'shi', '', NULL, '故郭婉儀挽歌 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13bb39b1-aeed-46ae-9576-315d59c1ddb5', '送翰林張學士嶺南勒聖碑', '送翰林張学士嶺南勒聖碑', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["漢恩天外洽，周頌日邊稱。","文獨司空羨，書兼太尉能。","出關逢北雁，度嶺逐南鵬。","使者翰林客，餘春歸灞陵。"]', '["漢恩天外洽，周頌日邊稱。","文独司空羨，书兼太尉能。","出关逢北雁，度嶺逐南鵬。","使者翰林客，餘春归灞陵。"]', '诗', 'shi', '', NULL, '送翰林張學士嶺南勒聖碑 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e77befb-75da-4226-b95d-0b44902bbb2e', '送吉校書東歸', '送吉校书东归', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["少年芸閣吏，罷直暫歸休。","獨與親知別，行逢江海秋。","聽猨看楚岫，隨雁到吳洲。","處處園林好，何人待子猷。"]', '["少年芸閣吏，罷直暫归休。","独與親知別，行逢江海秋。","听猨看楚岫，隨雁到吳洲。","处处园林好，何人待子猷。"]', '诗', 'shi', '', NULL, '送吉校書東歸 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d48cbe05-7d5a-4d01-a798-9b64117b301b', '早春遊望', '早春游望', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["東風春未足，試望秦城曲。","青草狀寒蕪，黃花似秋菊。","壯將歡共去，老與悲相逐。","獨作遊社人，暮過威輦宿。"]', '["东风春未足，試望秦城曲。","青草狀寒蕪，黄花似秋菊。","壯將歡共去，老與悲相逐。","独作游社人，暮過威輦宿。"]', '诗', 'shi', '', NULL, '早春遊望 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4fa2591-498f-46a4-8fa5-d813a13a1786', '秋日趨府上張大夫', '秋日趨府上張大夫', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["重城洞啓肅秋煙，共說羊公在鎮年。","鞞鼓暗驚林葉落，旌旗遙拂雁行偏。","石過橋下書曾受，星降人間夢已傳。","謫吏何能沐風化，空將歌頌拜車前。"]', '["重城洞啓肅秋煙，共说羊公在鎮年。","鞞鼓暗驚林葉落，旌旗遙拂雁行偏。","石過橋下书曾受，星降人间梦已傳。","謫吏何能沐风化，空將歌頌拜车前。"]', '诗', 'shi', '', NULL, '秋日趨府上張大夫 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50540ff5-7284-49dc-bcf1-73c8171e4bea', '竹裏徑', '竹裏徑', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["幽徑行迹稀，清陰苔色古。","蕭蕭風欲來，乍似蓬山雨。"]', '["幽徑行迹稀，清陰苔色古。","蕭蕭风欲来，乍似蓬山雨。"]', '诗', 'shi', '', NULL, '竹裏徑 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c14e9734-cec8-445e-8d03-88d75a42f48e', '黃子陂', '黄子陂', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["岸芳春色曉，水影夕陽微。","寂寂深煙裏，漁舟夜不歸。"]', '["岸芳春色晓，水影夕陽微。","寂寂深煙裏，漁舟夜不归。"]', '诗', 'shi', '', NULL, '黃子陂 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b9bc8ca-355e-44fc-84f9-edb83ba18dd9', '田鶴', '田鹤', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["散下渚田中，隱見菰蒲裏。","哀鳴自相應，欲作凌風起。"]', '["散下渚田中，隐见菰蒲裏。","哀鳴自相應，欲作凌风起。"]', '诗', 'shi', '', NULL, '田鶴 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ec10c43-5c07-40b9-a1e5-3684a31e3097', '藥園', '藥园', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["春園芳已遍，綠蔓雜紅英。","獨有深山客，時來辨藥名。"]', '["春园芳已遍，綠蔓杂紅英。","独有深山客，时来辨藥名。"]', '诗', 'shi', '', NULL, '藥園 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb578632-7e3b-45ba-af1e-adb0a6b4e805', '石井', '石井', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["苔色遍春石，桐陰入寒井。","幽人獨汲時，先樂殘陽影。"]', '["苔色遍春石，桐陰入寒井。","幽人独汲时，先乐殘陽影。"]', '诗', 'shi', '', NULL, '石井 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66f33bac-616c-4430-a850-efbd43761213', '板橋', '板橋', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["橫遮野水石，前帶荒村道。","來往見愁人，清風柳陰好。"]', '["橫遮野水石，前带荒村道。","来往见愁人，清风柳陰好。"]', '诗', 'shi', '', NULL, '板橋 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e44c5577-e518-4ead-a5c3-1940c86f0c8b', '石蓮花', '石蓮花', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["今逢石上生，本自波中有。","紅豔秋風裏，誰憐衆芳後。"]', '["今逢石上生，本自波中有。","紅豔秋风裏，誰怜衆芳後。"]', '诗', 'shi', '', NULL, '石蓮花 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9649f4dc-e18d-4b00-bb8c-018e0d725b03', '遠寺鐘', '远寺鐘', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["杳杳疎鐘發，因風清復引。","中宵獨聽之，似與東林近。"]', '["杳杳疎鐘發，因风清复引。","中宵独听之，似與东林近。"]', '诗', 'shi', '', NULL, '遠寺鐘 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e604fca-c9bc-4c80-a76b-102ba0c23af6', '松下雪', '松下雪', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["不隨晴野盡，獨向深松積。","落照入寒光，偏能伴幽寂。"]', '["不隨晴野尽，独向深松積。","落照入寒光，偏能伴幽寂。"]', '诗', 'shi', '', NULL, '松下雪 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35577519-453b-4de0-a631-080f9f90eca2', '新柳', '新柳', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["全欺芳蕙晚，似妬寒梅疾。","撩亂發青條，春風來幾日。"]', '["全欺芳蕙晚，似妬寒梅疾。","撩亂發青條，春风来幾日。"]', '诗', 'shi', '', NULL, '新柳 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('852b6ae2-62ae-486b-b236-dd51254e743a', '唐昌公主院看花', '唐昌公主院看花', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["遺殿空長閉，乘鸞自不回。","至今荒草上，寥落舊花開。"]', '["遺殿空长閉，乘鸾自不回。","至今荒草上，寥落旧花开。"]', '诗', 'shi', '', NULL, '唐昌公主院看花 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f73ad47-4dc9-4422-83fd-04a6600e0328', '別張讚', '別張讚', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["今日山晴後，殘蟬菊發時。","登樓見秋色，何處最相思。"]', '["今日山晴後，殘蟬菊發时。","登楼见秋色，何处最相思。"]', '诗', 'shi', '', NULL, '別張讚 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe83cf62-7214-467e-ac9a-f776ab75a95b', '晚思', '晚思', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["蛩餘窗下月，草溼堦前露。","晚景淒我衣，秋風入庭樹。"]', '["蛩餘窗下月，草溼堦前露。","晚景淒我衣，秋风入庭樹。"]', '诗', 'shi', '', NULL, '晚思 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('faafba66-ea77-4659-a4f3-705e983987ef', '留盧秦卿', '留盧秦卿', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["知有前期在，難分此夜中。","無將故人酒，不及石尤風。"]', '["知有前期在，难分此夜中。","無將故人酒，不及石尤风。"]', '诗', 'shi', '', NULL, '留盧秦卿 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('844a6888-158d-4ffd-9b8f-89fce8d79c9f', '登峴亭', '登峴亭', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["峴山回首望秦關，南向荆州幾日還。","今日登臨唯有淚，不知風景在何山。"]', '["峴山回首望秦关，南向荆州幾日還。","今日登臨唯有泪，不知风景在何山。"]', '诗', 'shi', '', NULL, '登峴亭 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8bd6aed-f7ef-403a-9584-cef60350368d', '哭麴山人', '哭麴山人', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["憶昔秋風起，君曾歎逐臣。","何言芳草日，自作九泉人。"]', '["憶昔秋风起，君曾歎逐臣。","何言芳草日，自作九泉人。"]', '诗', 'shi', '', NULL, '哭麴山人 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1b981cd-d3a7-4739-b886-a6e4f6bf2b09', '過堅上人故院與李端同賦', '過堅上人故院與李端同賦', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["舊依支遁宿，曾與戴顒來。","今日空林下，唯知見綠苔。"]', '["旧依支遁宿，曾與戴顒来。","今日空林下，唯知见綠苔。"]', '诗', 'shi', '', NULL, '過堅上人故院與李端同賦 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa4585b5-4390-49ad-9a27-43904499dff1', '病中嫁女妓', '病中嫁女妓', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["萬事傷心在目前，一身垂淚對花筵。","黃金用盡教歌舞，留與他人樂少年。"]', '["万事傷心在目前，一身垂泪对花筵。","黄金用尽教歌舞，留與他人乐少年。"]', '诗', 'shi', '', NULL, '病中嫁女妓 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64d3f88f-ce69-4ea3-8646-5635a7ed9139', '江村即事', '江村即事', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["釣罷歸來不繫船，江村月落正堪眠。","縱然一夜風吹去，只在蘆花淺水邊。"]', '["釣罷归来不繫船，江村月落正堪眠。","縱然一夜风吹去，只在蘆花淺水邊。"]', '诗', 'shi', '', NULL, '江村即事 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecd1b88c-bfc0-46b0-a91a-802f435755b6', '送鄭明府貶嶺南', '送鄭明府貶嶺南', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["青楓江色晚，楚客獨傷春。","共對一尊酒，相看萬里人。","猜嫌成謫宦，正直不防身。","莫畏炎方久，年年雨露新。"]', '["青楓江色晚，楚客独傷春。","共对一尊酒，相看万里人。","猜嫌成謫宦，正直不防身。","莫畏炎方久，年年雨露新。"]', '诗', 'shi', '', NULL, '送鄭明府貶嶺南 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c044e03-74a7-41e1-a28e-1386228564c3', '寄衞明府常見短靴褐裘又務持誦是以有末句之贈', '寄衞明府常见短靴褐裘又務持誦是以有末句之贈', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["柴桑官舍近東林，兒稚初髫即道心。","側寄繩牀嫌凭几，斜安苔幘嬾穿簪。","高僧靜望山僮逐，走吏喧來水鴨沈。","翠竹黃花皆佛性，莫教塵境誤相侵。"]', '["柴桑官舍近东林，兒稚初髫即道心。","側寄繩牀嫌凭几，斜安苔幘嬾穿簪。","高僧静望山僮逐，走吏喧来水鴨沈。","翠竹黄花皆佛性，莫教塵境誤相侵。"]', '诗', 'shi', '', NULL, '寄衞明府常見短靴褐裘又務持誦是以有末句之贈 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e6f3ca9-f771-438d-8f5f-75ba5b802739', '酬李端校書見贈', '酬李端校书见贈', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["綠槐垂穗乳烏飛，忽憶山中獨未歸。","青鏡流年看髮變，白雲芳草與心違。","乍逢酒客春遊慣，久別林僧夜坐稀。","昨日聞君到城闕，莫將簪弁勝荷衣。"]', '["綠槐垂穗乳烏飞，忽憶山中独未归。","青镜流年看髮变，白云芳草與心違。","乍逢酒客春游慣，久別林僧夜坐稀。","昨日闻君到城闕，莫將簪弁勝荷衣。"]', '诗', 'shi', '', NULL, '酬李端校書見贈 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3dcc157-7b7f-43a1-b884-2aec0694612e', '過盧秦卿舊居', '過盧秦卿旧居', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["五柳茅茨楚國賢，桔槔蔬圃水涓涓。","黃花寒後難逢蝶，紅葉晴來忽有蟬。","韓康助採君臣藥，支遁同看內外篇。","爲問潛夫空著論，如何侍從賦甘泉。"]', '["五柳茅茨楚国賢，桔槔蔬圃水涓涓。","黄花寒後难逢蝶，紅葉晴来忽有蟬。","韓康助採君臣藥，支遁同看內外篇。","爲问潛夫空著論，如何侍從賦甘泉。"]', '诗', 'shi', '', NULL, '過盧秦卿舊居 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('559dd818-124e-426b-8304-585076bece88', '秋園', '秋园', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["傷秋不是惜年華，別憶春風碧玉家。","強向衰藂見芳意，茱萸紅實似繁花。"]', '["傷秋不是惜年华，別憶春风碧玉家。","強向衰藂见芳意，茱萸紅實似繁花。"]', '诗', 'shi', '', NULL, '秋園 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d528dd1-986f-4758-bec4-909824a7f6c8', '送王使君赴太原拜節度副使', '送王使君赴太原拜節度副使', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["新從劉太尉，結束向幷州。","絡腦青絲騎，盤囊錦帶鉤。","出關逢將校，下嶺擁戈矛。","匣閉黃雲冷，山傳畫角秋。","劒鋒將破虜，函道罷登樓。","豈作書生老，當封萬戶侯。"]', '["新從劉太尉，結束向幷州。","絡腦青絲騎，盤囊錦带鉤。","出关逢將校，下嶺擁戈矛。","匣閉黄云冷，山傳畫角秋。","劒鋒將破虜，函道罷登楼。","豈作书生老，當封万戶侯。"]', '诗', 'shi', '', NULL, '送王使君赴太原拜節度副使 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9390e66b-2b88-4f90-a37b-3ae3a18bb5e9', '擬百勞歌', '擬百勞歌', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["朱絲紐弦金點雜，雙蔕芙蓉共開合。","誰家稚女著羅裳，紅粉青眉嬌暮妝。","木難作牀牙作席，雲母屏風光照壁。","玉顏年幾新上頭，迴身斂笑多自羞。","紅銷月落不復見，可惜當時誰拂面。"]', '["朱絲紐弦金点杂，雙蔕芙蓉共开合。","誰家稚女著羅裳，紅粉青眉嬌暮妝。","木难作牀牙作席，云母屏风光照壁。","玉顏年幾新上头，迴身斂笑多自羞。","紅銷月落不复见，可惜當时誰拂面。"]', '诗', 'shi', '', NULL, '擬百勞歌 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1b193e2-3062-4ac7-971b-33f310c12e93', '迎神', '迎神', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["吉日兮臨水，沐青蘭兮白芷。","假山鬼兮請東皇，託靈均兮邀帝子。","吹參差兮正苦，舞婆娑兮未已。","鸞旌圓蓋望欲來，山雨霏霏江浪起。","神既降兮我獨知，目成再拜爲陳詞。"]', '["吉日兮臨水，沐青蘭兮白芷。","假山鬼兮請东皇，託靈均兮邀帝子。","吹參差兮正苦，舞婆娑兮未已。","鸾旌圓蓋望欲来，山雨霏霏江浪起。","神既降兮我独知，目成再拜爲陳词。"]', '诗', 'shi', '', NULL, '迎神 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96d11aa0-418d-4fb9-a31c-248cb6edb341', '送神', '送神', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["神之去，迴風嫋嫋雲容與。","桂尊瑤席不復陳，蒼山綠水暮愁人。"]', '["神之去，迴风嫋嫋云容與。","桂尊瑤席不复陳，蒼山綠水暮愁人。"]', '诗', 'shi', '', NULL, '送神 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b47d819e-df0d-47a8-8864-5aadeb8190f8', '殘鶯百囀歌同王員外耿拾遺吉中孚李端遊慈恩各賦一物', '殘鶯百囀歌同王員外耿拾遺吉中孚李端游慈恩各賦一物', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["殘鶯一何怨，百囀相尋續。","始辨下將高，稍分長復促。","綿蠻巧狀語，機節終如曲。","野客賞應遲，幽僧聞詎足。","禪齋深樹夏陰清，零落空餘三兩聲。","金谷箏中傳不似，山陽笛裏寫難成。","憶昨亂啼無遠近，晴宮曉色偏相引。","送暖初隨柳色來，辭芳暗逐花枝盡。","歌殘鶯，歌殘鶯，悠然萬感生。","謝朓羇懷方一聽，何郎閑吟本多情。","乃知衆鳥非儔比，暮噪晨鳴倦人耳。","共愛奇音那可親，年年出谷待新春。","此時斷絕爲君惜，明日玄蟬催髮白。"]', '["殘鶯一何怨，百囀相尋續。","始辨下將高，稍分长复促。","綿蠻巧狀語，機節終如曲。","野客賞應遲，幽僧闻詎足。","禪斋深樹夏陰清，零落空餘三兩声。","金谷箏中傳不似，山陽笛裏寫难成。","憶昨亂啼無远近，晴宮晓色偏相引。","送暖初隨柳色来，辞芳暗逐花枝尽。","歌殘鶯，歌殘鶯，悠然万感生。","謝朓羇懷方一听，何郎闲吟本多情。","乃知衆鸟非儔比，暮噪晨鳴倦人耳。","共愛奇音那可親，年年出谷待新春。","此时斷絕爲君惜，明日玄蟬催髮白。"]', '诗', 'shi', '', NULL, '殘鶯百囀歌同王員外耿拾遺吉中孚李端遊慈恩各賦一物 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('048e688e-e32f-4dd7-9278-c83ab555f771', '過終南柳處士', '過終南柳处士', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["雲起山蒼蒼，林居蘿薜荒。","幽人老深境，素髮與青裳。","雨滌莓苔綠，風搖松桂香。","洞泉分溜淺，巖筍出藂長。","敗屨安松砌，餘棊在石牀。","書名一爲別，還路已堪傷。"]', '["云起山蒼蒼，林居蘿薜荒。","幽人老深境，素髮與青裳。","雨滌莓苔綠，风搖松桂香。","洞泉分溜淺，巖筍出藂长。","敗屨安松砌，餘棊在石牀。","书名一爲別，還路已堪傷。"]', '诗', 'shi', '', NULL, '過終南柳處士 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b62f493a-1634-4d07-a453-c2b51840ca9b', '春送郭大之官', '春送郭大之官', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["明府之官官舍春，春風辭我兩三人。","可憐江縣閑無事，手板支頤獨詠貧。"]', '["明府之官官舍春，春风辞我兩三人。","可怜江縣闲無事，手板支頤独詠貧。"]', '诗', 'shi', '', NULL, '春送郭大之官 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e5cc00a-1a2a-4a6a-9a98-2bea7f08255b', '送鄭錫', '送鄭錫', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["漢陽雲樹清無極，蜀國風煙思不堪。","莫怪別君偏有淚，十年曾事晉征南。"]', '["漢陽云樹清無極，蜀国风煙思不堪。","莫怪別君偏有泪，十年曾事晉征南。"]', '诗', 'shi', '', NULL, '送鄭錫 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d524713-c72f-4d10-b632-f4cfab9abece', '同張參軍喜李尚書寄新琴', '同張參軍喜李尚书寄新琴', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["新琴傳鳳凰，晴景稱高張。","白玉連徽淨，朱絲繫爪長。","輕埃隨拂拭，雜籟滿鏗鏘。","暗想山泉合，如親蘭蕙芳。","正聲消鄭衞，古狀掩笙簧。","遠識賢人意，清風願激揚。"]', '["新琴傳鳳凰，晴景稱高張。","白玉連徽淨，朱絲繫爪长。","轻埃隨拂拭，杂籟满鏗鏘。","暗想山泉合，如親蘭蕙芳。","正声消鄭衞，古狀掩笙簧。","远識賢人意，清风願激揚。"]', '诗', 'shi', '', NULL, '同張參軍喜李尚書寄新琴 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cbf0ade-9d50-476d-84b2-c20f21697c4c', '苦熱', '苦熱', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["暑氣發炎州，焦煙遠未收。","嘯風兼熾燄，揮汗訝成流。","鸛鵲投林盡，龜魚擁石稠。","漱泉齊飲酎，衣葛劇兼裘。","長簟貪欹枕，輕巾嬾挂頭。","招商如有曲，一爲取新秋。"]', '["暑氣發炎州，焦煙远未收。","嘯风兼熾燄，揮汗訝成流。","鸛鵲投林尽，龟鱼擁石稠。","漱泉齊饮酎，衣葛劇兼裘。","长簟貪欹枕，轻巾嬾挂头。","招商如有曲，一爲取新秋。"]', '诗', 'shi', '', NULL, '苦熱 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fea3769-7cab-4c8d-9a7b-5a9d654b9573', '送人歸黔府', '送人归黔府', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["伏波簫鼓水雲中，長戟如霜大斾紅。","油幕曉開飛鳥絕，翩翩上將獨趨風。"]', '["伏波簫鼓水云中，长戟如霜大斾紅。","油幕晓开飞鸟絕，翩翩上將独趨风。"]', '诗', 'shi', '', NULL, '送人歸黔府 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f8c955d-332c-40ee-bb64-017021a187b9', '雜興', '杂兴', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["月沒遼城暗出師，雙龍金角曉天悲。","黃塵滿目隨風散，不認將軍燕尾旗。"]', '["月沒遼城暗出師，雙龙金角晓天悲。","黄塵满目隨风散，不認將軍燕尾旗。"]', '诗', 'shi', '', NULL, '雜興 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('002d65d7-a386-46f1-8c8f-007095ec68bd', '歲暮懷崔峒耿湋', '歲暮懷崔峒耿湋', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["臘月江天見春色，白花青柳疑寒食。","洛陽舊社各東西，楚國遊人不相識。"]', '["臘月江天见春色，白花青柳疑寒食。","洛陽旧社各东西，楚国游人不相識。"]', '诗', 'shi', '', NULL, '歲暮懷崔峒耿湋 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a66209d3-155e-41b7-b272-8344f078847c', '觀妓', '观妓', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["翠蛾紅臉不勝情，管絕弦餘發一聲。","銀燭搖搖塵暗下，却愁紅粉淚痕生。"]', '["翠蛾紅臉不勝情，管絕弦餘發一声。","銀燭搖搖塵暗下，却愁紅粉泪痕生。"]', '诗', 'shi', '', NULL, '觀妓 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87ea72d1-8b8b-402f-b331-79f7a24dea41', '過長林湖西酒家', '過长林湖西酒家', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["湖草青青三兩家，門前桃杏一般花。","遷人到處唯求醉，聞說漁翁有酒賒。"]', '["湖草青青三兩家，门前桃杏一般花。","遷人到处唯求醉，闻说漁翁有酒賒。"]', '诗', 'shi', '', NULL, '過長林湖西酒家 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83c73d1e-bc22-4ba1-8974-2c8354de41cd', '過閻采病居', '過閻采病居', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["每逢佳節何曾坐，唯有今年不得遊。","張邴臥來休送客，菊花楓葉向誰秋。"]', '["每逢佳節何曾坐，唯有今年不得游。","張邴臥来休送客，菊花楓葉向誰秋。"]', '诗', 'shi', '', NULL, '過閻采病居 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2454276-7690-4f8a-8a84-f594d3856f05', '送程秀才', '送程秀才', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["悠悠多路岐，相見又別離。","東風催節換，燄燄春陽散。","楚草漸煙綿，江雲亦蕪漫。","送子恨何窮，故關如夢中。","遊人盡還北，旅雁辭南國。","楓樹幾回青，逐臣歸不得。"]', '["悠悠多路岐，相见又別離。","东风催節換，燄燄春陽散。","楚草漸煙綿，江云亦蕪漫。","送子恨何窮，故关如梦中。","游人尽還北，旅雁辞南国。","楓樹幾回青，逐臣归不得。"]', '诗', 'shi', '', NULL, '送程秀才 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3855367-0506-4851-a0e0-289ce9bf8f7e', '長林令衞象餳絲結歌', '长林令衞象餳絲結歌', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["主人琱盤盤素絲，寒女眷眷墨子悲。","乃言假使餳爲之，八珍重沓失顏色。","手援玉筯不敢持，始狀芙蓉新出水。","仰坼重衣傾萬蕊，又如合歡交亂枝。","紅茸向暮花參差，吳蠶絡繭抽尚絕。","細縷纖毫看欲滅，雪髮羞垂倭墮鬟。","繡囊畏並茱萸結，我愛此絲巧。","妙絕世間無，爲君作歌陳座隅。"]', '["主人琱盤盤素絲，寒女眷眷墨子悲。","乃言假使餳爲之，八珍重沓失顏色。","手援玉筯不敢持，始狀芙蓉新出水。","仰坼重衣傾万蕊，又如合歡交亂枝。","紅茸向暮花參差，吳蠶絡繭抽尚絕。","細縷纖毫看欲滅，雪髮羞垂倭墮鬟。","繡囊畏並茱萸結，我愛此絲巧。","妙絕世间無，爲君作歌陳座隅。"]', '诗', 'shi', '', NULL, '長林令衞象餳絲結歌 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a438ef5-b62e-4e29-9a48-b507796e5ba2', '酬崔峒見寄', '酬崔峒见寄', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["趨陪禁掖雁行隨，遷放江潭鶴髮垂。","素浪遙疑太液水，青楓忽似萬年枝。","嵩南春遍愁魂夢，壺口雲深隔路岐。","共望漢朝多沛澤，蒼蠅早晚得先知。"]', '["趨陪禁掖雁行隨，遷放江潭鹤髮垂。","素浪遙疑太液水，青楓忽似万年枝。","嵩南春遍愁魂梦，壺口云深隔路岐。","共望漢朝多沛澤，蒼蠅早晚得先知。"]', '诗', 'shi', '', NULL, '酬崔峒見寄 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2f4fe85-03f9-467c-a6f9-8d9a435fdbf2', '聞春雷', '闻春雷', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["水國春雷早，闐闐若衆車。","自憐遷逐者，猶滯蟄藏餘。"]', '["水国春雷早，闐闐若衆车。","自怜遷逐者，猶滯蟄藏餘。"]', '诗', 'shi', '', NULL, '聞春雷 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ed0cf4f-099d-4637-b8af-0a6b30356b98', '晚秋西省寄上李韓二舍人', '晚秋西省寄上李韓二舍人', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["晝漏傳清唱，天恩禁旅秋。","雁親承露掌，砧隔曝衣樓。","賜膳中人送，餘香侍女收。","仍聞勞上直，晚步鳳池頭。"]', '["晝漏傳清唱，天恩禁旅秋。","雁親承露掌，砧隔曝衣楼。","賜膳中人送，餘香侍女收。","仍闻勞上直，晚步鳳池头。"]', '诗', 'shi', '', NULL, '晚秋西省寄上李韓二舍人 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd9b9080-f3c9-4e70-8a5a-00f34b32569c', '下武昌江行望涔陽', '下武昌江行望涔陽', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["悠悠次楚鄉，楚口下涔陽。","雪隱洲渚暗，沙高蘆荻黃。","漁人共留滯，水鳥自喧翔。","懷土年空盡，春風又淼茫。"]', '["悠悠次楚乡，楚口下涔陽。","雪隐洲渚暗，沙高蘆荻黄。","漁人共留滯，水鸟自喧翔。","懷土年空尽，春风又淼茫。"]', '诗', 'shi', '', NULL, '下武昌江行望涔陽 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab3404a2-34a0-4ad2-b2a6-37cf28250a89', '送史申之峽州', '送史申之峽州', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["峽口巴江外，無風浪亦翻。","蒹葭新有雁，雲雨不離猨。","行客思鄉遠，愁人賴酒昏。","檀郎好聯句，共滯謝家門。"]', '["峽口巴江外，無风浪亦翻。","蒹葭新有雁，云雨不離猨。","行客思乡远，愁人賴酒昏。","檀郎好聯句，共滯謝家门。"]', '诗', 'shi', '', NULL, '送史申之峽州 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d3d42b2-b1f2-4e2f-9e43-219fa45f2427', '送王閏', '送王閏', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["相送臨寒水，蒼然望故關。","江蕪連夢澤，楚雪入商山。","話我他年舊，看君此日還。","因將自悲淚，一灑別離間。"]', '["相送臨寒水，蒼然望故关。","江蕪連梦澤，楚雪入商山。","話我他年旧，看君此日還。","因將自悲泪，一灑別離间。"]', '诗', 'shi', '', NULL, '送王閏 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('879f54a8-2beb-4334-bc17-6d7e7c29be15', '江園書事寄盧綸', '江园书事寄盧綸', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["種柳南江邊，閉門三四年。","豔花那勝竹，凡鳥不如蟬。","嗜酒漸嬰渴，讀書多欲眠。","平生故交在，白首遠相憐。"]', '["種柳南江邊，閉门三四年。","豔花那勝竹，凡鸟不如蟬。","嗜酒漸嬰渴，读书多欲眠。","平生故交在，白首远相怜。"]', '诗', 'shi', '', NULL, '江園書事寄盧綸 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0d7e119-8760-4482-b19b-7f424a116c0c', '送鄭況往淮南', '送鄭況往淮南', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["西楚見南關，蒼蒼落日間。","雲離大雷樹，潮入秣陵山。","登戍因高望，停橈放溜閑。","陳公有賢榻，君去豈空還。"]', '["西楚见南关，蒼蒼落日间。","云離大雷樹，潮入秣陵山。","登戍因高望，停橈放溜闲。","陳公有賢榻，君去豈空還。"]', '诗', 'shi', '', NULL, '送鄭況往淮南 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa9f873b-8b08-400c-8acb-f33b76db429f', '題江陵臨沙驛樓', '題江陵臨沙驛楼', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["江天清更愁，風柳入江樓。","雁惜楚山晚，蟬知秦樹秋。","淒涼多獨醉，零落半同遊。","豈復平生意，蒼然蘭杜洲。"]', '["江天清更愁，风柳入江楼。","雁惜楚山晚，蟬知秦樹秋。","淒涼多独醉，零落半同游。","豈复平生意，蒼然蘭杜洲。"]', '诗', 'shi', '', NULL, '題江陵臨沙驛樓 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90a58cb0-26fa-46ef-b1ba-e7c12bc12a06', '新蟬', '新蟬', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["今朝蟬忽鳴，遷客若爲情。","便覺一年老，能令萬感生。","微風方滿樹，落日稍沈城。","爲問同懷者，淒涼聽幾聲。"]', '["今朝蟬忽鳴，遷客若爲情。","便覺一年老，能令万感生。","微风方满樹，落日稍沈城。","爲问同懷者，淒涼听幾声。"]', '诗', 'shi', '', NULL, '新蟬 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a159d93-1de3-4be6-81de-10338e557ec7', '送張弋', '送張弋', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["擁櫂江天曠，蒼然下郢城。","冰霜葭菼變，雲澤鷓鴣鳴。","酒倦臨流醉，人逢置榻迎。","嘗聞藉東觀，不獨魯諸生。"]', '["擁櫂江天曠，蒼然下郢城。","冰霜葭菼变，云澤鷓鴣鳴。","酒倦臨流醉，人逢置榻迎。","嘗闻藉东观，不独魯諸生。"]', '诗', 'shi', '', NULL, '送張弋 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ee4fce8-9ad0-4931-90e6-6a5e6846e94c', '送僧無言歸山', '送僧無言归山', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["袈裟出塵外，山徑幾盤緣。","人到白雲樹，鶴沈青草田。","龕泉朝請盥，松籟夜和禪。","自昔聞多學，逍遙注一篇。"]', '["袈裟出塵外，山徑幾盤緣。","人到白云樹，鹤沈青草田。","龕泉朝請盥，松籟夜和禪。","自昔闻多学，逍遙注一篇。"]', '诗', 'shi', '', NULL, '送僧無言歸山 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('888f45a4-87d6-411d-854a-dd3a937c62a6', '和盧校書文若早入使院書事', '和盧校书文若早入使院书事', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["解帶獨裴回，秋風如水來。","軒墀溼繁露，琴几拂輕埃。","晨鳥猶在葉，夕蟲餘囗苔。","蒼然發高興，相仰坐難陪。"]', '["解带独裴回，秋风如水来。","軒墀溼繁露，琴几拂轻埃。","晨鸟猶在葉，夕蟲餘囗苔。","蒼然發高兴，相仰坐难陪。"]', '诗', 'shi', '', NULL, '和盧校書文若早入使院書事 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d587424-e1fd-4046-b518-b5f6dfec0922', '送史澤之長沙', '送史澤之长沙', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["謝朓懷西府，單車觸火雲。","野蕉依戍客，廟竹暎湘君。","夢渚巴山斷，長沙楚路分。","一杯從別後，風月不相聞。"]', '["謝朓懷西府，單车觸火云。","野蕉依戍客，廟竹暎湘君。","梦渚巴山斷，长沙楚路分。","一杯從別後，风月不相闻。"]', '诗', 'shi', '', NULL, '送史澤之長沙 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78a0656c-3a6e-43b0-9e67-1a894ded1688', '田家', '田家', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["田家喜雨足，鄰老相招攜。","泉溢溝塍壞，麥高桑柘低。","呼兒催放犢，宿客待烹雞。","搔首蓬門下，如將軒冕齊。"]', '["田家喜雨足，鄰老相招携。","泉溢溝塍壞，麦高桑柘低。","呼兒催放犢，宿客待烹雞。","搔首蓬门下，如將軒冕齊。"]', '诗', 'shi', '', NULL, '田家 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8acf36ea-95e1-4491-9718-8e0b85ee106d', '送盧堪', '送盧堪', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["羈貧不易去，此日始西東。","旅舍秋霖葉，行人寒草風。","酒醒餘恨在，野餞暫遊同。","莫使禰生刺，空留懷袖中。"]', '["羈貧不易去，此日始西东。","旅舍秋霖葉，行人寒草风。","酒醒餘恨在，野餞暫游同。","莫使禰生刺，空留懷袖中。"]', '诗', 'shi', '', NULL, '送盧堪 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3dc254c-55e1-4114-93e6-44ebc2f07232', '送柳震入蜀', '送柳震入蜀', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["粉堞連青氣，喧喧雜萬家。","夷人祠竹節，蜀鳥乳桐花。","酒報新豐景，琴迎抵峽斜。","多聞滯遊客，不似在天涯。"]', '["粉堞連青氣，喧喧杂万家。","夷人祠竹節，蜀鸟乳桐花。","酒報新豐景，琴迎抵峽斜。","多闻滯游客，不似在天涯。"]', '诗', 'shi', '', NULL, '送柳震入蜀 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c65a23c-f6bb-478e-8386-50278c0f0e1a', '送李嘉祐正字括圖書兼往揚州覲省', '送李嘉祐正字括圖书兼往揚州覲省', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["不事蘭臺貴，全多韋帶風。","儒官比劉向，使者得陳農。","晚燒平蕪外，朝陽疊浪東。","歸來喜調膳，寒筍出林中。"]', '["不事蘭台貴，全多韋带风。","儒官比劉向，使者得陳農。","晚燒平蕪外，朝陽叠浪东。","归来喜調膳，寒筍出林中。"]', '诗', 'shi', '', NULL, '送李嘉祐正字括圖書兼往揚州覲省 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ca822a6-8abd-42b0-a0cd-d38e81e22fb0', '送劉侍御', '送劉侍御', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["獄成收夜燭，整豸出登車。","黃葉辭荆楚，青山背漢初。","早朝新羽衞，晚下步徒胥。","應念長沙謫，思鄉不食魚。"]', '["獄成收夜燭，整豸出登车。","黄葉辞荆楚，青山背漢初。","早朝新羽衞，晚下步徒胥。","應念长沙謫，思乡不食鱼。"]', '诗', 'shi', '', NULL, '送劉侍御 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54e145bf-46ef-4ee6-8a40-7aaf46a35b14', '送龐判官赴黔中', '送龐判官赴黔中', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["天遠風煙異，西南見一方。","亂山來蜀道，諸水出辰陽。","堆案青油暮，看棋畫角長。","論文誰可制，記室有何郎。"]', '["天远风煙異，西南见一方。","亂山来蜀道，諸水出辰陽。","堆案青油暮，看棋畫角长。","論文誰可制，記室有何郎。"]', '诗', 'shi', '', NULL, '送龐判官赴黔中 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d668141d-a638-4b3d-af3a-fee7293fb90c', '送人遊嶺南', '送人游嶺南', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["萬里南遊客，交州見柳條。","逢迎人易合，時日酒能消。","浪曉浮青雀，風溫解黑貂。","囊金如未足，莫恨故鄉遙。"]', '["万里南游客，交州见柳條。","逢迎人易合，时日酒能消。","浪晓浮青雀，风溫解黑貂。","囊金如未足，莫恨故乡遙。"]', '诗', 'shi', '', NULL, '送人遊嶺南 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea112d09-8374-4aba-bdae-504d8c8d893c', '送曹同椅', '送曹同椅', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["青春三十餘，衆藝盡無如。","中散詩傳畫，將軍扇續書。","楚田晴下雁，江日暖遊魚。","惆悵空相送，歡遊自此疎。"]', '["青春三十餘，衆藝尽無如。","中散诗傳畫，將軍扇續书。","楚田晴下雁，江日暖游鱼。","惆悵空相送，歡游自此疎。"]', '诗', 'shi', '', NULL, '送曹同椅 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70bd18cf-3075-4752-8817-e591ace351e9', '送鄂州張別駕襄陽覲省', '送鄂州張別駕襄陽覲省', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["蒼蒼峴亭路，臘月漢陽春。","帶雪半山寺，行沙隔水人。","王祥因就宦，萊子不違親。","正恨殊鄉別，千條楚柳新。"]', '["蒼蒼峴亭路，臘月漢陽春。","带雪半山寺，行沙隔水人。","王祥因就宦，萊子不違親。","正恨殊乡別，千條楚柳新。"]', '诗', 'shi', '', NULL, '送鄂州張別駕襄陽覲省 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8095147b-d6cc-449c-9b3b-02996f626e1f', '送魏季羔遊長沙覲兄', '送魏季羔游长沙覲兄', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["蘆荻湘江水，蕭蕭萬里秋。","鶴高看迥野，蟬遠入中流。","訪友多成滯，攜家不厭遊。","惠連仍有作，知得從兄酬。"]', '["蘆荻湘江水，蕭蕭万里秋。","鹤高看迥野，蟬远入中流。","訪友多成滯，携家不厭游。","惠連仍有作，知得從兄酬。"]', '诗', 'shi', '', NULL, '送魏季羔遊長沙覲兄 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d52299f9-b685-4f94-bb8e-ea0d5a9e9069', '雜言', '杂言', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["伏餘西景移，風雨灑輕絺。","燕拂青蕪地，蟬鳴紅葉枝。"]', '["伏餘西景移，风雨灑轻絺。","燕拂青蕪地，蟬鳴紅葉枝。"]', '诗', 'shi', '', NULL, '雜言 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc51c891-8c40-4c18-9d15-a8530db21be0', '翫花與衞象同醉', '翫花與衞象同醉', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["衰鬢千莖雪，他鄉一樹花。","今朝與君醉，忘却在長沙。"]', '["衰鬢千莖雪，他乡一樹花。","今朝與君醉，忘却在长沙。"]', '诗', 'shi', '', NULL, '翫花與衞象同醉 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9a12ca0-3896-4787-a112-d9cbc41bac60', '送王尊師歸湖州', '送王尊師归湖州', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["煙蕪滿洞青山遶，幢節飄空紫鳳飛。","金闕乍看迎日麗，玉簫遙聽隔花微。","多開石髓供調膳，時御霓裳奉易衣。","莫學遼東華表上，千年始欲一迴歸。"]', '["煙蕪满洞青山遶，幢節飄空紫鳳飞。","金闕乍看迎日丽，玉簫遙听隔花微。","多开石髓供調膳，时御霓裳奉易衣。","莫学遼东华表上，千年始欲一迴归。"]', '诗', 'shi', '', NULL, '送王尊師歸湖州 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbe5c098-6fd2-4fdc-ace3-d7b049bc66c3', '九日洛東亭', '九日洛东亭', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["風息斜陽盡，遊人曲落間。","採花因覆酒，行草轉看山。","柳散新霜下，天晴早雁還。","傷秋非騎省，玄髮白成斑。"]', '["风息斜陽尽，游人曲落间。","採花因覆酒，行草轉看山。","柳散新霜下，天晴早雁還。","傷秋非騎省，玄髮白成斑。"]', '诗', 'shi', '', NULL, '九日洛東亭 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('402a706d-4568-471e-ac1f-e01a7f90f6cf', '九日送人', '九日送人', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["送人冠獬豸，值節佩茱萸。","均覆徵三壤，登車出五湖。","水風淒落日，岸葉颯衰蕪。","自恨塵中使，何因在路隅。"]', '["送人冠獬豸，值節佩茱萸。","均覆徵三壤，登车出五湖。","水风淒落日，岸葉颯衰蕪。","自恨塵中使，何因在路隅。"]', '诗', 'shi', '', NULL, '九日送人 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('287ab2db-8089-4449-bfaa-a292facd81cf', '哭王注', '哭王注', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["已歎漳濱臥，何言駐隙難。","異才傷促短，諸友哭門闌。","古道松聲暮，荒阡草色寒。","延陵今葬子，空使魯人觀。"]', '["已歎漳濱臥，何言駐隙难。","異才傷促短，諸友哭门闌。","古道松声暮，荒阡草色寒。","延陵今葬子，空使魯人观。"]', '诗', 'shi', '', NULL, '哭王注 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('871acf59-5c9b-4ed7-b140-d0c524481dca', '遇谷口道士', '遇谷口道士', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["一見林中客，閑知州縣勞。","白雲秋色遠，蒼嶺夕陽高。","自說名因石，誰逢手種桃。","丹經儻相授，何用戀青袍。"]', '["一见林中客，闲知州縣勞。","白云秋色远，蒼嶺夕陽高。","自说名因石，誰逢手種桃。","丹經儻相授，何用戀青袍。"]', '诗', 'shi', '', NULL, '遇谷口道士 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0cd6afd-c89d-4fc3-b214-bcbf63042e8e', '喜外弟盧綸見宿', '喜外弟盧綸见宿', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["靜夜四無鄰，荒居舊業貧。","雨中黃葉樹，燈下白頭人。","以我獨沈久，愧君相見頻。","平生自有分，況是蔡家親。"]', '["静夜四無鄰，荒居旧業貧。","雨中黄葉樹，灯下白头人。","以我独沈久，愧君相见頻。","平生自有分，況是蔡家親。"]', '诗', 'shi', '', NULL, '喜外弟盧綸見宿 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99b28edd-1f27-415b-993f-f7ca05f18279', '深上人見訪憶李端', '深上人见訪憶李端', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["雁稀秋色盡，落日對寒山。","避事多稱疾，留僧獨閉關。","心歸塵俗外，道勝有無間。","仍憶東林友，相期久不還。"]', '["雁稀秋色尽，落日对寒山。","避事多稱疾，留僧独閉关。","心归塵俗外，道勝有無间。","仍憶东林友，相期久不還。"]', '诗', 'shi', '', NULL, '深上人見訪憶李端 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc1afbea-10f7-4e8d-b768-da36dfa19bab', '宿青龍寺故曇上人院', '宿青龙寺故曇上人院', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["年深宮院在，舊客自相逢。","閉戶臨寒竹，無人有夜鐘。","降龍今已去，巢鶴竟何從。","坐見繁星曉，淒涼識舊峯。"]', '["年深宮院在，旧客自相逢。","閉戶臨寒竹，無人有夜鐘。","降龙今已去，巢鹤竟何從。","坐见繁星晓，淒涼識旧峯。"]', '诗', 'shi', '', NULL, '宿青龍寺故曇上人院 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d41d9356-525f-4680-93cc-724d67035925', '送張鍊師還峨嵋山', '送張鍊師還峨嵋山', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["太一天壇天柱西，垂蘿爲幌石爲梯。","前登靈境青霄絕，下視人間白日低。","松籟萬聲和管磐，丹光五色雜虹蜺。","春山一入尋無路，鳥響煙深水滿溪。"]', '["太一天壇天柱西，垂蘿爲幌石爲梯。","前登靈境青霄絕，下視人间白日低。","松籟万声和管磐，丹光五色杂虹蜺。","春山一入尋無路，鸟响煙深水满溪。"]', '诗', 'shi', '', NULL, '送張鍊師還峨嵋山 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58fe608e-8583-4be2-951a-4303ebac66f3', '逢江客問南中故人因以詩寄', '逢江客问南中故人因以诗寄', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["南客何時去，相逢問故人。","望鄉空淚落，嗜酒轉家貧。","疎嬾辭微祿，東西任老身。","上樓多看月，臨水共傷春。","五柳終期隱，雙鷗自可親。","應憐折腰吏，冉冉在風塵。"]', '["南客何时去，相逢问故人。","望乡空泪落，嗜酒轉家貧。","疎嬾辞微祿，东西任老身。","上楼多看月，臨水共傷春。","五柳終期隐，雙鷗自可親。","應怜折腰吏，冉冉在风塵。"]', '诗', 'shi', '', NULL, '逢江客問南中故人因以詩寄 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a5a657c-624e-44c1-8abd-4318953d1c56', '送臯法師', '送臯法師', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["江草知寒柳半衰，行吟怨別獨遲遲。","何人講席投如意，唯有東林遠法師。"]', '["江草知寒柳半衰，行吟怨別独遲遲。","何人講席投如意，唯有东林远法師。"]', '诗', 'shi', '', NULL, '送臯法師 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47fed2c6-8061-49e1-9228-ae17232c6026', '送鄭佶歸洛陽', '送鄭佶归洛陽', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["蒼蒼楚色水雲間，一醉春風送爾還。","何處鄉心最堪羨，汝南初見洛陽山。"]', '["蒼蒼楚色水云间，一醉春风送爾還。","何处乡心最堪羨，汝南初见洛陽山。"]', '诗', 'shi', '', NULL, '送鄭佶歸洛陽 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47e070ca-4722-4870-a959-ed38b3eeca3e', '分流水', '分流水', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["古時愁別淚，滴作分流水。","日夜東西流，分流幾千里。","通塞兩不見，波瀾各自起。","與君相背飛，去去心如此。"]', '["古时愁別泪，滴作分流水。","日夜东西流，分流幾千里。","通塞兩不见，波瀾各自起。","與君相背飞，去去心如此。"]', '诗', 'shi', '', NULL, '分流水 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bcc43ce-4c7c-4339-8b24-3c3cb0e5dad3', '和耿拾遺元日觀早朝', '和耿拾遺元日观早朝', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["元日爭朝闕，奔流若會溟。","路塵和薄霧，騎火接低星。","門響雙魚鑰，車喧百子鈴。","冕旒當翠殿，幢戟滿彤庭。","積歲方編瑞，乘春即省刑。","大官陳禹玉，司曆獻堯蓂。","壽酒三觴退，簫韶九奏停。","太陽開物象，霈澤及生靈。","南陌高山碧，東方曉氣青。","自憐揚子賤，歸草太玄經。"]', '["元日爭朝闕，奔流若會溟。","路塵和薄霧，騎火接低星。","门响雙鱼鑰，车喧百子鈴。","冕旒當翠殿，幢戟满彤庭。","積歲方編瑞，乘春即省刑。","大官陳禹玉，司曆獻堯蓂。","壽酒三觴退，簫韶九奏停。","太陽开物象，霈澤及生靈。","南陌高山碧，东方晓氣青。","自怜揚子賤，归草太玄經。"]', '诗', 'shi', '', NULL, '和耿拾遺元日觀早朝 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd7eeaf4-69cf-42f4-8f43-ef2f8ec7dcbc', '塞下曲', '塞下曲', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["寒柳接胡桑，軍門向大荒。","幕營隨月魄，兵氣長星芒。","橫吹催春酒，重裘隔夜霜。","冰開不防虜，青草滿遼陽。"]', '["寒柳接胡桑，軍门向大荒。","幕營隨月魄，兵氣长星芒。","橫吹催春酒，重裘隔夜霜。","冰开不防虜，青草满遼陽。"]', '诗', 'shi', '', NULL, '塞下曲 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d526d975-3b1e-45d9-9424-dc49390a5f7b', '關山月', '关山月', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["蒼茫明月上，夜久光如積。","野幕冷胡霜，關樓宿邊客。","隴頭秋露暗，磧外寒沙白。","唯有故鄉人，霑裳此聞笛。"]', '["蒼茫明月上，夜久光如積。","野幕冷胡霜，关楼宿邊客。","隴头秋露暗，磧外寒沙白。","唯有故乡人，霑裳此闻笛。"]', '诗', 'shi', '', NULL, '關山月 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb161a4b-f295-4b84-8cdf-e0c9a6ac7ccd', '御製雨後出城觀覽敕朝臣已下屬和', '御製雨後出城观覽敕朝臣已下屬和', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["上上開鶉野，師師出鳳城。","因知聖主念，得遂老農情。","隴麥垂秋合，郊塵得雨清。","時新薦玄祖，歲足富蒼生。","却馬川原靜，聞雞水土平。","薰弦歌舜德，和鼎致堯名。","覽物欣多稼，垂衣御大明。","史官何所錄，稱瑞滿天京。"]', '["上上开鶉野，師師出鳳城。","因知聖主念，得遂老農情。","隴麦垂秋合，郊塵得雨清。","时新薦玄祖，歲足富蒼生。","却马川原静，闻雞水土平。","薰弦歌舜德，和鼎致堯名。","覽物欣多稼，垂衣御大明。","史官何所錄，稱瑞满天京。"]', '诗', 'shi', '', NULL, '御製雨後出城觀覽敕朝臣已下屬和 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a13013e-1cb5-439f-928e-e2a2026356ca', '奉和常舍人晚秋集賢院即事寄徐薛二侍郎', '奉和常舍人晚秋集賢院即事寄徐薛二侍郎', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["藹藹鳳凰宮，蘭臺玉署通。","夜霜凝樹羽，朝日照相風。","官附三台貴，儒開百氏宗。","司言陳禹命，侍講發堯聰。","香卷青編內，鉛分綠字中。","綴籤從太史，鏘佩揖羣公。","池接天泉碧，林交御果紅。","寒龜登故葉，秋蝶戀疎藂。","顏謝徵文並，鍾裴直事同。","離羣驚海鶴，屬思怨江楓。","地遠姑蘇外，山長越絕東。","慙當哲匠後，下曲本難工。"]', '["藹藹鳳凰宮，蘭台玉署通。","夜霜凝樹羽，朝日照相风。","官附三台貴，儒开百氏宗。","司言陳禹命，侍講發堯聰。","香卷青編內，鉛分綠字中。","綴籤從太史，鏘佩揖羣公。","池接天泉碧，林交御果紅。","寒龟登故葉，秋蝶戀疎藂。","顏謝徵文並，鍾裴直事同。","離羣驚海鹤，屬思怨江楓。","地远姑蘇外，山长越絕东。","慙當哲匠後，下曲本难工。"]', '诗', 'shi', '', NULL, '奉和常舍人晚秋集賢院即事寄徐薛二侍郎 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b50750a-2f2f-48b4-b711-1c34c088006e', '題鮮于秋林園', '題鲜于秋林园', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["雨後園林好，幽行迥野通。","遠山芳草外，流水落花中。","客醉悠悠慣，鶯啼處處同。","夕陽自一望，日暮杜陵東。"]', '["雨後园林好，幽行迥野通。","远山芳草外，流水落花中。","客醉悠悠慣，鶯啼处处同。","夕陽自一望，日暮杜陵东。"]', '诗', 'shi', '', NULL, '題鮮于秋林園 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8f5cfed-2300-4d3a-8112-c63dd4c433dd', '登秦嶺', '登秦嶺', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["南登秦嶺頭，迴首始堪憂。","漢闕青門遠，商山藍水流。","三湘遷客去，九陌故人遊。","從此思鄉淚，雙垂不復收。"]', '["南登秦嶺头，迴首始堪憂。","漢闕青门远，商山藍水流。","三湘遷客去，九陌故人游。","從此思乡泪，雙垂不复收。"]', '诗', 'shi', '', NULL, '登秦嶺 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('362ee93e-9b20-4082-a797-bc339355f3be', '獨遊寄衞長林', '独游寄衞长林', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["草綠春陽動，遲遲澤畔遊。","戀花同野蝶，愛水劇江鷗。","身外唯須醉，人間盡是愁。","那知鳴玉者，不羨賣瓜侯。"]', '["草綠春陽动，遲遲澤畔游。","戀花同野蝶，愛水劇江鷗。","身外唯須醉，人间尽是愁。","那知鳴玉者，不羨賣瓜侯。"]', '诗', 'shi', '', NULL, '獨遊寄衞長林 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98ab1638-8308-40ae-9ed4-ddf81aeb2e86', '望水', '望水', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["高樓晴見水，楚色靄相和。","野極空如練，天遙不辨波。","永無人跡到，時有鳥行過。","況是蒼茫外，殘陽照最多。"]', '["高楼晴见水，楚色靄相和。","野極空如練，天遙不辨波。","永無人跡到，时有鸟行過。","況是蒼茫外，殘陽照最多。"]', '诗', 'shi', '', NULL, '望水 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('158d2496-f9df-4212-9997-7000227153dd', '望商山路', '望商山路', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["南見青山道，依然去國時。","已甘長避地，誰料有還期。","雨霽殘陽薄，人愁獨望遲。","空殘華髮在，前事不堪思。"]', '["南见青山道，依然去国时。","已甘长避地，誰料有還期。","雨霽殘陽薄，人愁独望遲。","空殘华髮在，前事不堪思。"]', '诗', 'shi', '', NULL, '望商山路 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35638e63-ef59-411d-a832-af24221fd0fd', '題落葉', '題落葉', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["霜景催危葉，今朝半樹空。","蕭條故國異，零落旅人同。","颯岸浮寒水，依堦擁夜蟲。","隨風偏可羨，得到洛陽宮。"]', '["霜景催危葉，今朝半樹空。","蕭條故国異，零落旅人同。","颯岸浮寒水，依堦擁夜蟲。","隨风偏可羨，得到洛陽宮。"]', '诗', 'shi', '', NULL, '題落葉 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b4fd6dd-f1dc-418d-88b1-9ee28f90a2d7', '寄準上人', '寄準上人', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["昨聞歸舊寺，暫別欲經年。","樵客應同步，鄰僧定伴禪。","後峯秋有雪，遠澗夜鳴泉。","偶與支公論，人間自共傳。"]', '["昨闻归旧寺，暫別欲經年。","樵客應同步，鄰僧定伴禪。","後峯秋有雪，远澗夜鳴泉。","偶與支公論，人间自共傳。"]', '诗', 'shi', '', NULL, '寄準上人 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7ace9a5-8100-4da9-b819-4f45d0f80d0b', '送況上人還荆州因寄衞侍御象', '送況上人還荆州因寄衞侍御象', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["惠持遊蜀久，策杖欲西還。","共別此宵月，獨歸何處山。","對鷗沙草畔，洗足野雲間。","知有玄暉會，齋心受八關。"]', '["惠持游蜀久，策杖欲西還。","共別此宵月，独归何处山。","对鷗沙草畔，洗足野云间。","知有玄暉會，斋心受八关。"]', '诗', 'shi', '', NULL, '送況上人還荆州因寄衞侍御象 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f3920b1-4088-40d9-a888-98e8869adcf1', '別盧綸', '別盧綸', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["有月多共賞，無秋不共悲。","如何與君別，又是菊黃時。"]', '["有月多共賞，無秋不共悲。","如何與君別，又是菊黄时。"]', '诗', 'shi', '', NULL, '別盧綸 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e072c7f0-1d16-4941-8ded-6703c9f66b44', '雪二首 一', '雪二首 一', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["樂遊春苑望鵝毛，宮殿如星樹似毫。","漫漫一川橫渭水，太陽初出五陵高。"]', '["乐游春苑望鵝毛，宮殿如星樹似毫。","漫漫一川橫渭水，太陽初出五陵高。"]', '诗', 'shi', '', NULL, '雪二首 一 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac9ff20b-28e5-41f5-b1ef-596dab0894cf', '雪二首 二', '雪二首 二', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["王屋南崖見洛城，石龕松寺上方平。","半山槲葉當窗下，一夜曾聞雪打聲。"]', '["王屋南崖见洛城，石龕松寺上方平。","半山槲葉當窗下，一夜曾闻雪打声。"]', '诗', 'shi', '', NULL, '雪二首 二 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01c7e7af-0460-4a15-adfe-a0b9b60a6d4e', '酬衞長林歲日見呈', '酬衞长林歲日见呈', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["地暖雪花摧，天春斗柄迴。","朱泥一丸藥，柏葉萬年杯。","旅雁辭人去，繁霜滿鏡來。","今朝彩盤上，神燕不須雷。"]', '["地暖雪花摧，天春斗柄迴。","朱泥一丸藥，柏葉万年杯。","旅雁辞人去，繁霜满镜来。","今朝彩盤上，神燕不須雷。"]', '诗', 'shi', '', NULL, '酬衞長林歲日見呈 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90ebf7a8-e3e4-4f50-8f66-fe0f412398c2', '杜鵑行', '杜鵑行', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["古時杜宇稱望帝，魂作杜鵑何微細。","跳枝竄葉樹木中，搶翔瞥捩雌隨雄。","毛衣慘黑自顦顇，衆鳥安肯相尊崇。","隳形不敢栖華屋，短翮唯願巢深叢。","穿皮啄朽觜欲禿，苦飢始得食一蟲。","誰言養雛不自哺，此語亦足爲愚蒙。","聲音咽噦若有謂，號啼略與嬰兒同。","口乾垂血轉迫促，似欲上訴於蒼穹。","蜀人聞之皆起立，至今相效傳遺風。","乃知變化不可窮，豈知昔日居深宮，嬪妃左右如花紅。"]', '["古时杜宇稱望帝，魂作杜鵑何微細。","跳枝竄葉樹木中，搶翔瞥捩雌隨雄。","毛衣慘黑自顦顇，衆鸟安肯相尊崇。","隳形不敢栖华屋，短翮唯願巢深叢。","穿皮啄朽觜欲禿，苦飢始得食一蟲。","誰言養雛不自哺，此語亦足爲愚蒙。","声音咽噦若有謂，號啼略與嬰兒同。","口乾垂血轉迫促，似欲上訴於蒼穹。","蜀人闻之皆起立，至今相效傳遺风。","乃知变化不可窮，豈知昔日居深宮，嬪妃左右如花紅。"]', '诗', 'shi', '', NULL, '杜鵑行 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1246e3b2-e4cc-4cea-b01d-6b1e3bae4d6b', '寄胡居士', '寄胡居士', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["日暖風微南陌頭，青田紅樹起春愁。","伯勞相逐行人別，岐路空歸野水流。","徧地尋僧同看雪，誰期載酒共登樓。","爲言惆悵嵩陽寺，明月高松應獨遊。"]', '["日暖风微南陌头，青田紅樹起春愁。","伯勞相逐行人別，岐路空归野水流。","徧地尋僧同看雪，誰期載酒共登楼。","爲言惆悵嵩陽寺，明月高松應独游。"]', '诗', 'shi', '', NULL, '寄胡居士 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dafd746b-c98e-4cb3-973d-952bbb683383', '寒塘', '寒塘', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["曉髮梳臨水，寒塘坐見秋。","鄉心正無限，一雁度南樓。"]', '["晓髮梳臨水，寒塘坐见秋。","乡心正無限，一雁度南楼。"]', '诗', 'shi', '', NULL, '寒塘 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8474ce5-372b-49a0-bdf2-0fe91fdd5c73', '爲李魏公賦謝汧公', '爲李魏公賦謝汧公', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["白雪高吟際，青霄遠望中。","誰言路遐曠，宮徵暗相通。"]', '["白雪高吟際，青霄远望中。","誰言路遐曠，宮徵暗相通。"]', '诗', 'shi', '', NULL, '爲李魏公賦謝汧公 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b0170c8-424f-4f0a-aaa3-b984ddffbfd4', '梁城老人怨', '梁城老人怨', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["朝爲耕鐘人，暮作刀槍鬼。","相看父子血，共染城壕水。"]', '["朝爲耕鐘人，暮作刀槍鬼。","相看父子血，共染城壕水。"]', '诗', 'shi', '', NULL, '梁城老人怨 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46e49082-f006-4157-b5e7-3c821cac0e42', '揚州選蒙相公賞判雪後呈上', '揚州選蒙相公賞判雪後呈上', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["自得山公許，休畊海上田。","慙看長史傳，欲棄釣魚船。","窮巷殷憂日，蕪城雨雪天。","此時瞻相府，心事比旌懸。"]', '["自得山公許，休畊海上田。","慙看长史傳，欲棄釣鱼船。","窮巷殷憂日，蕪城雨雪天。","此时瞻相府，心事比旌懸。"]', '诗', 'shi', '', NULL, '揚州選蒙相公賞判雪後呈上 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('039c2a5b-73bc-47b4-a6dd-68cb46a8dc59', '客舍書情寄趙中丞', '客舍书情寄趙中丞', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["東楚復西秦，浮雲類此身。","關山勞策蹇，僮僕慣投人。","孤客來千里，全家託四鄰。","生涯難自料，中夜問[情親]。"]', '["东楚复西秦，浮云類此身。","关山勞策蹇，僮僕慣投人。","孤客来千里，全家託四鄰。","生涯难自料，中夜问[情親]。"]', '诗', 'shi', '', NULL, '客舍書情寄趙中丞 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b12c992-250e-4231-9b19-8fada6c0f668', '客舍有懷因呈諸在事', '客舍有懷因呈諸在事', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["讀書常苦節，待詔豈辭貧。","暮雪猶驅馬，晡飡又寄人。","愁來占吉夢，老去惜良辰。","延首平津閣，家山日已春。"]', '["读书常苦節，待詔豈辞貧。","暮雪猶驱马，晡飡又寄人。","愁来占吉梦，老去惜良辰。","延首平津閣，家山日已春。"]', '诗', 'shi', '', NULL, '客舍有懷因呈諸在事 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9049867-1c05-4ba5-b3cc-ac55fe3ea20e', '書懷寄楊郭李王判官', '书懷寄楊郭李王判官', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["慣作雲林客，因成懶漫人。","吏欺從政拙，妻笑理家貧。","李郭應時望，王楊入幕頻。","從容丞相閣，知憶故園春。"]', '["慣作云林客，因成懶漫人。","吏欺從政拙，妻笑理家貧。","李郭應时望，王楊入幕頻。","從容丞相閣，知憶故园春。"]', '诗', 'shi', '', NULL, '書懷寄楊郭李王判官 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04ff6d31-d3fb-4343-aedd-7a53a106b470', '奉和給事寓直', '奉和給事寓直', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["桂枝家共折，雞樹代相傳。","忝向鸞臺下，仍看鴈影連。","夜閑方步月，漏盡欲朝天。","知去丹墀近，明王許薦賢。"]', '["桂枝家共折，雞樹代相傳。","忝向鸾台下，仍看鴈影連。","夜闲方步月，漏尽欲朝天。","知去丹墀近，明王許薦賢。"]', '诗', 'shi', '', NULL, '奉和給事寓直 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfa6b0e2-6fe0-4840-bb51-b27d4d8c1afb', '初入集賢院贈李獻仁', '初入集賢院贈李獻仁', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["燕代官初罷，江湖路便分。","九遷從命薄，四十幸人聞。","跡愧趨丹禁，身曾繫白雲。","何由返滄海，昨日謁明君。"]', '["燕代官初罷，江湖路便分。","九遷從命薄，四十幸人闻。","跡愧趨丹禁，身曾繫白云。","何由返滄海，昨日謁明君。"]', '诗', 'shi', '', NULL, '初入集賢院贈李獻仁 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8c0b596-d5d0-4073-9f9f-ecef8025dac2', '酬李補闕雨中寄贈', '酬李補闕雨中寄贈', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["十年隨馬宿，幾度受人恩。","白髮還鄉井，微官有子孫。","竹窗寒雨滴，苦砌夜蟲喧。","獨媿東垣友，新詩慰旅魂。"]', '["十年隨马宿，幾度受人恩。","白髮還乡井，微官有子孫。","竹窗寒雨滴，苦砌夜蟲喧。","独媿东垣友，新诗慰旅魂。"]', '诗', 'shi', '', NULL, '酬李補闕雨中寄贈 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b9258ce-f8d6-417d-8bb1-aac8b4b0b653', '初除拾遺酬丘二十二見寄', '初除拾遺酬丘二十二见寄', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["江海久垂綸，朝衣忽掛身。","丹墀初謁帝，白髮免羞人。","才愧文章士，名當諫諍臣。","空餘薦賢分，不敢負交親。"]', '["江海久垂綸，朝衣忽掛身。","丹墀初謁帝，白髮免羞人。","才愧文章士，名當諫諍臣。","空餘薦賢分，不敢負交親。"]', '诗', 'shi', '', NULL, '初除拾遺酬丘二十二見寄 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3abc38e4-f4ce-4a03-8cff-368a950c86e6', '劉展下判官相招以詩答之', '劉展下判官相招以诗答之', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["國有非常寵，家承異姓勳。","背恩慙皎日，不義若浮雲。","但使忠貞在，甘從玉石焚。","竄身如有地，夢寐見明君。"]', '["国有非常寵，家承異姓勳。","背恩慙皎日，不義若浮云。","但使忠貞在，甘從玉石焚。","竄身如有地，梦寐见明君。"]', '诗', 'shi', '', NULL, '劉展下判官相招以詩答之 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('651ebe46-5927-4e46-8cec-68edf7f09fa8', '送侯山人赴會稽', '送侯山人赴會稽', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["仙客辭蘿月，東來就一官。","且歸滄海住，猶向白雲看。","猨呌江天暮，蟲聲野浦寒。","時遊鏡湖裏，爲我把魚竿。"]', '["仙客辞蘿月，东来就一官。","且归滄海住，猶向白云看。","猨呌江天暮，蟲声野浦寒。","时游镜湖裏，爲我把鱼竿。"]', '诗', 'shi', '', NULL, '送侯山人赴會稽 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5388c512-5dad-4b5d-87a2-146786df0636', '宿禪智寺上方演大師院', '宿禪智寺上方演大師院', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["石林高幾許，金剎在中峰。","白日空山梵，清霜後夜鐘。","竹窗迴翠壁，苔徑入寒松。","幸接無生法，疑心怯所從。"]', '["石林高幾許，金剎在中峰。","白日空山梵，清霜後夜鐘。","竹窗迴翠壁，苔徑入寒松。","幸接無生法，疑心怯所從。"]', '诗', 'shi', '', NULL, '宿禪智寺上方演大師院 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8da62a2e-2782-4b7a-80c7-45042284ffc2', '題空山人石室', '題空山人石室', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["早晚悟無生，頭陀不到城。","雲山知夏臘，猨鳥見修行。","地僻無溪路，人尋逐水聲。","年年深谷裏，誰識遠公名。"]', '["早晚悟無生，头陀不到城。","云山知夏臘，猨鸟见修行。","地僻無溪路，人尋逐水声。","年年深谷裏，誰識远公名。"]', '诗', 'shi', '', NULL, '題空山人石室 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c418f6a0-9c6d-4a70-a409-c37c02297314', '登蔣山開善寺', '登蔣山开善寺', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["山殿秋雲裏，香煙出翠微。","客尋朝磬至，僧背夕陽歸。","下界千門見，前朝萬事非。","看心兼送目，葭菼暮依依。"]', '["山殿秋云裏，香煙出翠微。","客尋朝磬至，僧背夕陽归。","下界千门见，前朝万事非。","看心兼送目，葭菼暮依依。"]', '诗', 'shi', '', NULL, '登蔣山開善寺 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33328b3c-5773-4538-b70e-8b58e019a2cf', '題崇福寺禪院', '題崇福寺禪院', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["僧家竟何事，掃地與焚香。","清磬度山翠，閑雲來竹房。","身心塵外遠，歲月坐中長。","向晚禪堂掩，無人空夕陽。"]', '["僧家竟何事，掃地與焚香。","清磬度山翠，闲云来竹房。","身心塵外远，歲月坐中长。","向晚禪堂掩，無人空夕陽。"]', '诗', 'shi', '', NULL, '題崇福寺禪院 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5d27367-62b7-4b9a-b66c-bbaff3d2ea33', '秋晚送丹徒許明府赴上國因寄江南故人', '秋晚送丹徒許明府赴上国因寄江南故人', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["秋暮之彭澤，籬花遠近逢。","君書前日至，別後此時重。","寒夜江邊月，晴天海上峰。","還知南地客，招引住新豐。"]', '["秋暮之彭澤，籬花远近逢。","君书前日至，別後此时重。","寒夜江邊月，晴天海上峰。","還知南地客，招引住新豐。"]', '诗', 'shi', '', NULL, '秋晚送丹徒許明府赴上國因寄江南故人 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b721a577-dbff-480d-8b3a-76be13b31f02', '送薛仲方歸揚州', '送薛仲方归揚州', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["佳句應無敵，貞心不有猜。","慙爲丈人行，怯見後生才。","泛舸貪斜月，浮橈值早梅。","綠楊新過雨，芳草待君來。"]', '["佳句應無敵，貞心不有猜。","慙爲丈人行，怯见後生才。","泛舸貪斜月，浮橈值早梅。","綠楊新過雨，芳草待君来。"]', '诗', 'shi', '', NULL, '送薛仲方歸揚州 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3026b4a-e2e5-47f8-8497-ae73399bda6b', '送韋員外還京', '送韋員外還京', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["十年離亂後，此去若爲情。","春晚香山綠，人稀豫水清。","野陂看獨樹，關路逐殘鶯。","前殿朝明主，應憐白髮生。"]', '["十年離亂後，此去若爲情。","春晚香山綠，人稀豫水清。","野陂看独樹，关路逐殘鶯。","前殿朝明主，應怜白髮生。"]', '诗', 'shi', '', NULL, '送韋員外還京 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d73d10a5-8b43-46b7-8106-de6ed2153d66', '潤州送友人', '潤州送友人', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["見君還此地，灑淚向江邊。","國士勞相問，家書無處傳。","荒城胡馬跡，塞木戍人煙。","一路堪愁思，孤舟何渺然。"]', '["见君還此地，灑泪向江邊。","国士勞相问，家书無处傳。","荒城胡马跡，塞木戍人煙。","一路堪愁思，孤舟何渺然。"]', '诗', 'shi', '', NULL, '潤州送友人 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27ae9cbd-2344-4e12-8ce8-24adabd11486', '送張芬東歸', '送張芬东归', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["喧喧五衢上，鞍馬自驅馳。","落日臨阡陌，貧交欲別離。","早知時事異，堪與世人隨。","握手將何贈，君心我獨知。"]', '["喧喧五衢上，鞍马自驱驰。","落日臨阡陌，貧交欲別離。","早知时事異，堪與世人隨。","握手將何贈，君心我独知。"]', '诗', 'shi', '', NULL, '送張芬東歸 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58703b0a-258d-4de7-bb1e-c6587cb8bfea', '送蘇脩遊上饒', '送蘇脩游上饒', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["愛爾無羈束，雲山恣意過。","一身隨遠岫，孤棹任輕波。","世事關情少，漁家寄宿多。","蘆花淺淡處，江月奈人何。"]', '["愛爾無羈束，云山恣意過。","一身隨远岫，孤棹任轻波。","世事关情少，漁家寄宿多。","蘆花淺淡处，江月奈人何。"]', '诗', 'shi', '', NULL, '送蘇脩遊上饒 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('838ed701-495c-4c25-940a-ff012b60414a', '送陸明府之盱眙', '送陸明府之盱眙', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["陶令之官去，窮愁慘別魂。","白煙橫海戍，紅葉下淮村。","澹浪搖山郭，平蕪到縣門。","政成堪吏隱，免負府公恩。"]', '["陶令之官去，窮愁慘別魂。","白煙橫海戍，紅葉下淮村。","澹浪搖山郭，平蕪到縣门。","政成堪吏隐，免負府公恩。"]', '诗', 'shi', '', NULL, '送陸明府之盱眙 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('931833f0-e0e1-4904-a4b3-2183940856c7', '江南迴逢趙曜因送任十一赴交城主簿', '江南迴逢趙曜因送任十一赴交城主簿', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["江上長相憶，因高北望看。","不知攜老幼，何處度艱難。","屈指同人盡，傷心故里殘。","遙憐驅匹馬，白首到微官。"]', '["江上长相憶，因高北望看。","不知携老幼，何处度艱难。","屈指同人尽，傷心故里殘。","遙怜驱匹马，白首到微官。"]', '诗', 'shi', '', NULL, '江南迴逢趙曜因送任十一赴交城主簿 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('377fd9dd-3ab4-4bb4-8eaa-6a5334b38d14', '送薛良史往越州謁從叔', '送薛良史往越州謁從叔', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["辭家年已久，與子分偏深。","易得相思淚，難爲欲別心。","孤雲隨浦口，幾日到山陰。","遙想蘭亭下，清風滿竹林。"]', '["辞家年已久，與子分偏深。","易得相思泪，难爲欲別心。","孤云隨浦口，幾日到山陰。","遙想蘭亭下，清风满竹林。"]', '诗', 'shi', '', NULL, '送薛良史往越州謁從叔 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db8be32b-7191-4e61-a10f-1d3a20f533e9', '送丘二十二之蘇州', '送丘二十二之蘇州', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["積水與寒煙，嘉禾路幾千。","孤猨啼海島，羣雁起湖田。","曾見長洲苑，嘗聞大雅篇。","却將封事去，知爾愛閑眠。"]', '["積水與寒煙，嘉禾路幾千。","孤猨啼海島，羣雁起湖田。","曾见长洲苑，嘗闻大雅篇。","却將封事去，知爾愛闲眠。"]', '诗', 'shi', '', NULL, '送丘二十二之蘇州 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ea76149-dd97-4cd4-9564-7595c9df1506', '登潤州芙蓉樓', '登潤州芙蓉楼', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["上古人何在，東流水不歸。","往來潮有信，朝暮事成非。","煙樹臨沙靜，雲帆入海稀。","郡樓多逸興，良牧謝玄暉。"]', '["上古人何在，东流水不归。","往来潮有信，朝暮事成非。","煙樹臨沙静，云帆入海稀。","郡楼多逸兴，良牧謝玄暉。"]', '诗', 'shi', '', NULL, '登潤州芙蓉樓 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8cb002c-be55-4c7b-8725-3983ebec476f', '江上書懷', '江上书懷', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["骨肉天涯別，江山日落時。","淚流襟上血，髮變鏡中絲。","胡越書難到，存亡夢豈知。","登高回首罷，形影自相隨。"]', '["骨肉天涯別，江山日落时。","泪流襟上血，髮变镜中絲。","胡越书难到，存亡梦豈知。","登高回首罷，形影自相隨。"]', '诗', 'shi', '', NULL, '江上書懷 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6d2af85-ad87-42c8-97b9-5f6e32b4950d', '春日憶姚氏外甥', '春日憶姚氏外甥', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["離亂人相失，春秋鴈自飛。","祗緣行路遠，未必寄書稀。","二月花無數，頻年意有違。","落暉看過後，獨坐淚沾衣。"]', '["離亂人相失，春秋鴈自飞。","祗緣行路远，未必寄书稀。","二月花無數，頻年意有違。","落暉看過後，独坐泪沾衣。"]', '诗', 'shi', '', NULL, '春日憶姚氏外甥 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc1b6105-9342-4aa3-9872-516886fd2e5a', '送真上人還蘭若', '送真上人還蘭若', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["得道雲林久，年深暫一歸。","出山逢世亂，乞食覺人稀。","半偈初傳法，中峰又掩扉。","愛憎應不染，塵俗自依依。"]', '["得道云林久，年深暫一归。","出山逢世亂，乞食覺人稀。","半偈初傳法，中峰又掩扉。","愛憎應不染，塵俗自依依。"]', '诗', 'shi', '', NULL, '送真上人還蘭若 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f0f738a-0f5a-4646-8f7e-21f4a86c763d', '潤州送師弟自江夏往台州', '潤州送師弟自江夏往台州', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["遠客乘流去，孤帆向夜開。","春風江上使，前日漢陽來。","別路猶千里，離心重一杯。","剡溪木未落，羨爾過天台。"]', '["远客乘流去，孤帆向夜开。","春风江上使，前日漢陽来。","別路猶千里，離心重一杯。","剡溪木未落，羨爾過天台。"]', '诗', 'shi', '', NULL, '潤州送師弟自江夏往台州 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93ea6203-85b0-4aff-a8c1-6b017c83f05c', '送李道士歸山', '送李道士归山', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["秋城臨古路，城上望君還。","曠野入寒草，獨行隨遠山。","授人鴻寶內，將犬白雲間。","早晚燒丹罷，遙知冰雪寒。"]', '["秋城臨古路，城上望君還。","曠野入寒草，独行隨远山。","授人鴻寶內，將犬白云间。","早晚燒丹罷，遙知冰雪寒。"]', '诗', 'shi', '', NULL, '送李道士歸山 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c55add81-d6ba-4c4d-bc3d-346914766a12', '宿江西竇主簿廳', '宿江西竇主簿廳', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["廣庭方緩步，星漢話中移。","月滿關山道，烏啼霜樹枝。","時艱難會合，年長重親知。","前事成金石，悽然淚欲垂。"]', '["廣庭方緩步，星漢話中移。","月满关山道，烏啼霜樹枝。","时艱难會合，年长重親知。","前事成金石，悽然泪欲垂。"]', '诗', 'shi', '', NULL, '宿江西竇主簿廳 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('580aa9a1-188d-4ba7-abae-7cdf6e2ac289', '喜逢妻弟鄭損因送入京', '喜逢妻弟鄭損因送入京', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["亂後自江城，相逢喜復驚。","爲經多載別，欲問小時名。","對酒悲前事，論文畏後生。","遙知盈卷軸，紙貴在江城。"]', '["亂後自江城，相逢喜复驚。","爲經多載別，欲问小时名。","对酒悲前事，論文畏後生。","遙知盈卷軸，紙貴在江城。"]', '诗', 'shi', '', NULL, '喜逢妻弟鄭損因送入京 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f25f510-e1a5-4803-89a9-d16c13d6013e', '詠門下畫小松上元王杜三相公', '詠门下畫小松上元王杜三相公', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["昔聞生澗底，今見起毫端。","衆草此時沒，何人知歲寒。","豈能裨棟宇，且貴出門闌。","只在丹青意，凌雲也不難。"]', '["昔闻生澗底，今见起毫端。","衆草此时沒，何人知歲寒。","豈能裨棟宇，且貴出门闌。","只在丹青意，凌云也不难。"]', '诗', 'shi', '', NULL, '詠門下畫小松上元王杜三相公 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7dd27c6-0626-42da-a842-380334fadf9a', '寄上禮部李侍郎', '寄上禮部李侍郎', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["吳楚相逢處，江湖共泛時。","任風舟去遠，待月酒行遲。","白髮常同歡，青雲本要期。","貴來君却少，秋至老偏悲。","玉佩明朝盛，蒼苔陋巷滋。","追尋恨無路，唯有夢相思。"]', '["吳楚相逢处，江湖共泛时。","任风舟去远，待月酒行遲。","白髮常同歡，青云本要期。","貴来君却少，秋至老偏悲。","玉佩明朝盛，蒼苔陋巷滋。","追尋恨無路，唯有梦相思。"]', '诗', 'shi', '', NULL, '寄上禮部李侍郎 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02c4f932-2c5d-49a4-b9bb-962315ef1ac2', '書情寄上蘇州韋使君兼呈吳縣李明府', '书情寄上蘇州韋使君兼呈吳縣李明府', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["數年湖上謝浮名，竹杖紗巾遂性情。","雲外有時逢寺宿，日西無事傍江行。","陶潛縣裏看花發，庾亮樓中對月明。","誰念獻書來萬里，君王深在九重城。"]', '["數年湖上謝浮名，竹杖紗巾遂性情。","云外有时逢寺宿，日西無事傍江行。","陶潛縣裏看花發，庾亮楼中对月明。","誰念獻书来万里，君王深在九重城。"]', '诗', 'shi', '', NULL, '書情寄上蘇州韋使君兼呈吳縣李明府 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63038f1b-c864-496c-813c-11c021deb618', '題桐廬李明府官舍', '題桐廬李明府官舍', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["訟堂寂寂對煙霞，五柳門前聚曉鵶。","流水聲中視公事，寒山影裏見人家。","觀風競美新爲政，計日還知舊觸邪。","可惜陶潛無限酒，不逢籬菊正開花。"]', '["訟堂寂寂对煙霞，五柳门前聚晓鵶。","流水声中視公事，寒山影裏见人家。","观风競美新爲政，計日還知旧觸邪。","可惜陶潛無限酒，不逢籬菊正开花。"]', '诗', 'shi', '', NULL, '題桐廬李明府官舍 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b311196f-b1ae-4df5-8ee5-7e1af438478a', '贈竇十九', '贈竇十九', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["靈臺暮宿意多違，木落花開羨客歸。","江海幾時傳錦字，風塵不覺化緇衣。","山陽會裏同人少，灞曲農時故老稀。","幸得漢皇容直諫，憐君未遇覺人非。"]', '["靈台暮宿意多違，木落花开羨客归。","江海幾时傳錦字，风塵不覺化緇衣。","山陽會裏同人少，灞曲農时故老稀。","幸得漢皇容直諫，怜君未遇覺人非。"]', '诗', 'shi', '', NULL, '贈竇十九 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('752f0d5f-d851-437c-8be9-8d6ace092e57', '虔州見鄭表新詩因以寄贈', '虔州见鄭表新诗因以寄贈', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["梅花嶺裏見新詩，感激情深過楚詞。","平子四愁今莫比，休文八詠自同時。","萍鄉露冕真堪惜，鳳沼鳴珂已訝遲。","才子風流定難見，湖南春草但相思。"]', '["梅花嶺裏见新诗，感激情深過楚词。","平子四愁今莫比，休文八詠自同时。","萍乡露冕真堪惜，鳳沼鳴珂已訝遲。","才子风流定难见，湖南春草但相思。"]', '诗', 'shi', '', NULL, '虔州見鄭表新詩因以寄贈 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dabb5b5f-fe33-4632-93ce-e32f638296b1', '贈元秘書', '贈元秘书', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["舊書稍稍出風塵，孤客逢秋感此身。","秦地謬爲門下客，淮陰徒笑市中人。","也聞阮籍尋常醉，見說陳平不久貧。","幸有故人茅屋在，更將心事問情親。"]', '["旧书稍稍出风塵，孤客逢秋感此身。","秦地謬爲门下客，淮陰徒笑市中人。","也闻阮籍尋常醉，见说陳平不久貧。","幸有故人茅屋在，更將心事问情親。"]', '诗', 'shi', '', NULL, '贈元秘書 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7066599-38bd-4570-b61a-ac733327440f', '送韋八少府判官歸東京', '送韋八少府判官归东京', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["玄成世業紫真官，文似相如貌勝潘。","鴻鴈南飛人獨去，雲山一別歲將闌。","清淮水急桑林晚，古驛霜多柿葉寒。","瓊樹相思何日見，銀鉤數字莫爲難。"]', '["玄成世業紫真官，文似相如貌勝潘。","鴻鴈南飞人独去，云山一別歲將闌。","清淮水急桑林晚，古驛霜多柿葉寒。","瓊樹相思何日见，銀鉤數字莫爲难。"]', '诗', 'shi', '', NULL, '送韋八少府判官歸東京 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dec5ea9f-2718-41d2-8159-634c502b0764', '送馮八將軍奏事畢歸滑臺幕府', '送馮八將軍奏事畢归滑台幕府', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["王門別後到滄洲，帝里相逢俱白頭。","自歡馬卿常帶疾，還嗟李廣不封侯。","棠梨宮裏瞻龍衮，細柳營中著虎裘。","想到滑臺桑葉落，黃河東注杏園秋。"]', '["王门別後到滄洲，帝里相逢俱白头。","自歡马卿常带疾，還嗟李廣不封侯。","棠梨宮裏瞻龙衮，細柳營中著虎裘。","想到滑台桑葉落，黄河东注杏园秋。"]', '诗', 'shi', '', NULL, '送馮八將軍奏事畢歸滑臺幕府 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65bfae3b-2f83-4256-b0e3-a52e6855b6d6', '送王侍御佐婺州', '送王侍御佐婺州', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["聞君作尉向江潭，吳越風煙到自諳。","客路尋常經竹徑，人家大底傍山嵐。","緣溪花木偏宜遠，避地衣冠盡向南。","惟有夜猨啼海樹，思鄉望北意難堪。"]', '["闻君作尉向江潭，吳越风煙到自諳。","客路尋常經竹徑，人家大底傍山嵐。","緣溪花木偏宜远，避地衣冠尽向南。","惟有夜猨啼海樹，思乡望北意难堪。"]', '诗', 'shi', '', NULL, '送王侍御佐婺州 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1945ec6b-ad53-4e03-8cd8-24f84d51add5', '越中送王使君赴江華', '越中送王使君赴江华', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["皂蓋春風自越溪，獨尋芳樹桂陽西。","遠水浮雲隨馬去，空山弱篠向雲低。","遙知異政荆門北，舊許新詩康樂齊。","萬里相思在何處，九疑殘雪白猿啼。"]', '["皂蓋春风自越溪，独尋芳樹桂陽西。","远水浮云隨马去，空山弱篠向云低。","遙知異政荆门北，旧許新诗康乐齊。","万里相思在何处，九疑殘雪白猿啼。"]', '诗', 'shi', '', NULL, '越中送王使君赴江華 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bdcf9e3-cb35-46e5-ab96-ad215e02f331', '送皇甫冉往白田', '送皇甫冉往白田', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["江邊盡日雉鳴飛，君向白田何日歸。","楚地蒹葭連海逈，隋朝楊柳映堤稀。","津樓故市無行客，山館空庭閉落暉。","試問疲人與征戰，使君雙淚定沾衣。"]', '["江邊尽日雉鳴飞，君向白田何日归。","楚地蒹葭連海逈，隋朝楊柳映堤稀。","津楼故市無行客，山館空庭閉落暉。","試问疲人與征戰，使君雙泪定沾衣。"]', '诗', 'shi', '', NULL, '送皇甫冉往白田 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('445a7886-88f4-443b-9eca-5959e8d7d5de', '題蘭若', '題蘭若', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["絕頂茅庵老此生，寒雲孤木獨經行。","世人那得知幽逕，遙向青峰禮磬聲。"]', '["絕頂茅庵老此生，寒云孤木独經行。","世人那得知幽逕，遙向青峰禮磬声。"]', '诗', 'shi', '', NULL, '題蘭若 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('620a3bee-0216-4573-a96d-7bd67bcc1c21', '送賀蘭廣赴選', '送賀蘭廣赴選', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["而今用武爾攻文，流輩干時獨臥雲。","白髮青袍趨會府，定應衡鏡却慙君。"]', '["而今用武爾攻文，流輩干时独臥云。","白髮青袍趨會府，定應衡镜却慙君。"]', '诗', 'shi', '', NULL, '送賀蘭廣赴選 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd4458fa-8053-4817-a7e1-9d9b5fddd2fe', '清江曲內一絕', '清江曲內一絕', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["八月長江去浪平，片帆一道帶風輕。","極目不分天水色，南山南是岳陽城。"]', '["八月长江去浪平，片帆一道带风轻。","極目不分天水色，南山南是岳陽城。"]', '诗', 'shi', '', NULL, '清江曲內一絕 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31c7702e-8d2a-4a2f-a7cc-2e07c7498f05', '武康郭外望許緯先生山居', '武康郭外望許緯先生山居', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["湖上千峰帶落暉，白雲開處見柴扉。","松門一逕仍生草，應是仙人向郭稀。"]', '["湖上千峰带落暉，白云开处见柴扉。","松门一逕仍生草，應是仙人向郭稀。"]', '诗', 'shi', '', NULL, '武康郭外望許緯先生山居 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b96b4bed-3730-4d2f-819a-b5a472a1107c', '送司空曙之蘇州', '送司空曙之蘇州', 'a78b0949-fd21-461b-9c9a-f9af0f3e35b6', '唐', '["盤門吳舊地，蟬盡草秋時。","歸國人皆久，移家君獨遲。","廣陵經水宿，建鄴有僧期。","若到西霞寺，應看江總碑。"]', '["盤门吳旧地，蟬尽草秋时。","归国人皆久，移家君独遲。","廣陵經水宿，建鄴有僧期。","若到西霞寺，應看江總碑。"]', '诗', 'shi', '', NULL, '送司空曙之蘇州 苗發 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5a61d84-8246-462a-beae-fea8dbc3c0df', '送孫德諭罷官往黔州', '送孫德諭罷官往黔州', 'a78b0949-fd21-461b-9c9a-f9af0f3e35b6', '唐', '["中歲分符典石城，兩朝趨陛謁承明。","闕下昨承歸老疏，天南今切去鄉情。","親知握手三秋別，几杖扶身萬里行。","伯道暮年無嗣子，欲將家事託門生。"]', '["中歲分符典石城，兩朝趨陛謁承明。","闕下昨承归老疏，天南今切去乡情。","親知握手三秋別，几杖扶身万里行。","伯道暮年無嗣子，欲將家事託门生。"]', '诗', 'shi', '', NULL, '送孫德諭罷官往黔州 苗發 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('794b90fc-bcbe-41ac-945a-912255c2189a', '送歸中丞使新羅冊立弔祭', '送归中丞使新羅冊立弔祭', '146a4bbe-f3e3-4236-9b3f-473d28577906', '唐', '["官稱漢獨坐，身是魯諸生。","絕域通王制，窮天向水程。","島中分萬象，日處轉雙旌。","氣積魚龍窟，濤翻水浪聲。","路長經歲去，海盡向山行。","復道殊方禮，人瞻漢使榮。"]', '["官稱漢独坐，身是魯諸生。","絕域通王制，窮天向水程。","島中分万象，日处轉雙旌。","氣積鱼龙窟，濤翻水浪声。","路长經歲去，海尽向山行。","复道殊方禮，人瞻漢使榮。"]', '诗', 'shi', '', NULL, '送歸中丞使新羅冊立弔祭 吉中孚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cff990b-3924-447a-bebd-71e49aa9fd89', '詠被中繡鞵', '詠被中繡鞵', '4f36145c-8a3d-4a11-8d89-9997bccec194', '唐', '["雲裏蟾鉤落鳳窩，玉郎沈醉也摩挲。","陳王當日風流減，只向波間見襪羅。"]', '["云裏蟾鉤落鳳窩，玉郎沈醉也摩挲。","陳王當日风流減，只向波间见襪羅。"]', '诗', 'shi', '', NULL, '詠被中繡鞵 夏侯審 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f972a01-6d28-4693-aa79-68840f6fc049', '行路難', '行路难', 'b7220886-f068-4069-af11-5d182395c081', '唐', '["行客滿長路，路長良足哀。","白日持角弓，射人而取財。","千金誰家子，紛紛死黃埃。","見者不敢言，言者不得回。","家人各望歸，豈知長不來。"]', '["行客满长路，路长良足哀。","白日持角弓，射人而取財。","千金誰家子，紛紛死黄埃。","见者不敢言，言者不得回。","家人各望归，豈知长不来。"]', '诗', 'shi', '', NULL, '行路難 王烈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('887ebd54-4d78-41de-8082-a636a184fc0a', '雪', '雪', 'b7220886-f068-4069-af11-5d182395c081', '唐', '["雪飛當夢蝶，風度幾驚人。","半夜一窗曉，平明千樹春。","花園應失路，白屋忽爲鄰。","散入仙廚裏，還如雲母塵。"]', '["雪飞當梦蝶，风度幾驚人。","半夜一窗晓，平明千樹春。","花园應失路，白屋忽爲鄰。","散入仙廚裏，還如云母塵。"]', '诗', 'shi', '', NULL, '雪 王烈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cf00a29-37e1-48fc-8277-fc915eda0495', '酬崔峝', '酬崔峝', 'b7220886-f068-4069-af11-5d182395c081', '唐', '["狥世甘長往，逢時忝一官。","欲朝青瑣去，羞向白雲看。","榮寵無心易，艱危抗節難。","思君寫懷抱，非敢和幽蘭。"]', '["狥世甘长往，逢时忝一官。","欲朝青瑣去，羞向白云看。","榮寵無心易，艱危抗節难。","思君寫懷抱，非敢和幽蘭。"]', '诗', 'shi', '', NULL, '酬崔峝 王烈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23a06f51-e1f9-44af-9fdd-35e3c6ed92ca', '塞上曲二首 一', '塞上曲二首 一', 'b7220886-f068-4069-af11-5d182395c081', '唐', '["紅顏歲歲老金微，砂磧年年臥鐵衣。","白草城中春不入，黃花戍上鴈長飛。"]', '["紅顏歲歲老金微，砂磧年年臥鐵衣。","白草城中春不入，黄花戍上鴈长飞。"]', '诗', 'shi', '', NULL, '塞上曲二首 一 王烈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d2e9575-91b2-4e8c-9b4b-eaaf27df10dd', '塞上曲二首 二', '塞上曲二首 二', 'b7220886-f068-4069-af11-5d182395c081', '唐', '["孤城夕對戍樓閑，迴合青冥萬仞山。","明鏡不須生白髮，風沙自解老紅顏。"]', '["孤城夕对戍楼闲，迴合青冥万仞山。","明镜不須生白髮，风沙自解老紅顏。"]', '诗', 'shi', '', NULL, '塞上曲二首 二 王烈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a10b41f-45f7-42fe-9728-30d1e9418660', '傷李端', '傷李端', '4c381977-be01-44f9-ab94-9fb67e76f2f7', '唐', '["才子浮生促，泉臺此路賒。","官卑揚執戟，年少賈長沙。","人去門栖鵩，災成酒誤虵。","唯餘封禪草，留在茂陵家。"]', '["才子浮生促，泉台此路賒。","官卑揚執戟，年少賈长沙。","人去门栖鵩，災成酒誤虵。","唯餘封禪草，留在茂陵家。"]', '诗', 'shi', '', NULL, '傷李端 衞象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4dbe585-74e3-44ed-a767-4692b9e9c39c', '古詞', '古词', '4c381977-be01-44f9-ab94-9fb67e76f2f7', '唐', '["鵲血琱弓濕未乾，鸊鵜新淬劒光寒。","遼東老將鬢成雪，猶向旄頭夜夜看。"]', '["鵲血琱弓濕未乾，鸊鵜新淬劒光寒。","遼东老將鬢成雪，猶向旄头夜夜看。"]', '诗', 'shi', '', NULL, '古詞 衞象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6c01e2e-acb8-46ec-8e77-ceacd788b9f7', '晴江秋望', '晴江秋望', '15834310-8013-41f2-b662-f1d099b92630', '唐', '["八月長江萬里晴，千帆一道帶風輕。","盡日不分天水色，洞庭南是岳陽城。"]', '["八月长江万里晴，千帆一道带风轻。","尽日不分天水色，洞庭南是岳陽城。"]', '诗', 'shi', '', NULL, '晴江秋望 崔季卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d22f1a49-5ef6-4df6-b365-f9ba2fe2442c', '贈兄', '贈兄', 'f3e18d42-3030-4490-93e3-d22d6a074e5a', '唐', '["洛陽紙價因兄貴，蜀地紅牋爲弟貧。","南北東西九千里，除兄與弟更無人。"]', '["洛陽紙價因兄貴，蜀地紅牋爲弟貧。","南北东西九千里，除兄與弟更無人。"]', '诗', 'shi', '', NULL, '贈兄 何兆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db497d72-aefd-4639-88d1-dc93999b1de4', '玉蘂花', '玉蘂花', 'f3e18d42-3030-4490-93e3-d22d6a074e5a', '唐', '["羽車潛下玉龜山，塵世何緣覩蕣顏。","惟有多情天上雪，好風吹上綠雲鬟。"]', '["羽车潛下玉龟山，塵世何緣覩蕣顏。","惟有多情天上雪，好风吹上綠云鬟。"]', '诗', 'shi', '', NULL, '玉蘂花 何兆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8cb3dc3-f809-4681-907c-49afb54f3015', '句', '句', 'f3e18d42-3030-4490-93e3-d22d6a074e5a', '唐', '["芙蓉十二池心漏，薝蔔三千灌頂香。"]', '["芙蓉十二池心漏，薝蔔三千灌頂香。"]', '诗', 'shi', '', NULL, '句 何兆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2c6ea87-8f59-4fdf-aa86-232255783cb9', '嚴陵灘下寄常建', '嚴陵灘下寄常建', '1e955e7e-6916-4f43-b49b-9de28ba51cb7', '唐', '["日入溪水靜，尋真此亦難。","乃知滄洲人，道成仍釣竿。","漾檝乘微月，振衣生早寒。","紛吾成獨往，自速耽考槃。","已息漢陰誚，且同濠上觀。","曠然心無涯，誰問容膝安。"]', '["日入溪水静，尋真此亦难。","乃知滄洲人，道成仍釣竿。","漾檝乘微月，振衣生早寒。","紛吾成独往，自速耽考槃。","已息漢陰誚，且同濠上观。","曠然心無涯，誰问容膝安。"]', '诗', 'shi', '', NULL, '嚴陵灘下寄常建 奚賈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac8e5604-8985-4de3-bc4a-2904364dcfe9', '謁李尊師', '謁李尊師', '1e955e7e-6916-4f43-b49b-9de28ba51cb7', '唐', '["萬物返常性，惟道貴自然。","先生容其微，隱几爲列仙。","鍊魄閉瓊戶，養毛飛洞天。","將知逍遙久，得道無歲年。"]', '["万物返常性，惟道貴自然。","先生容其微，隐几爲列仙。","鍊魄閉瓊戶，養毛飞洞天。","將知逍遙久，得道無歲年。"]', '诗', 'shi', '', NULL, '謁李尊師 奚賈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edc6142f-c234-48ed-8e65-4c9bef714834', '尋許山人亭子', '尋許山人亭子', '1e955e7e-6916-4f43-b49b-9de28ba51cb7', '唐', '["桃源若遠近，漁子櫂輕舟。","川路行難盡，人家到漸幽。","山禽拂席起，溪水入庭流。","君是何年隱，如今成白頭。"]', '["桃源若远近，漁子櫂轻舟。","川路行难尽，人家到漸幽。","山禽拂席起，溪水入庭流。","君是何年隐，如今成白头。"]', '诗', 'shi', '', NULL, '尋許山人亭子 奚賈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20bb2033-bc83-4b7c-be92-bb3066b03aa7', '句', '句', '1e955e7e-6916-4f43-b49b-9de28ba51cb7', '唐', '["眠澗花自落，步林鳥不飛。","谿谷何蕭條，日入人獨行。","落日下平楚，孤煙生洞庭。"]', '["眠澗花自落，步林鸟不飞。","谿谷何蕭條，日入人独行。","落日下平楚，孤煙生洞庭。"]', '诗', 'shi', '', NULL, '句 奚賈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ba0acd3-935e-4e2a-bd8c-d9d62532758f', '富陽南樓望浙江風起', '富陽南楼望浙江风起', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["南樓渚風起，樹杪見滄波。","稍覺征帆上，蕭蕭暮雨多。","沙洲殊未極，雲水更相和。","欲問任公子，垂綸意若何。"]', '["南楼渚风起，樹杪见滄波。","稍覺征帆上，蕭蕭暮雨多。","沙洲殊未極，云水更相和。","欲问任公子，垂綸意若何。"]', '诗', 'shi', '', NULL, '富陽南樓望浙江風起 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('921c64b8-bb7b-48dc-9f1f-799076ee6349', '奉酬李舍人秋日寓直見寄', '奉酬李舍人秋日寓直见寄', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["秋日金華直，遙知玉佩清。","九重門更肅，五色詔初成。","槐落宮中影，鴻高苑外聲。","飜從魏闕下，江海寄幽情。"]', '["秋日金华直，遙知玉佩清。","九重门更肅，五色詔初成。","槐落宮中影，鴻高苑外声。","飜從魏闕下，江海寄幽情。"]', '诗', 'shi', '', NULL, '奉酬李舍人秋日寓直見寄 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fa1dc58-6378-4da2-9b04-640aa565ab05', '同韓侍郎秋朝使院', '同韓侍郎秋朝使院', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["重門啓曙關，一葉報秋還。","露井桐柯濕，風庭鶴翅閒。","忘情簪白筆，假夢入青山。","惆悵祗應此，難裁語默間。"]', '["重门啓曙关，一葉報秋還。","露井桐柯濕，风庭鹤翅閒。","忘情簪白笔，假梦入青山。","惆悵祗應此，难裁語默间。"]', '诗', 'shi', '', NULL, '同韓侍郎秋朝使院 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5f86b06-3568-4bf7-95ac-7ca3e383b074', '送朱大遊塞', '送朱大游塞', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["歲暮一爲別，江湖聊自寬。","且無人事處，誰謂客行難。","郢曲憐公子，吳州憶伯鸞。","蒼蒼遠山際，松柏獨宜寒。"]', '["歲暮一爲別，江湖聊自寬。","且無人事处，誰謂客行难。","郢曲怜公子，吳州憶伯鸾。","蒼蒼远山際，松柏独宜寒。"]', '诗', 'shi', '', NULL, '送朱大遊塞 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe45ab35-fb40-4650-bc87-ccd12776c478', '送鄭錄事赴太原', '送鄭錄事赴太原', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["歎息不相見，紅顏今白頭。","重爲西候別，方起北風愁。","六月胡天冷，雙城汾水流。","盧諶即故吏，還復向幷州。"]', '["歎息不相见，紅顏今白头。","重爲西候別，方起北风愁。","六月胡天冷，雙城汾水流。","盧諶即故吏，還复向幷州。"]', '诗', 'shi', '', NULL, '送鄭錄事赴太原 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5608e2a-b7e9-4cc4-8b23-cf45036f80d3', '送余贊善使還赴薛尚書幕', '送余贊善使還赴薛尚书幕', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["音書不可論，河塞雪紛紛。","雁足期蘇武，狐裘見薛君。","城池通紫陌，鞍馬入黃雲。","遠棹漳渠水，平流幾處分。"]', '["音书不可論，河塞雪紛紛。","雁足期蘇武，狐裘见薛君。","城池通紫陌，鞍马入黄云。","远棹漳渠水，平流幾处分。"]', '诗', 'shi', '', NULL, '送余贊善使還赴薛尚書幕 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5311d52-89f9-4ab0-a879-234456f23778', '送李侍御入茅山採藥', '送李侍御入茅山採藥', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["苦縣家風在，茅山道錄傳。","聊聽驄馬使，却就紫陽仙。","江海生岐路，雲霞入洞天。","莫令千歲鶴，飛到草堂前。"]', '["苦縣家风在，茅山道錄傳。","聊听驄马使，却就紫陽仙。","江海生岐路，云霞入洞天。","莫令千歲鹤，飞到草堂前。"]', '诗', 'shi', '', NULL, '送李侍御入茅山採藥 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad17b1f6-13c6-4030-9709-a880fae6b672', '寄中書李舍人', '寄中书李舍人', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["昨宵淒斷處，對月與臨風。","鶴病三江上，蘭衰百草中。","題詩隨謝客，飲酒寄黃翁。","早歲心相待，還因貴賤同。"]', '["昨宵淒斷处，对月與臨风。","鹤病三江上，蘭衰百草中。","題诗隨謝客，饮酒寄黄翁。","早歲心相待，還因貴賤同。"]', '诗', 'shi', '', NULL, '寄中書李舍人 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9391ef33-933e-452d-8fc3-5c6ccfe8eb12', '和崔中丞中秋月', '和崔中丞中秋月', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["秋夜月偏明，西樓獨有情。","千家看露濕，萬里覺天清。","映水金波動，銜山桂樹生。","不知飛鵲意，何用此時驚。"]', '["秋夜月偏明，西楼独有情。","千家看露濕，万里覺天清。","映水金波动，銜山桂樹生。","不知飞鵲意，何用此时驚。"]', '诗', 'shi', '', NULL, '和崔中丞中秋月 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('723959fc-7c26-46a6-be23-6532a951edf9', '西陵懷靈一上人兼寄朱放', '西陵懷靈一上人兼寄朱放', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["淮海風濤起，江關憂思長。","同悲鵲遶樹，獨坐雁隨陽。","山晚雲藏雪，汀寒月照霜。","由來濯纓處，漁父愛滄浪。"]', '["淮海风濤起，江关憂思长。","同悲鵲遶樹，独坐雁隨陽。","山晚云藏雪，汀寒月照霜。","由来濯纓处，漁父愛滄浪。"]', '诗', 'shi', '', NULL, '西陵懷靈一上人兼寄朱放 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb63a531-5e8b-4da9-b04b-5351b3bad171', '寄靜虛上人雲門', '寄静虛上人云门', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["寒日白雲裏，法侶自提攜。","竹徑通城下，松門隔水西。","方同沃洲去，不自武陵迷。","髣髴心疑處，高峯是會稽。"]', '["寒日白云裏，法侶自提携。","竹徑通城下，松门隔水西。","方同沃洲去，不自武陵迷。","髣髴心疑处，高峯是會稽。"]', '诗', 'shi', '', NULL, '寄靜虛上人雲門 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('721bea36-8cbd-4787-974d-23b4760c8b6b', '送司空十四北遊宋州', '送司空十四北游宋州', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["九拒危城下，蕭條送爾歸。","寒風吹畫角，暮雪犯征衣。","道里猶成間，親朋重與違。","白雲愁欲斷，看入大梁飛。"]', '["九拒危城下，蕭條送爾归。","寒风吹畫角，暮雪犯征衣。","道里猶成间，親朋重與違。","白云愁欲斷，看入大梁飞。"]', '诗', 'shi', '', NULL, '送司空十四北遊宋州 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9328299-6903-4418-93f1-e4172e7e3320', '殷卿宅夜宴', '殷卿宅夜宴', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["日暗城烏宿，天寒櫪馬嘶。","詞人留上客，妓女出中閨。","積雪連燈照，迴廊映竹迷。","太常今夜宴，誰不醉如泥。"]', '["日暗城烏宿，天寒櫪马嘶。","词人留上客，妓女出中閨。","積雪連灯照，迴廊映竹迷。","太常今夜宴，誰不醉如泥。"]', '诗', 'shi', '', NULL, '殷卿宅夜宴 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2d39297-ba40-40e6-94b9-b09cdffebaae', '宣城雪後還望郡中寄孟侍御', '宣城雪後還望郡中寄孟侍御', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["臘後年華變，關西驛騎遙。","塞鴻連暮雪，江柳動寒條。","山水還鄣郡，圖書入漢朝。","高樓非別處，故使百憂銷。"]', '["臘後年华变，关西驛騎遙。","塞鴻連暮雪，江柳动寒條。","山水還鄣郡，圖书入漢朝。","高楼非別处，故使百憂銷。"]', '诗', 'shi', '', NULL, '宣城雪後還望郡中寄孟侍御 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b7e6f4d-499f-4489-a106-c60a0532087a', '獨孤常州北亭', '独孤常州北亭', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["北洫敞高明，憑軒見野情。","朝回五馬跡，更勝百花名。","海樹凝煙遠，湖田見鶴清。","雲光侵素壁，水影蕩閒楹。","俗賴褰帷謁，人歡倒屣迎。","始能崇結構，獨有謝宣城。"]', '["北洫敞高明，憑軒见野情。","朝回五马跡，更勝百花名。","海樹凝煙远，湖田见鹤清。","云光侵素壁，水影蕩閒楹。","俗賴褰帷謁，人歡倒屣迎。","始能崇結構，独有謝宣城。"]', '诗', 'shi', '', NULL, '獨孤常州北亭 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7038ee94-a84c-4d53-80a9-90430ce36af1', '早春書事奉寄中書李舍人', '早春书事奉寄中书李舍人', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["儒服山東士，衡門洛下居。","風塵遊上路，簡冊委空廬。","戎馬生郊日，賢人避地初。","竄身初浩蕩，投跡豈躊躇。","翠羽憐窮鳥，瓊枝顧散樗。","還令親道術，倒欲混樵漁。","敝緼袍多補，飛蓬鬢少梳。","誦詩陪賈誼，酌酒伴應璩。","鶴膝兵家備，鳧茨儉歲儲。","泊舟依野水，開逕接園蔬。","暫閱新山澤，長懷故里閭。","思賢乘朗月，覽古到荒墟。","在竹慙充箭，爲蘭幸免鋤。","那堪聞相府，更遣詣公車。","蹇足終難進，嚬眉竟未舒。","事從因病止，生寄負恩餘。","不見神仙久，無由鄙恡祛。","帝庭張禮樂，天閣繡簪裾。","日色浮青瑣，香煙近玉除。","神清王子敬，氣逐馬相如。","銅漏時常靜，金門步轉徐。","唯看五字表，不記八行書。","宿昔投知己，周旋謝起予。","祇應高位隔，詎是故情疎。","爲報周多士，須憐楚子虛。","一身從棄置，四節苦居諸。","柳發三條陌，花飛六輔渠。","靈盤浸沆瀣，龍首映儲胥。","北海樽留客，西江水救魚。","長安同日遠，不敢詠歸歟。"]', '["儒服山东士，衡门洛下居。","风塵游上路，簡冊委空廬。","戎马生郊日，賢人避地初。","竄身初浩蕩，投跡豈躊躇。","翠羽怜窮鸟，瓊枝顧散樗。","還令親道術，倒欲混樵漁。","敝緼袍多補，飞蓬鬢少梳。","誦诗陪賈誼，酌酒伴應璩。","鹤膝兵家備，鳧茨儉歲儲。","泊舟依野水，开逕接园蔬。","暫閱新山澤，长懷故里閭。","思賢乘朗月，覽古到荒墟。","在竹慙充箭，爲蘭幸免鋤。","那堪闻相府，更遣詣公车。","蹇足終难進，嚬眉竟未舒。","事從因病止，生寄負恩餘。","不见神仙久，無由鄙恡祛。","帝庭張禮乐，天閣繡簪裾。","日色浮青瑣，香煙近玉除。","神清王子敬，氣逐马相如。","銅漏时常静，金门步轉徐。","唯看五字表，不記八行书。","宿昔投知己，周旋謝起予。","祇應高位隔，詎是故情疎。","爲報周多士，須怜楚子虛。","一身從棄置，四節苦居諸。","柳發三條陌，花飞六輔渠。","靈盤浸沆瀣，龙首映儲胥。","北海樽留客，西江水救鱼。","长安同日远，不敢詠归歟。"]', '诗', 'shi', '', NULL, '早春書事奉寄中書李舍人 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99e9e559-6f81-4757-9b14-827d6d4aa2de', '陸勝宅秋暮雨中探韻同作', '陸勝宅秋暮雨中探韻同作', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["同人永日自相將，深竹閒園偶辟疆。","已被秋風教憶鱠，更聞寒雨勸飛觴。","歸心莫問三江水，旅服徒沾九日霜。","醉裏欲尋騎馬路，蕭條幾處有垂楊。"]', '["同人永日自相將，深竹閒园偶辟疆。","已被秋风教憶鱠，更闻寒雨勸飞觴。","归心莫问三江水，旅服徒沾九日霜。","醉裏欲尋騎马路，蕭條幾处有垂楊。"]', '诗', 'shi', '', NULL, '陸勝宅秋暮雨中探韻同作 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e01bfd47-271a-4897-85aa-0b6c469e19f9', '春日道中寄孟侍御', '春日道中寄孟侍御', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["春來游子傍歸路，時有白雲遮獨行。","水流亂赴石潭響，花開不知山樹名。","誰家魚網求鮮食，幾處人煙事火耕。","昨日已嘗村酒熟，一杯思與孟嘉傾。"]', '["春来游子傍归路，时有白云遮独行。","水流亂赴石潭响，花开不知山樹名。","誰家鱼網求鲜食，幾处人煙事火耕。","昨日已嘗村酒熟，一杯思與孟嘉傾。"]', '诗', 'shi', '', NULL, '春日道中寄孟侍御 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91ba74c4-82ef-4760-a723-9916b32800bc', '江北春望贈皇甫補闕', '江北春望贈皇甫補闕', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["閒園柳綠井桃紅，野徑荒墟左右通。","清逈獨連江水北，芳菲更似洛城東。","時看雨歇人歸岫，每覺潮來樹起風。","聞道金門堪避世，何須身與海鷗同。"]', '["閒园柳綠井桃紅，野徑荒墟左右通。","清逈独連江水北，芳菲更似洛城东。","时看雨歇人归岫，每覺潮来樹起风。","闻道金门堪避世，何須身與海鷗同。"]', '诗', 'shi', '', NULL, '江北春望贈皇甫補闕 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('986ee647-9f82-44bf-908e-9d31e70e29bc', '酬張二倉曹楊子閒居見寄兼呈韓郎中左補闕皇甫冉', '酬張二倉曹楊子閒居见寄兼呈韓郎中左補闕皇甫冉', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["孤雲獨鶴自悠悠，別後經年尚泊舟。","漁父致詞相借問，仙郎能賦許依投。","折芳遠計三春草，乘興閒看萬里流。","莫怪杜門頻乞假，不堪扶病拜龍樓。"]', '["孤云独鹤自悠悠，別後經年尚泊舟。","漁父致词相借问，仙郎能賦許依投。","折芳远計三春草，乘兴閒看万里流。","莫怪杜门頻乞假，不堪扶病拜龙楼。"]', '诗', 'shi', '', NULL, '酬張二倉曹楊子閒居見寄兼呈韓郎中左補闕皇甫冉 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3900a71-2d1e-4099-81d9-2f4e099b0940', '秋夜聞鴈寄南十五兼呈空和尚', '秋夜闻鴈寄南十五兼呈空和尚', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["晚節聞君道趣深，結茅栽樹近東林。","禪師幾度曾摩頂，高士何年更發心。","北渚三更聞過鴈，西城萬木動寒砧。","不見支公與玄度，相思擁膝坐長吟。"]', '["晚節闻君道趣深，結茅栽樹近东林。","禪師幾度曾摩頂，高士何年更發心。","北渚三更闻過鴈，西城万木动寒砧。","不见支公與玄度，相思擁膝坐长吟。"]', '诗', 'shi', '', NULL, '秋夜聞鴈寄南十五兼呈空和尚 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('712df10d-a110-4c39-8d92-d93874a499fc', '雪', '雪', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["雪，雪。","花片，玉屑。","結陰風，凝暮節。","高嶺虛晶，平原廣潔。","初從雲外飄，還向空中噎。","千門萬戶皆靜，獸炭皮裘自熱。","此時雙舞洛陽人，誰悟郢中歌斷絕。"]', '["雪，雪。","花片，玉屑。","結陰风，凝暮節。","高嶺虛晶，平原廣潔。","初從云外飄，還向空中噎。","千门万戶皆静，獸炭皮裘自熱。","此时雙舞洛陽人，誰悟郢中歌斷絕。"]', '诗', 'shi', '', NULL, '雪 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45e3e037-699c-41df-a14f-9c2835334fcc', '月', '月', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["月，月。","暫盈，還缺。","上虛空，生溟渤。","散彩無際，移輪不歇。","桂殿入西秦，菱歌映南越。","正看雲霧秋卷，莫待關山曉沒。","天涯地角不可尋，清光永夜何超忽。"]', '["月，月。","暫盈，還缺。","上虛空，生溟渤。","散彩無際，移輪不歇。","桂殿入西秦，菱歌映南越。","正看云霧秋卷，莫待关山晓沒。","天涯地角不可尋，清光永夜何超忽。"]', '诗', 'shi', '', NULL, '月 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3754072-4bb7-47ba-9ea4-5a5d4d8e4949', '泉', '泉', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["泉，泉。","色淨，苔鮮。","石上激，雲中懸。","津流竹樹，脉亂山川。","扣玉千聲應，含風百道連。","太液倂歸池上，雲陽舊出宮邊。","北陵井深鑿不到，我欲添淚作潺湲。"]', '["泉，泉。","色淨，苔鲜。","石上激，云中懸。","津流竹樹，脉亂山川。","扣玉千声應，含风百道連。","太液倂归池上，云陽旧出宮邊。","北陵井深鑿不到，我欲添泪作潺湲。"]', '诗', 'shi', '', NULL, '泉 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88ec78ff-b1f5-4176-aa01-60bd10186362', '竹', '竹', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["竹，竹。","披山，連谷。","出東南，殊草木。","葉細枝動，霜停露宿。","成林處處雲，抽笋年年玉。","天風乍起爭韻，池水相涵更綠。","却尋庾信小園中，閒對數竿心自足。"]', '["竹，竹。","披山，連谷。","出东南，殊草木。","葉細枝动，霜停露宿。","成林处处云，抽笋年年玉。","天风乍起爭韻，池水相涵更綠。","却尋庾信小园中，閒对數竿心自足。"]', '诗', 'shi', '', NULL, '竹 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3584c703-97e7-45ca-92df-a8decb1b31b5', '花', '花', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["花，花。","深淺，芬葩。","凝爲雪，錯爲霞。","鶯和蝶到，苑占宮遮。","已迷金谷路，頻駐玉人車。","芳草欲陵芳樹，東家半落西家。","願得春風相伴去，一攀一折向天涯。"]', '["花，花。","深淺，芬葩。","凝爲雪，錯爲霞。","鶯和蝶到，苑占宮遮。","已迷金谷路，頻駐玉人车。","芳草欲陵芳樹，东家半落西家。","願得春风相伴去，一攀一折向天涯。"]', '诗', 'shi', '', NULL, '花 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd638a99-949f-4db8-9655-ba974f9d0de1', '草', '草', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["草，草。","折宜，看好。","滿地生，催人老。","金殿玉砌，荒城古道。","青青千里遙，悵悵三春早。","每逢南北離別，乍逐東西傾倒。","一身本是山中人，聊與王孫慰懷抱。"]', '["草，草。","折宜，看好。","满地生，催人老。","金殿玉砌，荒城古道。","青青千里遙，悵悵三春早。","每逢南北離別，乍逐东西傾倒。","一身本是山中人，聊與王孫慰懷抱。"]', '诗', 'shi', '', NULL, '草 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55ff7275-ebbb-4a1f-ba4e-30a9f4937113', '送人', '送人', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["白日向西沒，黃河復東流。","人生足著地，寧免四方遊。","我行無返顧，祝子勿回頭。","當須向前去，何用起離憂。","但恐無廣路，平地作山丘。","令我車與馬，欲疾反停留。","蜀客多積貨，邊人易封侯。","男兒戀家鄉，歡樂爲仇讐。","丁寧相勸勉，苦口幸無尤。","對面無相成，不如豺虎儔。","彼遠不寄書，此寒莫寄裘。","與君俱絕跡，兩念無因由。"]', '["白日向西沒，黄河复东流。","人生足著地，寧免四方游。","我行無返顧，祝子勿回头。","當須向前去，何用起離憂。","但恐無廣路，平地作山丘。","令我车與马，欲疾反停留。","蜀客多積貨，邊人易封侯。","男兒戀家乡，歡乐爲仇讐。","丁寧相勸勉，苦口幸無尤。","对面無相成，不如豺虎儔。","彼远不寄书，此寒莫寄裘。","與君俱絕跡，兩念無因由。"]', '诗', 'shi', '', NULL, '送人 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc77a4a0-3e5c-456f-8bf2-739e4ec6e477', '主人故亭', '主人故亭', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["主人昔專城，城南起高亭。","貴與賓客遊，工者夜不寧。","酒食宴圃人，栽接望早成。","經年使家僮，遠道求異英。","郡中暫閑暇，遶樹引諸生。","開泉浴山禽，爲愛山中聲。","世間事難保，一日各徂征。","死生不相及，花落實方榮。","我來至此中，守吏非本名。","重君昔爲主，相與下馬行。","舊島日日摧，池水不復清。","豈無後人賞，所貴手自營。","澆酒向所思，風起如有靈。","此去不重來，重來傷我形。"]', '["主人昔專城，城南起高亭。","貴與賓客游，工者夜不寧。","酒食宴圃人，栽接望早成。","經年使家僮，远道求異英。","郡中暫闲暇，遶樹引諸生。","开泉浴山禽，爲愛山中声。","世间事难保，一日各徂征。","死生不相及，花落實方榮。","我来至此中，守吏非本名。","重君昔爲主，相與下马行。","旧島日日摧，池水不复清。","豈無後人賞，所貴手自營。","澆酒向所思，风起如有靈。","此去不重来，重来傷我形。"]', '诗', 'shi', '', NULL, '主人故亭 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f447572-d25c-4898-a1c0-0f2f1a8194e8', '古從軍', '古從軍', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["漢家逐單于，日沒處河曲。","浮雲道旁起，行子車下宿。","槍城圍鼓角，氈帳依山谷。","馬上懸壺漿，刀頭分頰肉。","來時高堂上，父母親結束。","回面不見家，風吹破衣服。","金瘡在肢節，相與拔箭鏃。","聞道西涼州，家家婦女哭。"]', '["漢家逐單于，日沒处河曲。","浮云道旁起，行子车下宿。","槍城圍鼓角，氈帳依山谷。","马上懸壺漿，刀头分頰肉。","来时高堂上，父母親結束。","回面不见家，风吹破衣服。","金瘡在肢節，相與拔箭鏃。","闻道西涼州，家家婦女哭。"]', '诗', 'shi', '', NULL, '古從軍 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f60d0421-7813-4060-9dbe-fb59533a778b', '邯鄲主人', '邯鄲主人', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["遠客無主人，夜投邯鄲市。","飛蛾繞殘燭，半夜人醉起。","壚邊酒家女，遺我緗綺被。","合成雙鳳花，宛轉不相離。","縱令顏色改，勿遣合歡異。","一念始爲難，萬金誰足貴。","門前長安道，去者如流水。","晨風羣鳥翔，裴回別離此。"]', '["远客無主人，夜投邯鄲市。","飞蛾繞殘燭，半夜人醉起。","壚邊酒家女，遺我緗綺被。","合成雙鳳花，宛轉不相離。","縱令顏色改，勿遣合歡異。","一念始爲难，万金誰足貴。","门前长安道，去者如流水。","晨风羣鸟翔，裴回別離此。"]', '诗', 'shi', '', NULL, '邯鄲主人 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1876a213-663e-4780-ae52-068af79122c3', '泛水曲', '泛水曲', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["載酒入煙浦，方舟泛綠波。","子酌我復飲，子飲我還歌。","蓮深微路通，峰曲幽氣多。","閱芳無留瞬，弄桂不停柯。","水上秋日鮮，西山碧峩峩。","茲歡良可貴，誰復更來過。"]', '["載酒入煙浦，方舟泛綠波。","子酌我复饮，子饮我還歌。","蓮深微路通，峰曲幽氣多。","閱芳無留瞬，弄桂不停柯。","水上秋日鲜，西山碧峩峩。","茲歡良可貴，誰复更来過。"]', '诗', 'shi', '', NULL, '泛水曲 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b41259ac-cee7-406a-9ee7-089d0ea337e2', '江南雜體二首 一', '江南杂體二首 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["江上風翛翛，竹間湘水流。","日夜桂花落，行人去悠悠。","復見離別處，蟲聲陰雨秋。"]', '["江上风翛翛，竹间湘水流。","日夜桂花落，行人去悠悠。","复见離別处，蟲声陰雨秋。"]', '诗', 'shi', '', NULL, '江南雜體二首 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('519df5eb-79c7-4f25-87bc-e51522aaa186', '江南雜體二首 二', '江南杂體二首 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["處處江草綠，行人發瀟湘。","瀟湘回雁多，日夜思故鄉。","春夢不知數，空山蘭蕙芳。"]', '["处处江草綠，行人發瀟湘。","瀟湘回雁多，日夜思故乡。","春梦不知數，空山蘭蕙芳。"]', '诗', 'shi', '', NULL, '江南雜體二首 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36c4627f-ef62-4ee3-8652-4d6399bd5512', '遠征歸', '远征归', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["萬里發遼陽，處處問家鄉。","回車不淹轍，雨雪滿衣裳。","行見日月疾，坐思道路長。","但令不征戍，暗鏡生重光。"]', '["万里發遼陽，处处问家乡。","回车不淹轍，雨雪满衣裳。","行见日月疾，坐思道路长。","但令不征戍，暗镜生重光。"]', '诗', 'shi', '', NULL, '遠征歸 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fed7bba3-9372-4ffb-bce2-5733cb757be5', '思遠人', '思远人', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["妾思常懸懸，君行復綿綿。","征途向何處，碧海與青天。","歲久自有念，誰令長在邊。","少年若不歸，蘭室如黃泉。"]', '["妾思常懸懸，君行复綿綿。","征途向何处，碧海與青天。","歲久自有念，誰令长在邊。","少年若不归，蘭室如黄泉。"]', '诗', 'shi', '', NULL, '思遠人 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d6c9fbb-dd8b-4272-9419-b821f5099672', '傷近者不見', '傷近者不见', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["離人隔中庭，幸不爲遠征。","雕梁下有壁，聞語亦聞行。","天涯尚寄信，此處不傳情。","君能並照水，形影自分明。"]', '["離人隔中庭，幸不爲远征。","雕梁下有壁，闻語亦闻行。","天涯尚寄信，此处不傳情。","君能並照水，形影自分明。"]', '诗', 'shi', '', NULL, '傷近者不見 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9efd292-5e45-487a-b4ad-fec81366b5c3', '元日早朝', '元日早朝', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["大國禮樂備，萬邦朝元正。","東方色未動，冠劒門已盈。","帝居在蓬萊，肅肅鐘漏清。","將軍領羽林，持戟巡宮城。","翠華皆宿陳，雪仗羅天兵。","庭燎遠煌煌，旗上日月明。","聖人龍火衣，寢殿開旋扃。","龍樓橫紫煙，宮女天中行。","六蕃倍位次，衣服各異形。","舉頭看玉牌，不識宮殿名。","左右雉扇開，蹈舞分滿庭。","朝服帶金玉，珊珊相觸聲。","泰階備雅樂，九奏鸞鳳鳴。","裴回慶雲中，竽磬寒錚錚。","三公再獻壽，上帝錫永貞。","天明告四方，羣后保太平。"]', '["大国禮乐備，万邦朝元正。","东方色未动，冠劒门已盈。","帝居在蓬萊，肅肅鐘漏清。","將軍領羽林，持戟巡宮城。","翠华皆宿陳，雪仗羅天兵。","庭燎远煌煌，旗上日月明。","聖人龙火衣，寢殿开旋扃。","龙楼橫紫煙，宮女天中行。","六蕃倍位次，衣服各異形。","舉头看玉牌，不識宮殿名。","左右雉扇开，蹈舞分满庭。","朝服带金玉，珊珊相觸声。","泰階備雅乐，九奏鸾鳳鳴。","裴回慶云中，竽磬寒錚錚。","三公再獻壽，上帝錫永貞。","天明告四方，羣后保太平。"]', '诗', 'shi', '', NULL, '元日早朝 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd65fb3f-d418-4cd7-8658-444d19f1327b', '聞故人自征戍回', '闻故人自征戍回', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["昔聞著征戍，三年一還鄉。","今來不換兵，須死在戰場。","念子無氣力，徒學事戎行。","少年得生還，有同墮穹蒼。","自去報爾家，再行上高堂。","爾弟修廢櫪，爾母縫新裳。","恍恍恐不真，猶未苦承望。","每日空出城，畏渴攜壺漿。","安得縮地經，忽使在我傍。","亦知遠行勞，人悴馬玄黃。","慎莫多停留，苦我居者腸。"]', '["昔闻著征戍，三年一還乡。","今来不換兵，須死在戰場。","念子無氣力，徒学事戎行。","少年得生還，有同墮穹蒼。","自去報爾家，再行上高堂。","爾弟修廢櫪，爾母縫新裳。","恍恍恐不真，猶未苦承望。","每日空出城，畏渴携壺漿。","安得縮地經，忽使在我傍。","亦知远行勞，人悴马玄黄。","慎莫多停留，苦我居者腸。"]', '诗', 'shi', '', NULL, '聞故人自征戍回 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('922842c3-c2c1-4c9f-9bc3-83a0580b01d1', '七泉寺上方', '七泉寺上方', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["長年好名山，本性今得從。","回看塵蹟遙，稍見糜鹿蹤。","老僧雲中居，石門青重重。","陰泉養成龜，古壁飛却龍。","掃石禮新經，懸幡上高峰。","日夕猿鳥合，覓食聽山鐘。","將火尋遠泉，煮茶傍寒松。","晚隨收藥人，便宿南澗中。","晨起衝露行，濕花枝茸茸。","歸依向禪師，願作香火翁。"]', '["长年好名山，本性今得從。","回看塵蹟遙，稍见糜鹿蹤。","老僧云中居，石门青重重。","陰泉養成龟，古壁飞却龙。","掃石禮新經，懸幡上高峰。","日夕猿鸟合，覓食听山鐘。","將火尋远泉，煮茶傍寒松。","晚隨收藥人，便宿南澗中。","晨起衝露行，濕花枝茸茸。","归依向禪師，願作香火翁。"]', '诗', 'shi', '', NULL, '七泉寺上方 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44108987-73c2-4661-a258-cab7d617838b', '從元太守夏讌西樓', '從元太守夏讌西楼', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["六月晨亦熱，卑居多煩昏。","五馬遊西城，几杖隨朱輪。","西樓臨方塘，嘉木當華軒。","鳧鷖滿中流，有酒復盈尊。","山東地無山，平視大海垠。","高風涼氣來，灝景沈清源。","青衿儼坐傍，禮容益敦敦。","願爲顏氏徒，歌詠夫子門。"]', '["六月晨亦熱，卑居多煩昏。","五马游西城，几杖隨朱輪。","西楼臨方塘，嘉木當华軒。","鳧鷖满中流，有酒复盈尊。","山东地無山，平視大海垠。","高风涼氣来，灝景沈清源。","青衿儼坐傍，禮容益敦敦。","願爲顏氏徒，歌詠夫子门。"]', '诗', 'shi', '', NULL, '從元太守夏讌西樓 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09d9d2b1-e2a0-499c-a673-bd9f9333a435', '酬栢侍御聞與韋處士同遊靈臺寺見寄', '酬栢侍御闻與韋处士同游靈台寺见寄', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["西域傳中說，靈臺屬雍州。","有泉皆聖蹟，有石皆佛頭。","所出薝蔔香，外國俗來求。","毒蛇護其下，樵者不可偷。","古碑在雲巔，備載置寺由。","魏家移下來，後人始增修。","近與韋處士，愛此山之幽。","各自具所須，竹籠盛茶甌。","牽馬過危棧，襞衣涉奔流。","草開平路盡，林下大石稠。","過郭轉經峰，忽見東西樓。","瀑布當寺門，逬落衣裳秋。","石苔鋪紫花，溪葉裁碧油。","松根載殿高，飄颻仙山浮。","縣中賢大夫，一月前此遊。","賽神賀得雨，豈暇多停留。","二十韻新詩，遠寄尋山儔。","清冷玉澗泣，冷切石磬愁。","君名高難閑，余身愚終休。","相將長無因，從今生離憂。"]', '["西域傳中说，靈台屬雍州。","有泉皆聖蹟，有石皆佛头。","所出薝蔔香，外国俗来求。","毒蛇護其下，樵者不可偷。","古碑在云巔，備載置寺由。","魏家移下来，後人始增修。","近與韋处士，愛此山之幽。","各自具所須，竹籠盛茶甌。","牽马過危棧，襞衣涉奔流。","草开平路尽，林下大石稠。","過郭轉經峰，忽见东西楼。","瀑布當寺门，逬落衣裳秋。","石苔鋪紫花，溪葉裁碧油。","松根載殿高，飄颻仙山浮。","縣中賢大夫，一月前此游。","賽神賀得雨，豈暇多停留。","二十韻新诗，远寄尋山儔。","清冷玉澗泣，冷切石磬愁。","君名高难闲，余身愚終休。","相將长無因，從今生離憂。"]', '诗', 'shi', '', NULL, '酬栢侍御聞與韋處士同遊靈臺寺見寄 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('612f385f-0ae2-411c-a894-e24280d4dbfb', '荆南贈別李肇著作轉韻詩', '荆南贈別李肇著作轉韻诗', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["輝天復耀地，再爲歌詠始。","素傳學道徒，清門有君子。","文澗瀉潺潺，德峰來壘壘。","兩京二十年，投食公卿間。","封章既不下，故舊多慙顏。","賣馬市耕牛，却歸湘浦山。","麥收蠶上簇，衣食應豐足。","碧澗伴僧禪，秋山對雨宿。","且歡身體適，幸免纓組束。","上宰鎮荆州，敬重同歲遊。","歡逢通世友，簡授畫戎籌。","遲遲就公食，愴愴別野裘。","主人開宴席，禮數無形迹。","醉笑或顛吟，發談皆損益。","臨甃理芳鮮，升堂引賓客。","早歲慕嘉名，遠思今始平。","孔門忝同轍，潘館幸諸甥。","自知再婚娶，豈望爲親情。","欣欣還切切，又二千里別。","楚筆防寄書，蜀茶憂遠熱。","關山足重疊，會合何時節。","莫歎各從軍，且愁岐路分。","美人停玉指，離瑟不中聞。","爭向巴山夜，猿聲滿碧雲。"]', '["輝天复耀地，再爲歌詠始。","素傳学道徒，清门有君子。","文澗瀉潺潺，德峰来壘壘。","兩京二十年，投食公卿间。","封章既不下，故旧多慙顏。","賣马市耕牛，却归湘浦山。","麦收蠶上簇，衣食應豐足。","碧澗伴僧禪，秋山对雨宿。","且歡身體適，幸免纓組束。","上宰鎮荆州，敬重同歲游。","歡逢通世友，簡授畫戎籌。","遲遲就公食，愴愴別野裘。","主人开宴席，禮數無形迹。","醉笑或顛吟，發談皆損益。","臨甃理芳鲜，升堂引賓客。","早歲慕嘉名，远思今始平。","孔门忝同轍，潘館幸諸甥。","自知再婚娶，豈望爲親情。","欣欣還切切，又二千里別。","楚笔防寄书，蜀茶憂远熱。","关山足重叠，會合何时節。","莫歎各從軍，且愁岐路分。","美人停玉指，離瑟不中闻。","爭向巴山夜，猿声满碧云。"]', '诗', 'shi', '', NULL, '荆南贈別李肇著作轉韻詩 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ea2fc96-eaad-49f9-8c58-72dee6735599', '早發金堤驛', '早發金堤驛', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["蟲聲四野合，月色滿城白。","家家閉戶眠，行人發孤驛。","離家尚苦熱，衣服唯輕綌。","時節忽復遷，秋風徹經脈。","人睡落塹轍，馬驚入蘆荻。","慰遠時問程，驚昏忽搖策。","從軍豈云樂，憂患常縈積。","唯願在貧家，團圓過朝夕。"]', '["蟲声四野合，月色满城白。","家家閉戶眠，行人發孤驛。","離家尚苦熱，衣服唯轻綌。","时節忽复遷，秋风徹經脈。","人睡落塹轍，马驚入蘆荻。","慰远时问程，驚昏忽搖策。","從軍豈云乐，憂患常縈積。","唯願在貧家，團圓過朝夕。"]', '诗', 'shi', '', NULL, '早發金堤驛 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6782377e-0381-425a-a12e-e8b8ae91c95e', '和裴相公道中贈別張相公', '和裴相公道中贈別張相公', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["雲間雙鳳鳴，一去一歸城。","鞍馬朝天色，封章戀闕情。","日臨宮樹高，煙蓋沙草平。","會當戎事息，聯影遶池行。"]', '["云间雙鳳鳴，一去一归城。","鞍马朝天色，封章戀闕情。","日臨宮樹高，煙蓋沙草平。","會當戎事息，聯影遶池行。"]', '诗', 'shi', '', NULL, '和裴相公道中贈別張相公 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66f3955f-e971-44b8-9d9e-ae10c784bf40', '和錢舍人水植詩', '和錢舍人水植诗', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["盆裏盛野泉，晚鮮幽更好。","初活草根浮，重生荷葉小。","多時水馬出，盡日蜻蜓遶。","朝早獨來看，冷星沈碧曉。"]', '["盆裏盛野泉，晚鲜幽更好。","初活草根浮，重生荷葉小。","多时水马出，尽日蜻蜓遶。","朝早独来看，冷星沈碧晓。"]', '诗', 'shi', '', NULL, '和錢舍人水植詩 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e75f834-9e40-4e26-8167-a63f3979d3d5', '題壽安南館', '題壽安南館', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["明蒙竹間亭，天暖幽桂碧。","雲生四面山，水接當階石。","濕樹浴鳥痕，破苔臥鹿蹟。","不緣塵駕觸，堪作商皓宅。"]', '["明蒙竹间亭，天暖幽桂碧。","云生四面山，水接當階石。","濕樹浴鸟痕，破苔臥鹿蹟。","不緣塵駕觸，堪作商皓宅。"]', '诗', 'shi', '', NULL, '題壽安南館 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db092216-2813-4abb-8802-fa92516db6f2', '送張籍歸江東', '送張籍归江东', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["清泉澣塵緇，靈藥釋昏狂。","君詩發大雅，正氣回我腸。","復令五彩姿，潔白歸天常。","昔歲同講道，青襟在師傍。","出處兩相因，如彼衣與裳。","行行成此歸，離我適咸陽。","失意未還家，馬蹄盡四方。","訪余詠新文，不倦道路長。","僮僕懷昔念，亦如還故鄉。","相親惜晝夜，寢息不異牀。","猶將在遠道，忽忽起思量。","黃金未爲罍，無以挹酒漿。","所念俱貧賤，安得相發揚。","回車遠歸省，舊宅江南廂。","歸鄉非得意，但貴情義彰。","五月天氣熱，波濤毒於湯。","慎勿多飲酒，藥膳願自強。"]', '["清泉澣塵緇，靈藥釋昏狂。","君诗發大雅，正氣回我腸。","复令五彩姿，潔白归天常。","昔歲同講道，青襟在師傍。","出处兩相因，如彼衣與裳。","行行成此归，離我適咸陽。","失意未還家，马蹄尽四方。","訪余詠新文，不倦道路长。","僮僕懷昔念，亦如還故乡。","相親惜晝夜，寢息不異牀。","猶將在远道，忽忽起思量。","黄金未爲罍，無以挹酒漿。","所念俱貧賤，安得相發揚。","回车远归省，旧宅江南廂。","归乡非得意，但貴情義彰。","五月天氣熱，波濤毒於湯。","慎勿多饮酒，藥膳願自強。"]', '诗', 'shi', '', NULL, '送張籍歸江東 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab7653e1-0fe1-4051-bc3e-e6b08d29ae19', '勵學', '勵学', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["買地不肥實，其繁繫耕鑿。","良田少鋤理，蘭焦香亦薄。","勿以聽者迷，故使宮徵錯。","誰言三歲童，還能分善惡。","孜孜日求益，猶恐業未博。","況我性頑蒙，復不勤修學。","有如朝暮食，暫虧憂隕穫。","若使無六經，賢愚何所託。"]', '["買地不肥實，其繁繫耕鑿。","良田少鋤理，蘭焦香亦薄。","勿以听者迷，故使宮徵錯。","誰言三歲童，還能分善惡。","孜孜日求益，猶恐業未博。","況我性頑蒙，复不勤修学。","有如朝暮食，暫虧憂隕穫。","若使無六經，賢愚何所託。"]', '诗', 'shi', '', NULL, '勵學 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8aa0031-9b68-4a19-b6d0-6695b1021c0b', '山中寄及第故人', '山中寄及第故人', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["長長南山松，短短北磵楊。","俱承日月照，幸免斤斧傷。","去年與子別，誠言暫還鄉。","如何棄我去，天路忽騰驤。","誰謂有雙目，識貌不識腸。","豈知心內乖，著我薜蘿裳。","尋君向前事，不歎今異翔。","往往空室中，寤寐說珪璋。","十年居此溪，松桂日蒼蒼。","自從無佳人，山中不輝光。","盡棄所留藥，亦焚舊草堂。","還君誓已書，歸我學仙方。","既爲參與辰，各願不相望。","始終名利途，慎勿罹咎殃。"]', '["长长南山松，短短北磵楊。","俱承日月照，幸免斤斧傷。","去年與子別，誠言暫還乡。","如何棄我去，天路忽腾驤。","誰謂有雙目，識貌不識腸。","豈知心內乖，著我薜蘿裳。","尋君向前事，不歎今異翔。","往往空室中，寤寐说珪璋。","十年居此溪，松桂日蒼蒼。","自從無佳人，山中不輝光。","尽棄所留藥，亦焚旧草堂。","還君誓已书，归我学仙方。","既爲參與辰，各願不相望。","始終名利途，慎勿罹咎殃。"]', '诗', 'shi', '', NULL, '山中寄及第故人 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdc098ae-1b92-4a86-8a7e-469c5231d735', '求友', '求友', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["鑒形須明鏡，療疾須良醫。","若無傍人見，形疾安自知。","世路薄言行，學成棄其師。","每懷一飯恩，不重勸勉詞。","斅學既不誠，朋友道日虧。","遂作名利交，四海爭奔馳。","常慕正直人，生死不相離。","苟能成我身，甘與僮僕隨。","我言彼當信，彼道我無疑。","針藥及病源，以石投深池。","終朝舉善道，敬愛當行之。","縱令誤所見，亦貴本相規。","不求立名聲，所貴去瑕玼。","各願貽子孫，永爲後世資。"]', '["鑒形須明镜，療疾須良醫。","若無傍人见，形疾安自知。","世路薄言行，学成棄其師。","每懷一飯恩，不重勸勉词。","斅学既不誠，朋友道日虧。","遂作名利交，四海爭奔驰。","常慕正直人，生死不相離。","苟能成我身，甘與僮僕隨。","我言彼當信，彼道我無疑。","針藥及病源，以石投深池。","終朝舉善道，敬愛當行之。","縱令誤所见，亦貴本相規。","不求立名声，所貴去瑕玼。","各願貽子孫，永爲後世資。"]', '诗', 'shi', '', NULL, '求友 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4811480c-aba6-48b9-bc0d-241c51f17c8a', '寄李益少監兼送張實遊幽州', '寄李益少監兼送張實游幽州', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["大雅廢已久，人倫失其常。","天若不生君，誰復爲文綱。","迷者得道路，溺者遇舟航。","國風人已變，山澤增輝光。","星辰有其位，豈合離帝傍。","賢人既遐征，鳳鳥安來翔。","少小慕高名，所念隔山岡。","集卷新紙封，每讀常焚香。","古來難自達，取鑑在賢良。","未爲知音故，徒恨名不彰。","諒無金石堅，性命豈能長。","常恐一世中，不上君子堂。","偉哉清河子，少年志堅強。","篋中有素文，千里求發揚。","自願音韻乖，無因合宮商。","幸君達精誠，爲我求回章。"]', '["大雅廢已久，人倫失其常。","天若不生君，誰复爲文綱。","迷者得道路，溺者遇舟航。","国风人已变，山澤增輝光。","星辰有其位，豈合離帝傍。","賢人既遐征，鳳鸟安来翔。","少小慕高名，所念隔山岡。","集卷新紙封，每读常焚香。","古来难自達，取鑑在賢良。","未爲知音故，徒恨名不彰。","諒無金石堅，性命豈能长。","常恐一世中，不上君子堂。","偉哉清河子，少年志堅強。","篋中有素文，千里求發揚。","自願音韻乖，無因合宮商。","幸君達精誠，爲我求回章。"]', '诗', 'shi', '', NULL, '寄李益少監兼送張實遊幽州 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b11e727-9af6-4a6c-b4c1-daa5547e0ad0', '寄崔列中丞', '寄崔列中丞', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["火山無冷地，濁流無清源。","人生在艱世，何處避讒言。","諸侯鎮九州，天子開四門。","尚有忠義士，不得申其冤。","嘉木移遠植，爲我當行軒。","君子居要途，易失主人恩。","我愛古人道，師君直且溫。","貪泉誓不飲，邪路誓不奔。","如何非岡坂，故使車輪翻。","妓妾隨他人，家事幸獲存。","當時門前客，默默空冤煩。","從今遇明代，善惡亦須論。","莫以曾見疑，直道遂不敦。"]', '["火山無冷地，濁流無清源。","人生在艱世，何处避讒言。","諸侯鎮九州，天子开四门。","尚有忠義士，不得申其冤。","嘉木移远植，爲我當行軒。","君子居要途，易失主人恩。","我愛古人道，師君直且溫。","貪泉誓不饮，邪路誓不奔。","如何非岡坂，故使车輪翻。","妓妾隨他人，家事幸獲存。","當时门前客，默默空冤煩。","從今遇明代，善惡亦須論。","莫以曾见疑，直道遂不敦。"]', '诗', 'shi', '', NULL, '寄崔列中丞 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c4151f4-a21d-431c-a30b-220a65f5fecd', '喩時', '喩时', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["去者如弊帷，來者如新衣。","鮮華非久長，色落還棄遺。","詎知行者夭，豈悟壯者衰。","區區未死間，回面相是非。","好聞苦不樂，好視忽生疵。","乃明萬物情，皆逐人心移。","古今盡如此，達士將何爲。"]', '["去者如弊帷，来者如新衣。","鲜华非久长，色落還棄遺。","詎知行者夭，豈悟壯者衰。","區區未死间，回面相是非。","好闻苦不乐，好視忽生疵。","乃明万物情，皆逐人心移。","古今尽如此，達士將何爲。"]', '诗', 'shi', '', NULL, '喩時 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33ab50e2-eea7-4403-afb3-34719c8495ed', '贈王侍御', '贈王侍御', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["愚者昧邪正，貴將平道行。","君子抱仁義，不懼天地傾。","三受主人辟，方出咸陽城。","遲疑匪自崇，將顯求賢名。","自來掌軍書，無不盡臣誠。","何必操白刃，始致海內平。","恭事四海人，甚於敬公卿。","有惡如己辱，聞善如已榮。","或人居飢寒，進退陳中情。","徹晏聽苦辛，坐臥身不寧。","以心應所求，盡家猶爲輕。","衣食有親疎，但恐踰禮經。","我今願求益，詎敢爲友生。","幸君揚素風，永作來者程。"]', '["愚者昧邪正，貴將平道行。","君子抱仁義，不懼天地傾。","三受主人辟，方出咸陽城。","遲疑匪自崇，將显求賢名。","自来掌軍书，無不尽臣誠。","何必操白刃，始致海內平。","恭事四海人，甚於敬公卿。","有惡如己辱，闻善如已榮。","或人居飢寒，進退陳中情。","徹晏听苦辛，坐臥身不寧。","以心應所求，尽家猶爲轻。","衣食有親疎，但恐踰禮經。","我今願求益，詎敢爲友生。","幸君揚素风，永作来者程。"]', '诗', 'shi', '', NULL, '贈王侍御 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f2cc792-642c-4d3a-8113-c9f46ea1fd7f', '宋氏五女', '宋氏五女', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["五女誓終養，貞孝內自持。","兔絲自縈紆，不上青松枝。","晨昏在親傍，閑則讀書詩。","自得聖人心，不因儒者知。","少年絕音華，貴絕父母詞。","素釵垂兩髦，短窄古時衣。","行成聞四方，徵詔環珮隨。","同時入皇宮，聯影步玉墀。","鄉中尚其風，重爲修茅茨。","聖朝有良史，將此爲女師。"]', '["五女誓終養，貞孝內自持。","兔絲自縈紆，不上青松枝。","晨昏在親傍，闲則读书诗。","自得聖人心，不因儒者知。","少年絕音华，貴絕父母词。","素釵垂兩髦，短窄古时衣。","行成闻四方，徵詔环珮隨。","同时入皇宮，聯影步玉墀。","乡中尚其风，重爲修茅茨。","聖朝有良史，將此爲女師。"]', '诗', 'shi', '', NULL, '宋氏五女 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c72f6a51-1cf2-4924-b193-bbe6bbb411ca', '送于丹移家洺州', '送于丹移家洺州', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["憶昔門館前，君當童子年。","今來見成長，俱過遠所傳。","詩禮不外學，兄弟相攻研。","如彼販海翁，豈種溪中田。","四方尚爾文，獨我敬爾賢。","但愛金玉聲，不貴金玉堅。","孤遺一室中，寢食不相捐。","飽如腸胃同，疾若膚體連。","耕者求沃土，漚者求深源。","彼邦君子居，一日可徂遷。","念此居處近，各爲衣食牽。","從今不見面，猶勝異山川。","既乖歡會期，鬱鬱兩難宣。","素琴苦無徽，安得宮商全。","他皆緩別日，我願促行軒。","送人莫長歌，長歌離恨延。","羸馬不知去，過門常盤旋。","會當爲爾鄰，有地容一泉。"]', '["憶昔门館前，君當童子年。","今来见成长，俱過远所傳。","诗禮不外学，兄弟相攻研。","如彼販海翁，豈種溪中田。","四方尚爾文，独我敬爾賢。","但愛金玉声，不貴金玉堅。","孤遺一室中，寢食不相捐。","飽如腸胃同，疾若膚體連。","耕者求沃土，漚者求深源。","彼邦君子居，一日可徂遷。","念此居处近，各爲衣食牽。","從今不见面，猶勝異山川。","既乖歡會期，鬱鬱兩难宣。","素琴苦無徽，安得宮商全。","他皆緩別日，我願促行軒。","送人莫长歌，长歌離恨延。","羸马不知去，過门常盤旋。","會當爲爾鄰，有地容一泉。"]', '诗', 'shi', '', NULL, '送于丹移家洺州 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0f1e9a8-8f81-4001-9a1d-3fbe51e29e89', '留別舍弟', '留別舍弟', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["孤賤相長育，未曾爲遠遊。","誰不重歡愛，晨昏闕珍羞。","出門念衣車，草木當窮秋。","非疾有憂歎，實爲人子尤。","世情本難合，對面隔山丘。","況復干戈地，儒夫何所投。","與爾俱長成，尚爲溝壑憂。","豈非輕歲月，少小不勤修。","從今解思量，勉力謀善猷。","但得成爾身，衣食寧我求。","固合受此訓，墮慢爲身羞。","歲暮當歸來，慎莫懷遠遊。"]', '["孤賤相长育，未曾爲远游。","誰不重歡愛，晨昏闕珍羞。","出门念衣车，草木當窮秋。","非疾有憂歎，實爲人子尤。","世情本难合，对面隔山丘。","況复干戈地，儒夫何所投。","與爾俱长成，尚爲溝壑憂。","豈非轻歲月，少小不勤修。","從今解思量，勉力謀善猷。","但得成爾身，衣食寧我求。","固合受此訓，墮慢爲身羞。","歲暮當归来，慎莫懷远游。"]', '诗', 'shi', '', NULL, '留別舍弟 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('380d7f3c-cd6c-47ce-9ccb-a8a90906376f', '壞屋', '壞屋', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["官家有壞屋，居者願離得。","苟或幸其遷，回循任傾側。","若當君子住，一日還修餙。","必使換榱楹，先須木端直。","永令雀與鼠，無處求棲息。","堅固傳後人，從今勉勞力。","以茲喩臣下，亦可成邦國。","雖曰愚者詞，將來幸無惑。"]', '["官家有壞屋，居者願離得。","苟或幸其遷，回循任傾側。","若當君子住，一日還修餙。","必使換榱楹，先須木端直。","永令雀與鼠，無处求棲息。","堅固傳後人，從今勉勞力。","以茲喩臣下，亦可成邦国。","雖曰愚者词，將来幸無惑。"]', '诗', 'shi', '', NULL, '壞屋 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dccf57d8-9597-43fe-a8ea-034e4ae4776e', '送薛蔓應舉', '送薛蔓應舉', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["四海重貢獻，珠賮稱至珍。","聖朝開禮闈，所貴集嘉賓。","若生在世間，此路出常倫。","一士登甲科，九族光彩新。","憧憧車馬徒，爭路長安塵。","萬目視高天，昇者得苦辛。","況子當少年，丈人在咸秦。","出門見宮闕，獻賦侍朱輪。","有賢大國豐，無子一家貧。","男兒富邦家，豈爲榮其身。","煌煌文明代，俱幸生此辰。","自顧非國風，難以合聖人。","子去東堂上，我歸南澗濱。","願君勤作書，與我山中鄰。"]', '["四海重貢獻，珠賮稱至珍。","聖朝开禮闈，所貴集嘉賓。","若生在世间，此路出常倫。","一士登甲科，九族光彩新。","憧憧车马徒，爭路长安塵。","万目視高天，昇者得苦辛。","況子當少年，丈人在咸秦。","出门见宮闕，獻賦侍朱輪。","有賢大国豐，無子一家貧。","男兒富邦家，豈爲榮其身。","煌煌文明代，俱幸生此辰。","自顧非国风，难以合聖人。","子去东堂上，我归南澗濱。","願君勤作书，與我山中鄰。"]', '诗', 'shi', '', NULL, '送薛蔓應舉 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9661054e-93f0-4f1b-bec0-0c83814e189d', '將歸故山留別杜侍御', '將归故山留別杜侍御', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["有川不得涉，有路不得行。","沈沈百憂中，一日如一生。","錯來干諸侯，石田廢春耕。","虎戟衞重門，何因達中誠。","日月俱照輝，山川異陰晴。","如何百里間，開目不見明。","我今歸故山，誓與草木幷。","願君去丘坂，長使道路平。"]', '["有川不得涉，有路不得行。","沈沈百憂中，一日如一生。","錯来干諸侯，石田廢春耕。","虎戟衞重门，何因達中誠。","日月俱照輝，山川異陰晴。","如何百里间，开目不见明。","我今归故山，誓與草木幷。","願君去丘坂，长使道路平。"]', '诗', 'shi', '', NULL, '將歸故山留別杜侍御 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb751212-3263-4f61-ae0c-1c2397ac6578', '送韋處士老舅', '送韋处士老舅', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["憶昨癡小年，不知有經籍。","常隨童子遊，多向外家劇。","偷花入鄰里，弄筆書牆壁。","照水學梳頭，應門未穿幘。","人前賞文性，棃果蒙不惜。","賦字詠新泉，探題得幽石。","自從出關輔，三十年作客。","風雨一飄颻，親情多阻隔。","如何二千里，塵土驅蹇瘠。","良久陳苦辛，從頭歎衰白。","既來今又去，暫笑還成戚。","落日動征車，春風卷離席。","雲臺觀西路，華岳祠前柏。","會得過帝鄉，重尋舊行蹟。"]', '["憶昨癡小年，不知有經籍。","常隨童子游，多向外家劇。","偷花入鄰里，弄笔书牆壁。","照水学梳头，應门未穿幘。","人前賞文性，棃果蒙不惜。","賦字詠新泉，探題得幽石。","自從出关輔，三十年作客。","风雨一飄颻，親情多阻隔。","如何二千里，塵土驱蹇瘠。","良久陳苦辛，從头歎衰白。","既来今又去，暫笑還成戚。","落日动征车，春风卷離席。","云台观西路，华岳祠前柏。","會得過帝乡，重尋旧行蹟。"]', '诗', 'shi', '', NULL, '送韋處士老舅 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('546e3a8a-d3a5-4930-8098-8754e020ca35', '送同學故人', '送同学故人', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["各爲四方人，此地同事師。","業成有先後，不得長相隨。","出林多道路，緣岡復遶陂。","念君辛苦行，令我形體疲。","黃葉墮車前，四散當此時。","亭上夜蕭索，山風水離離。"]', '["各爲四方人，此地同事師。","業成有先後，不得长相隨。","出林多道路，緣岡复遶陂。","念君辛苦行，令我形體疲。","黄葉墮车前，四散當此时。","亭上夜蕭索，山风水離離。"]', '诗', 'shi', '', NULL, '送同學故人 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc82c7ca-e900-4c69-b6a9-9c14cd89aadf', '幽州送申稷評事歸平盧', '幽州送申稷評事归平盧', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["行子繞天北，山高塞復深。","升堂展客禮，臨水濯纓襟。","驅馳戎地馬，聚散林間禽。","一杯瀉東流，各願無異心。","薊亭雖苦寒，春夕勿重衾。","從軍任白頭，莫賣故山岑。"]', '["行子繞天北，山高塞复深。","升堂展客禮，臨水濯纓襟。","驱驰戎地马，聚散林间禽。","一杯瀉东流，各願無異心。","薊亭雖苦寒，春夕勿重衾。","從軍任白头，莫賣故山岑。"]', '诗', 'shi', '', NULL, '幽州送申稷評事歸平盧 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a90251b7-5025-4345-9e39-6e3b7f42230c', '溫門山', '溫门山', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["早入溫門山，羣峰亂如戟。","崩崖欲相觸，呀豁斷行跡。","脫屐尋淺流，定足畏欹石。","路盡十里溪，地多千歲栢。","洞門晝陰黑，深處惟石壁。","似見丹砂光，亦聞鍾乳滴。","靈池出山底，沸水沖地脈。","暖氣成濕煙，濛濛窗中白。","隨僧入古寺，便是雲外客。","月出天氣涼，夜鐘山寂寂。"]', '["早入溫门山，羣峰亂如戟。","崩崖欲相觸，呀豁斷行跡。","脫屐尋淺流，定足畏欹石。","路尽十里溪，地多千歲栢。","洞门晝陰黑，深处惟石壁。","似见丹砂光，亦闻鍾乳滴。","靈池出山底，沸水沖地脈。","暖氣成濕煙，濛濛窗中白。","隨僧入古寺，便是云外客。","月出天氣涼，夜鐘山寂寂。"]', '诗', 'shi', '', NULL, '溫門山 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d84e98a-9ad7-4e40-b772-4da9680ad763', '代故人新姬侍疾', '代故人新姬侍疾', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["雙轂不回轍，子疾已在傍。","侍坐長搖扇，迎醫漸下牀。","新施箱中幔，未洗來時妝。","奉君纏綿意，幸願莫相忘。"]', '["雙轂不回轍，子疾已在傍。","侍坐长搖扇，迎醫漸下牀。","新施箱中幔，未洗来时妝。","奉君纏綿意，幸願莫相忘。"]', '诗', 'shi', '', NULL, '代故人新姬侍疾 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74b26b8b-be15-482f-a6b0-0135133c917f', '採桑', '採桑', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["鳥鳴桑葉間，綠條復柔柔。","攀看去手近，放下長長鉤。","黃花蓋野田，白馬少年遊。","所念豈回顧，良人在高樓。"]', '["鸟鳴桑葉间，綠條复柔柔。","攀看去手近，放下长长鉤。","黄花蓋野田，白马少年游。","所念豈回顧，良人在高楼。"]', '诗', 'shi', '', NULL, '採桑 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9ab989a-79e5-45b2-8eda-0cf6e74818dc', '曉思', '晓思', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["曉氣生綠水，春條露霏霏。","林間棲鳥散，遠念征人起。","幽花宿含彩，早蝶寒弄翅。","君行非晨風，詎能從門至。"]', '["晓氣生綠水，春條露霏霏。","林间棲鸟散，远念征人起。","幽花宿含彩，早蝶寒弄翅。","君行非晨风，詎能從门至。"]', '诗', 'shi', '', NULL, '曉思 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb0080b1-c476-47dc-a946-c5b8d668ec27', '早起', '早起', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["回燈正衣裳，出戶星未稀。","堂前候姑起，環珮生晨輝。","暗池光羃䍥，密樹花葳蕤。","九城鐘漏絕，遙聽直郎歸。"]', '["回灯正衣裳，出戶星未稀。","堂前候姑起，环珮生晨輝。","暗池光羃䍥，密樹花葳蕤。","九城鐘漏絕，遙听直郎归。"]', '诗', 'shi', '', NULL, '早起 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('684387fe-9020-4b93-97e8-37a7cda07cf3', '酬張十八病中寄詩', '酬張十八病中寄诗', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["本性慵遠行，綿綿病自生。","見君綢繆思，慰我寂寞情。","風幌夜不掩，秋燈照雨明。","彼愁此又憶，一夕兩盈盈。"]', '["本性慵远行，綿綿病自生。","见君綢繆思，慰我寂寞情。","风幌夜不掩，秋灯照雨明。","彼愁此又憶，一夕兩盈盈。"]', '诗', 'shi', '', NULL, '酬張十八病中寄詩 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9159fcd-f025-43f3-b009-1ead5ede5268', '涼州行', '涼州行', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["涼州四邊沙皓皓，漢家無人開舊道。","邊頭州縣盡胡兵，將軍別築防秋城。","萬里人家皆已沒，年年旌節發西京。","多來中國收婦女，一半生男爲漢語。","蕃人舊日不耕犂，相學如今種禾黍。","驅羊亦著錦爲衣，爲惜氈裘防鬬時。","養蠶繅繭成匹帛，那堪繞帳作旌旗。","城頭山雞鳴角角，洛陽家家學胡樂。"]', '["涼州四邊沙皓皓，漢家無人开旧道。","邊头州縣尽胡兵，將軍別築防秋城。","万里人家皆已沒，年年旌節發西京。","多来中国收婦女，一半生男爲漢語。","蕃人旧日不耕犂，相学如今種禾黍。","驱羊亦著錦爲衣，爲惜氈裘防鬬时。","養蠶繅繭成匹帛，那堪繞帳作旌旗。","城头山雞鳴角角，洛陽家家学胡乐。"]', '诗', 'shi', '', NULL, '涼州行 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('124207a8-53d1-49be-aacd-ddcd530fab38', '寒食行', '寒食行', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["寒食家家出古城，老人看屋少年行。","丘壠年年無舊道，車徒散行入衰草。","牧兒驅牛下塚頭，畏有家人來灑掃。","遠人無墳水頭祭，還引婦姑望鄉拜。","三日無火燒紙錢，紙錢那得到黃泉。","但看壠上無新土，此中白骨應無主。"]', '["寒食家家出古城，老人看屋少年行。","丘壠年年無旧道，车徒散行入衰草。","牧兒驱牛下塚头，畏有家人来灑掃。","远人無墳水头祭，還引婦姑望乡拜。","三日無火燒紙錢，紙錢那得到黄泉。","但看壠上無新土，此中白骨應無主。"]', '诗', 'shi', '', NULL, '寒食行 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31438fab-f58e-4e89-93c1-9a01aface955', '促剌詞', '促剌词', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["促剌復促剌，水中無魚山無石。","少年雖嫁不得歸，頭白猶著父母衣。","田邊舊宅非所有，我身不及逐雞飛。","出門若有歸死處，猛虎當衢向前去。","百年不遺踏君門，在家誰喚爲新婦。","豈不見他鄰舍娘，嫁來常在舅姑傍。"]', '["促剌复促剌，水中無鱼山無石。","少年雖嫁不得归，头白猶著父母衣。","田邊旧宅非所有，我身不及逐雞飞。","出门若有归死处，猛虎當衢向前去。","百年不遺踏君门，在家誰喚爲新婦。","豈不见他鄰舍娘，嫁来常在舅姑傍。"]', '诗', 'shi', '', NULL, '促剌詞 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aa3602c-eb42-4fc5-8839-215fd094ce16', '壠頭水', '壠头水', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["壠水何年壠頭別，不在山中亦嗚咽。","征人塞耳馬不行，未到壠頭聞水聲。","謂是西流入蒲海，還聞北去繞龍城。","壠東壠西多屈曲，野麋飲水長簇簇。","胡兵夜回水旁住，憶著來時磨劒處。","向前無井復無泉，放馬回看壠頭樹。"]', '["壠水何年壠头別，不在山中亦嗚咽。","征人塞耳马不行，未到壠头闻水声。","謂是西流入蒲海，還闻北去繞龙城。","壠东壠西多屈曲，野麋饮水长簇簇。","胡兵夜回水旁住，憶著来时磨劒处。","向前無井复無泉，放马回看壠头樹。"]', '诗', 'shi', '', NULL, '壠頭水 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('988939d3-4c01-4bbf-928d-0c542920c3d5', '北邙行', '北邙行', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["北邙山頭少閑士，盡是洛陽人舊墓。","舊墓人家歸葬多，堆著黃金無買處。","天涯悠悠葬日促，岡坂崎嶇不停轂。","高張素幕繞銘旌，夜唱挽歌山下宿。","洛陽城北復城東，魂車祖馬長相逢。","車轍廣若長安路，蒿草少於松柏樹。","澗底盤陀石漸稀，盡向墳向作羊虎。","誰家石碑文字滅，後人重取書年月。","朝朝車馬送葬回，還起大宅與高臺。"]', '["北邙山头少闲士，尽是洛陽人旧墓。","旧墓人家归葬多，堆著黄金無買处。","天涯悠悠葬日促，岡坂崎嶇不停轂。","高張素幕繞銘旌，夜唱挽歌山下宿。","洛陽城北复城东，魂车祖马长相逢。","车轍廣若长安路，蒿草少於松柏樹。","澗底盤陀石漸稀，尽向墳向作羊虎。","誰家石碑文字滅，後人重取书年月。","朝朝车马送葬回，還起大宅與高台。"]', '诗', 'shi', '', NULL, '北邙行 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bbfafbe-cb90-4552-8ddf-b3789804f5d2', '溫泉宮行', '溫泉宮行', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["十月一日天子來，青繩御路無塵埃。","宮前內裏湯各別，每箇白玉芙蓉開。","朝元閣向山上起，城繞青山龍暖水。","夜開金殿看星河，宮女知更月明裏。","武皇得仙王母去，山雞晝鳴宮中樹。","溫泉決決出宮流，宮使年年修玉樓。","禁兵去盡無射獵，日西麋鹿登城頭。","棃園弟子偷曲譜，頭白人間教歌舞。"]', '["十月一日天子来，青繩御路無塵埃。","宮前內裏湯各別，每箇白玉芙蓉开。","朝元閣向山上起，城繞青山龙暖水。","夜开金殿看星河，宮女知更月明裏。","武皇得仙王母去，山雞晝鳴宮中樹。","溫泉決決出宮流，宮使年年修玉楼。","禁兵去尽無射獵，日西麋鹿登城头。","棃园弟子偷曲譜，头白人间教歌舞。"]', '诗', 'shi', '', NULL, '溫泉宮行 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acb9fa7a-7147-40eb-8613-68de9dba2e19', '春詞', '春词', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["紅煙滿戶日照梁，天絲軟弱蟲飛揚。","菱花霍霍繞帷光，美人對鏡著衣裳。","庭中並種相思樹，夜夜還棲雙鳳凰。"]', '["紅煙满戶日照梁，天絲軟弱蟲飞揚。","菱花霍霍繞帷光，美人对镜著衣裳。","庭中並種相思樹，夜夜還棲雙鳳凰。"]', '诗', 'shi', '', NULL, '春詞 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9857add-a99a-4c64-af63-2b22c8263508', '遼東行', '遼东行', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["遼東萬里遼水曲，古戍無城復無屋。","黃雲蓋地雪作山，不惜黃金買衣服。","戰回各自收弓箭，正西回面家鄉遠。","年年郡縣送征人，將與遼東作丘坂。","寧爲草木鄉中生，有身不向遼東行。"]', '["遼东万里遼水曲，古戍無城复無屋。","黄云蓋地雪作山，不惜黄金買衣服。","戰回各自收弓箭，正西回面家乡远。","年年郡縣送征人，將與遼东作丘坂。","寧爲草木乡中生，有身不向遼东行。"]', '诗', 'shi', '', NULL, '遼東行 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7806360-7bc2-41cb-b8bf-f889b1c9362e', '塞上梅', '塞上梅', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["天山路傍一株梅，年年花發黃雲下。","昭君已歿漢使回，前後征人惟繫馬。","日夜風吹滿隴頭，還隨隴水東西流。","此花若近長安路，九衢年少無攀處。"]', '["天山路傍一株梅，年年花發黄云下。","昭君已歿漢使回，前後征人惟繫马。","日夜风吹满隴头，還隨隴水东西流。","此花若近长安路，九衢年少無攀处。"]', '诗', 'shi', '', NULL, '塞上梅 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('396a0cc2-38dc-45c7-be8a-615efb330b57', '戴勝詞', '戴勝词', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["戴勝誰與爾爲名，木中作窠牆上鳴。","聲聲催我急種轂，人家向田不歸宿。","紫冠采采褐羽斑，銜得蜻蜓飛過屋。","可憐白鷺滿綠池，不如戴勝知天時。"]', '["戴勝誰與爾爲名，木中作窠牆上鳴。","声声催我急種轂，人家向田不归宿。","紫冠采采褐羽斑，銜得蜻蜓飞過屋。","可怜白鷺满綠池，不如戴勝知天时。"]', '诗', 'shi', '', NULL, '戴勝詞 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db5e7031-fe00-4693-a3e0-ed08debf7dec', '鞦韆詞', '鞦韆词', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["長長絲繩紫復碧，嫋嫋橫枝高百尺。","少年兒女重鞦韆，盤巾結帶分兩邊。","身輕裙薄易生力，雙手向空如鳥翼。","下來立定重繫衣，復畏斜風高不得。","傍人送上那足貴，終賭鳴璫鬬自起。","回回若與高樹齊，頭上寶釵從墮地。","眼前爭勝難爲休，足踏平地看始愁。"]', '["长长絲繩紫复碧，嫋嫋橫枝高百尺。","少年兒女重鞦韆，盤巾結带分兩邊。","身轻裙薄易生力，雙手向空如鸟翼。","下来立定重繫衣，复畏斜风高不得。","傍人送上那足貴，終賭鳴璫鬬自起。","回回若與高樹齊，头上寶釵從墮地。","眼前爭勝难爲休，足踏平地看始愁。"]', '诗', 'shi', '', NULL, '鞦韆詞 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a30aff99-3d64-40a0-8585-4a1cb8f73780', '開池得古釵', '开池得古釵', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["美人開池北堂下，拾得寶釵金未化。","鳳凰半在雙股齊，鈿花落處生黃泥。","當時墮地覓不得，暗想窗中還夜啼。","可知將來對夫壻，鏡前學梳古時髻。","莫言至死亦不遺，還似前人初得時。"]', '["美人开池北堂下，拾得寶釵金未化。","鳳凰半在雙股齊，鈿花落处生黄泥。","當时墮地覓不得，暗想窗中還夜啼。","可知將来对夫壻，镜前学梳古时髻。","莫言至死亦不遺，還似前人初得时。"]', '诗', 'shi', '', NULL, '開池得古釵 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('676c6fd4-203d-47e3-8aea-00e2a34d96ea', '賽神曲', '賽神曲', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["男抱琵琶女作舞，主人再拜聽神語。","新婦上酒勿辭勤，使爾舅姑無所苦。","椒漿湛湛桂座新，一雙長箭繫紅巾。","但願牛羊滿家宅，十月報賽南山神。","青天無風水復碧，龍馬上鞍牛服軛。","紛紛醉舞踏衣裳，把酒路旁勸行客。"]', '["男抱琵琶女作舞，主人再拜听神語。","新婦上酒勿辞勤，使爾舅姑無所苦。","椒漿湛湛桂座新，一雙长箭繫紅巾。","但願牛羊满家宅，十月報賽南山神。","青天無风水复碧，龙马上鞍牛服軛。","紛紛醉舞踏衣裳，把酒路旁勸行客。"]', '诗', 'shi', '', NULL, '賽神曲 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39c1283a-f88c-4375-9f4c-70e3159ef04e', '田家留客', '田家留客', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["人家少能留我屋，客有新漿馬有粟。","遠行僮僕應苦飢，新婦廚中炊欲熟。","不嫌田家破門戶，蠶房新泥無風土。","行人但飲莫畏貧，明府上來何苦辛。","丁寧回語屋中妻，有客勿令兒夜啼。","雙塚直西有縣路，我教丁男送君去。"]', '["人家少能留我屋，客有新漿马有粟。","远行僮僕應苦飢，新婦廚中炊欲熟。","不嫌田家破门戶，蠶房新泥無风土。","行人但饮莫畏貧，明府上来何苦辛。","丁寧回語屋中妻，有客勿令兒夜啼。","雙塚直西有縣路，我教丁男送君去。"]', '诗', 'shi', '', NULL, '田家留客 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af6128a3-ddea-4701-a489-e0f367f7200e', '精衞詞', '精衞词', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["精衞誰教爾填海，海邊石子青磊磊。","但得海水作枯池，海中魚龍何所爲。","口穿豈爲空銜石，山中草木無全枝。","朝在樹頭暮海裏，飛多羽折時墮水。","高山未盡海未平，願我身死子還生。"]', '["精衞誰教爾填海，海邊石子青磊磊。","但得海水作枯池，海中鱼龙何所爲。","口穿豈爲空銜石，山中草木無全枝。","朝在樹头暮海裏，飞多羽折时墮水。","高山未尽海未平，願我身死子還生。"]', '诗', 'shi', '', NULL, '精衞詞 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39142992-539e-419e-8546-182666f9ede6', '老婦歎鏡', '老婦歎镜', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["嫁時明鏡老猶在，黃金鏤畫雙鳳背。","憶昔咸陽初買來，燈前自繡芙蓉帶。","十年不開一片鐵，長向暗中梳白髮。","今日後牀重照看，生死終當此長別。"]', '["嫁时明镜老猶在，黄金鏤畫雙鳳背。","憶昔咸陽初買来，灯前自繡芙蓉带。","十年不开一片鐵，长向暗中梳白髮。","今日後牀重照看，生死終當此长別。"]', '诗', 'shi', '', NULL, '老婦歎鏡 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4af6a6ef-c011-48c1-9485-b5b6ec581fe6', '望夫石', '望夫石', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["望夫處，江悠悠，化爲石，不回頭。","上頭日日風復雨，行人歸來石應語。"]', '["望夫处，江悠悠，化爲石，不回头。","上头日日风复雨，行人归来石應語。"]', '诗', 'shi', '', NULL, '望夫石 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc55325f-3c89-4e22-ae8d-042170027926', '別鶴曲', '別鹤曲', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["主人一去池水絕，池鶴散飛不相別。","青天漫漫碧水重，知向何山風雪中。","萬里雖然音影在，兩心終是死生同。","池邊巢破松樹死，樹頭年年烏生子。"]', '["主人一去池水絕，池鹤散飞不相別。","青天漫漫碧水重，知向何山风雪中。","万里雖然音影在，兩心終是死生同。","池邊巢破松樹死，樹头年年烏生子。"]', '诗', 'shi', '', NULL, '別鶴曲 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4b50477-282b-4699-886f-35c25410a3e0', '烏棲曲', '烏棲曲', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["章華宮人夜上樓，君王望月西山頭。","夜深宮殿門不鎖，白露滿山山葉墮。"]', '["章华宮人夜上楼，君王望月西山头。","夜深宮殿门不鎖，白露满山山葉墮。"]', '诗', 'shi', '', NULL, '烏棲曲 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a1d2b85-1c8e-4d56-8b68-083c95ec1cf3', '雉將雛', '雉將雛', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["雉咿喔，雛出㲉，毛斑斑，觜啄啄。","學飛未得一尺高，還逐母行旋母脚。","麥壟淺淺難蔽身，遠去戀雛低怕人。","時時土中鼓兩翅，引雛拾蟲不相離。"]', '["雉咿喔，雛出㲉，毛斑斑，觜啄啄。","学飞未得一尺高，還逐母行旋母脚。","麦壟淺淺难蔽身，远去戀雛低怕人。","时时土中鼓兩翅，引雛拾蟲不相離。"]', '诗', 'shi', '', NULL, '雉將雛 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2c97c4b-aff9-42a6-841b-cbc358d85ddf', '白紵歌二首 一', '白紵歌二首 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["天河漫漫北斗璨，宮中烏啼知夜半。","新縫白紵舞衣成，來遲邀得吳王迎。","低鬟轉面掩雙袖，玉釵浮動秋風生。","酒多夜長夜未曉，月明燈光兩相照，後庭歌聲更窈窕。"]', '["天河漫漫北斗璨，宮中烏啼知夜半。","新縫白紵舞衣成，来遲邀得吳王迎。","低鬟轉面掩雙袖，玉釵浮动秋风生。","酒多夜长夜未晓，月明灯光兩相照，後庭歌声更窈窕。"]', '诗', 'shi', '', NULL, '白紵歌二首 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32e0c97c-34f5-4030-bd0a-a410f5643784', '白紵歌二首 二', '白紵歌二首 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["館娃宮中春日暮，荔枝木瓜花滿樹。","城頭烏棲休擊鼓，青蛾彈瑟白紵舞。","夜天曈曈不見星，宮中火照西江明。","美人醉起無次第，墮釵遺珮滿中庭。","此時但願可君意，回晝爲宵亦不寐，年年奉君君莫棄。"]', '["館娃宮中春日暮，荔枝木瓜花满樹。","城头烏棲休擊鼓，青蛾彈瑟白紵舞。","夜天曈曈不见星，宮中火照西江明。","美人醉起無次第，墮釵遺珮满中庭。","此时但願可君意，回晝爲宵亦不寐，年年奉君君莫棄。"]', '诗', 'shi', '', NULL, '白紵歌二首 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1eff153c-0993-4236-8430-289b1d13c8a0', '短歌行', '短歌行', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["人初生，日初出，上山遲，下山疾。","百年三萬六千朝，夜裏分將強半日。","有歌有舞須早爲，昨日健於今日時。","人家見生男女好，不知男女催人老。","短歌行，無樂聲。"]', '["人初生，日初出，上山遲，下山疾。","百年三万六千朝，夜裏分將強半日。","有歌有舞須早爲，昨日健於今日时。","人家见生男女好，不知男女催人老。","短歌行，無乐声。"]', '诗', 'shi', '', NULL, '短歌行 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2d88511-cac0-434e-a102-792458bc3af5', '飲馬長城窟', '饮马长城窟', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["長城窟，長城窟邊多馬骨。","古來此地無井泉，賴得秦家築城卒。","征人飲馬愁不回，長城變作望鄉堆。","蹄蹤未乾人去近，續後馬來泥污盡。","枕弓睡著待水生，不見陰山在前陣。","馬蹄足脫裝馬頭，健兒戰死誰封侯。"]', '["长城窟，长城窟邊多马骨。","古来此地無井泉，賴得秦家築城卒。","征人饮马愁不回，长城变作望乡堆。","蹄蹤未乾人去近，續後马来泥污尽。","枕弓睡著待水生，不见陰山在前陣。","马蹄足脫裝马头，健兒戰死誰封侯。"]', '诗', 'shi', '', NULL, '飲馬長城窟 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98d7c675-3763-425d-827d-cd3d96d5ee38', '烏夜啼', '烏夜啼', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["庭樹烏，爾何不向別處棲？","夜夜夜半當戶啼。","家人把燭出洞戶，驚棲失羣飛落樹。","一飛直欲飛上天，回回不離舊棲處。","未明重繞主人屋，欲下空中黑相觸。","風飄雨濕亦不移，君家樹頭多好枝。"]', '["庭樹烏，爾何不向別处棲？","夜夜夜半當戶啼。","家人把燭出洞戶，驚棲失羣飞落樹。","一飞直欲飞上天，回回不離旧棲处。","未明重繞主人屋，欲下空中黑相觸。","风飄雨濕亦不移，君家樹头多好枝。"]', '诗', 'shi', '', NULL, '烏夜啼 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec370770-8350-41f2-81ff-c79d7dc452fe', '簇蠶辭', '簇蠶辞', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["蠶欲老，箔頭作繭絲皓皓。","場寬地高風日多，不向中庭曬蒿草。","神蠶急作莫悠揚，年來爲爾祭神桑。","但得青天不下雨，上無蒼蠅下無鼠。","新婦拜簇願繭稠，女灑桃漿男打鼓。","三日開箔雪團團，先將新繭送縣官。","已聞鄉里催織作，去與誰人身上著。"]', '["蠶欲老，箔头作繭絲皓皓。","場寬地高风日多，不向中庭曬蒿草。","神蠶急作莫悠揚，年来爲爾祭神桑。","但得青天不下雨，上無蒼蠅下無鼠。","新婦拜簇願繭稠，女灑桃漿男打鼓。","三日开箔雪團團，先將新繭送縣官。","已闻乡里催织作，去與誰人身上著。"]', '诗', 'shi', '', NULL, '簇蠶辭 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ea88702-91b1-4d3c-870b-14f3d4114781', '渡遼水', '渡遼水', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["渡遼水，此去咸陽五千里。","來時父母知隔生，重著衣裳如送死。","亦有白骨歸咸陽，營家各與題本鄉。","身在應無回渡日，駐馬相看遼水傍。"]', '["渡遼水，此去咸陽五千里。","来时父母知隔生，重著衣裳如送死。","亦有白骨归咸陽，營家各與題本乡。","身在應無回渡日，駐马相看遼水傍。"]', '诗', 'shi', '', NULL, '渡遼水 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6390608-433d-470e-912a-1f6dad0134fe', '空城雀', '空城雀', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["空城雀，何不飛來人家住？","空城無人種禾黍，土間生子草間長。","滿地蓬蒿幸無主，近村雖有高樹枝。","雨中無食長苦飢，八月小兒挾弓箭。","家家畏向田頭飛，但能不出空城裏。","秋時百草皆有子，報言黃口莫啾啾，長爾得成無橫死。"]', '["空城雀，何不飞来人家住？","空城無人種禾黍，土间生子草间长。","满地蓬蒿幸無主，近村雖有高樹枝。","雨中無食长苦飢，八月小兒挾弓箭。","家家畏向田头飞，但能不出空城裏。","秋时百草皆有子，報言黄口莫啾啾，长爾得成無橫死。"]', '诗', 'shi', '', NULL, '空城雀 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72798678-f47c-43dc-bf79-43e41e388365', '水運行', '水運行', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["西江運船立紅幟，萬棹千帆繞江水。","去年六月無稻苗，已說水鄉人餓死。","縣官部船日算程，暴風惡雨亦不停。","在生有樂當有苦，三年作官一年行。","壞舟畏鼠復畏漏，恐向太倉折升斗。","辛勤耕種非毒藥，看著不入農夫口。","用盡百金不爲貴，但得一金即爲利。","遠徵海稻供邊食，豈如多種邊頭地。"]', '["西江運船立紅幟，万棹千帆繞江水。","去年六月無稻苗，已说水乡人餓死。","縣官部船日算程，暴风惡雨亦不停。","在生有乐當有苦，三年作官一年行。","壞舟畏鼠复畏漏，恐向太倉折升斗。","辛勤耕種非毒藥，看著不入農夫口。","用尽百金不爲貴，但得一金即爲利。","远徵海稻供邊食，豈如多種邊头地。"]', '诗', 'shi', '', NULL, '水運行 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('301bcd5f-5135-4a43-a2d2-314423cf4b74', '當窗織', '當窗织', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["歎息復歎息，園中有棗行人食。","貧家女爲富家織，翁母隔牆不得力。","水寒手澁絲脆斷，續來續去心腸爛。","草蟲促促機下啼，兩日催成一匹半。","輸官上頂有零落，姑未得衣身不著。","當窗却羨青樓倡，十指不動衣盈箱。"]', '["歎息复歎息，园中有棗行人食。","貧家女爲富家织，翁母隔牆不得力。","水寒手澁絲脆斷，續来續去心腸爛。","草蟲促促機下啼，兩日催成一匹半。","輸官上頂有零落，姑未得衣身不著。","當窗却羨青楼倡，十指不动衣盈箱。"]', '诗', 'shi', '', NULL, '當窗織 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ea9829e-b553-4509-b2d3-68b31fd347b2', '失釵怨', '失釵怨', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["貧女銅釵惜於玉，失却來尋一日哭。","嫁時女伴與作妝，頭戴此釵如鳳凰。","雙杯行酒六親喜，我家新婦宜拜堂。","鏡中乍無失髻樣，初起猶疑在牀上。","高樓翠鈿飄舞塵，明日從頭一遍新。"]', '["貧女銅釵惜於玉，失却来尋一日哭。","嫁时女伴與作妝，头戴此釵如鳳凰。","雙杯行酒六親喜，我家新婦宜拜堂。","镜中乍無失髻樣，初起猶疑在牀上。","高楼翠鈿飄舞塵，明日從头一遍新。"]', '诗', 'shi', '', NULL, '失釵怨 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b18fd37-f900-44bc-86a6-84243776001f', '春燕詞', '春燕词', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["新燕新燕何不定，東家綠池西家井。","飛鳴當戶影悠揚，一遶簷頭一遶梁。","黃姑說向新婦女，去年墮子汙衣箱。","已能辭山復過海，幸我堂前故巢在。","求食慎勿愛高飛，空中飢鳶爲爾害。","辛勤作窠在畫梁，願得年年主人富。"]', '["新燕新燕何不定，东家綠池西家井。","飞鳴當戶影悠揚，一遶簷头一遶梁。","黄姑说向新婦女，去年墮子汙衣箱。","已能辞山复過海，幸我堂前故巢在。","求食慎勿愛高飞，空中飢鳶爲爾害。","辛勤作窠在畫梁，願得年年主人富。"]', '诗', 'shi', '', NULL, '春燕詞 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e4bef3c-d99d-41e4-899c-c0110ff6e378', '主人故池', '主人故池', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["高池高閣上連起，荷葉團團蓋秋水。","主人已遠涼風生，舊客不來芙蓉死。"]', '["高池高閣上連起，荷葉團團蓋秋水。","主人已远涼风生，旧客不来芙蓉死。"]', '诗', 'shi', '', NULL, '主人故池 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fe183ad-90cb-4691-8e9f-4e71a133ee40', '古宮怨', '古宮怨', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["乳烏啞啞飛復啼，城頭晨夕宮中棲。","吳王別殿繞江水，後宮不開美人死。"]', '["乳烏啞啞飞复啼，城头晨夕宮中棲。","吳王別殿繞江水，後宮不开美人死。"]', '诗', 'shi', '', NULL, '古宮怨 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58568655-f115-4c02-bf0f-35eca3742bf4', '關山月', '关山月', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["關山月，營開道白前軍發。","凍輪當磧光悠悠，照見三堆兩堆骨。","邊風割面天欲明，金沙嶺西看看沒。"]', '["关山月，營开道白前軍發。","凍輪當磧光悠悠，照见三堆兩堆骨。","邊风割面天欲明，金沙嶺西看看沒。"]', '诗', 'shi', '', NULL, '關山月 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a48bafe1-dc29-4500-b83b-78937237372f', '贈離曲', '贈離曲', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["合歡葉墮梧桐秋，鴛鴦背飛水分流。","少年使我忽相棄，雌號雄鳴夜悠悠。","夜長月沒蟲切切，冷風入房燈焰滅。","若知中路各西東，彼此不忘同心結。","收取頭邊蛟龍枕，留著箱中雙雉裳。","我今焚却舊房物，免使他人登爾牀。"]', '["合歡葉墮梧桐秋，鴛鴦背飞水分流。","少年使我忽相棄，雌號雄鳴夜悠悠。","夜长月沒蟲切切，冷风入房灯焰滅。","若知中路各西东，彼此不忘同心結。","收取头邊蛟龙枕，留著箱中雙雉裳。","我今焚却旧房物，免使他人登爾牀。"]', '诗', 'shi', '', NULL, '贈離曲 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bc0a972-789b-493a-83f9-d597d1eee3b3', '宛轉詞', '宛轉词', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["宛宛轉轉勝上紗，紅紅綠綠苑中花。","紛紛泊泊夜飛鵶，寂寂寞寞離人家。"]', '["宛宛轉轉勝上紗，紅紅綠綠苑中花。","紛紛泊泊夜飞鵶，寂寂寞寞離人家。"]', '诗', 'shi', '', NULL, '宛轉詞 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94e1f141-b25f-4c12-8084-534b4210bd49', '水夫謠', '水夫謠', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["苦哉生長當驛邊，官家使我牽驛船。","辛苦日多樂日少，水宿沙行如海鳥。","逆風上水萬斛重，前驛迢迢後淼淼。","半夜緣堤雪和雨，受他驅遣還復去。","衣寒衣濕披短蓑，臆穿足裂忍痛何。","到明辛苦無處說，齊聲騰踏牽船出。","一間茆屋何所值，父母之鄉去不得。","我願此水作平田，長使水夫不怨天。"]', '["苦哉生长當驛邊，官家使我牽驛船。","辛苦日多乐日少，水宿沙行如海鸟。","逆风上水万斛重，前驛迢迢後淼淼。","半夜緣堤雪和雨，受他驱遣還复去。","衣寒衣濕披短蓑，臆穿足裂忍痛何。","到明辛苦無处说，齊声腾踏牽船出。","一间茆屋何所值，父母之乡去不得。","我願此水作平田，长使水夫不怨天。"]', '诗', 'shi', '', NULL, '水夫謠 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('649329b5-17f4-4af1-8476-6e428b814cdf', '田家行', '田家行', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["男聲欣欣女顏悅，人家不怨言語別。","五月雖熱麥風清，簷頭索索繰車鳴。","野蠶作繭人不取，葉間撲撲秋蛾生。","麥收上場絹在軸，的知輸得官家足。","不望入口復上身，且免向城賣黃犢。","回家衣食無厚薄，不見縣門身即樂。"]', '["男声欣欣女顏悅，人家不怨言語別。","五月雖熱麦风清，簷头索索繰车鳴。","野蠶作繭人不取，葉间撲撲秋蛾生。","麦收上場絹在軸，的知輸得官家足。","不望入口复上身，且免向城賣黄犢。","回家衣食無厚薄，不见縣门身即乐。"]', '诗', 'shi', '', NULL, '田家行 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acd2442a-816c-4a5b-a0dc-94e0ba485033', '去婦', '去婦', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["新婦去年腁手足，衣不暇縫蠶廢簇。","白頭使我憂家事，還如夜裏燒殘燭。","當初爲取傍人語，豈道如今自辛苦。","在時縱嫌織絹遲，有絲不上鄰家機。"]', '["新婦去年腁手足，衣不暇縫蠶廢簇。","白头使我憂家事，還如夜裏燒殘燭。","當初爲取傍人語，豈道如今自辛苦。","在时縱嫌织絹遲，有絲不上鄰家機。"]', '诗', 'shi', '', NULL, '去婦 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67a7c727-1f4b-4950-82a9-80841147949e', '神樹詞', '神樹词', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["我家家西老棠樹，須晴即晴雨即雨。","四時八節上杯盤，願神莫離神處所。","男不着丁女在舍，官事上下無言語。","老身長健樹婆娑，萬歲千年作神主。"]', '["我家家西老棠樹，須晴即晴雨即雨。","四时八節上杯盤，願神莫離神处所。","男不着丁女在舍，官事上下無言語。","老身长健樹婆娑，万歲千年作神主。"]', '诗', 'shi', '', NULL, '神樹詞 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20a724d2-1075-4645-8bbd-7385f675a2dc', '祝鵲', '祝鵲', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["神鵲神鵲好言語，行人早回多利賂。","我今庭中栽好樹，與汝作巢當報汝。"]', '["神鵲神鵲好言語，行人早回多利賂。","我今庭中栽好樹，與汝作巢當報汝。"]', '诗', 'shi', '', NULL, '祝鵲 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13d28611-fc3c-4b50-af12-d155d9ab5895', '古謠', '古謠', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["一東一西壠頭水，一聚一散天邊霞。","一來一去道上客，一顛一倒池中麻。"]', '["一东一西壠头水，一聚一散天邊霞。","一来一去道上客，一顛一倒池中麻。"]', '诗', 'shi', '', NULL, '古謠 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26a84f32-1349-4ff1-8b61-91d2af5cd47c', '公無渡河', '公無渡河', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["渡頭惡天兩岸遠，波濤塞川如疊坂。","幸無白刃驅向前，何用將身自棄捐。","蛟龍嚙骨魚食血，黃泥直下無青天。","男兒縱輕婦人語，惜君性命還須取。","婦人無力挽斷衣，舟沈身死悔難追。","公無渡河，公須自爲。"]', '["渡头惡天兩岸远，波濤塞川如叠坂。","幸無白刃驱向前，何用將身自棄捐。","蛟龙嚙骨鱼食血，黄泥直下無青天。","男兒縱轻婦人語，惜君性命還須取。","婦人無力挽斷衣，舟沈身死悔难追。","公無渡河，公須自爲。"]', '诗', 'shi', '', NULL, '公無渡河 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aae75655-ec65-44a3-a8b5-71de5dafa5ef', '海人謠', '海人謠', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["海人無家海裏住，採珠役象爲歲賦。","惡波橫天山塞路，未央宮中常滿庫。"]', '["海人無家海裏住，採珠役象爲歲賦。","惡波橫天山塞路，未央宮中常满庫。"]', '诗', 'shi', '', NULL, '海人謠 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cee87ca-ba60-468f-8569-9e5a69147dee', '行見月', '行见月', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["月初生，居人見月一月行。","行行一年十二月，強半馬上看盈缺。","百年歡樂能幾何，在家見少行見多。","不緣衣食相驅遣，此身誰願長奔波。","篋中有帛倉有粟，豈向天涯走碌碌。","家人見月望我歸，正是道上思家時。"]', '["月初生，居人见月一月行。","行行一年十二月，強半马上看盈缺。","百年歡乐能幾何，在家见少行见多。","不緣衣食相驱遣，此身誰願长奔波。","篋中有帛倉有粟，豈向天涯走碌碌。","家人见月望我归，正是道上思家时。"]', '诗', 'shi', '', NULL, '行見月 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d8dba87-8e48-42cb-9943-653cd609afe3', '七夕曲', '七夕曲', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["河邊獨自看星宿，夜織天絲難接續。","拋梭振鑷動明璫，爲有秋期眠不足。","遙愁今夜河水隔，龍駕車轅鵲填石。","流蘇翠帳星渚間，環珮無聲燈寂寂。","兩情纏綿忽如故，復畏秋風生曉路。","幸回郎意且斯須，一年中別今始初，明星未出少停車。"]', '["河邊独自看星宿，夜织天絲难接續。","拋梭振鑷动明璫，爲有秋期眠不足。","遙愁今夜河水隔，龙駕车轅鵲填石。","流蘇翠帳星渚间，环珮無声灯寂寂。","兩情纏綿忽如故，复畏秋风生晓路。","幸回郎意且斯須，一年中別今始初，明星未出少停车。"]', '诗', 'shi', '', NULL, '七夕曲 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe6f88c0-13a5-4742-b8c4-6c3b4c8ef8ed', '兩頭纖纖', '兩头纖纖', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["兩頭纖纖青玉玦，半白半黑頭上髮。","偪偪仆仆春冰裂，磊磊落落桃花結。"]', '["兩头纖纖青玉玦，半白半黑头上髮。","偪偪仆仆春冰裂，磊磊落落桃花結。"]', '诗', 'shi', '', NULL, '兩頭纖纖 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('feb3e164-e431-4451-89da-49f5829aeeb7', '獨漉歌', '独漉歌', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["獨獨漉漉，鼠食貓肉。","烏日中，鶴露宿，黃河水直人心曲。"]', '["独独漉漉，鼠食貓肉。","烏日中，鹤露宿，黄河水直人心曲。"]', '诗', 'shi', '', NULL, '獨漉歌 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d47993cd-94d9-468e-93e9-0c3c237e2d8c', '寄遠曲', '寄远曲', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["美人別來無處所，巫山月明湘江雨。","千回相見不分明，井底看星夢中語。","兩心相對尚難知，何況萬里不相疑。"]', '["美人別来無处所，巫山月明湘江雨。","千回相见不分明，井底看星梦中語。","兩心相对尚难知，何況万里不相疑。"]', '诗', 'shi', '', NULL, '寄遠曲 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddec6ff9-8dd4-4e9e-8789-009f896a7703', '傷韋令孔雀詞', '傷韋令孔雀词', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["可憐孔雀初得時，美人爲爾別開池。","池邊鳳凰作伴侶，羌聲鸚鵡無言語。","雕籠玉架嫌不棲，夜夜思歸向南舞。","如今憔悴人見惡，萬里更求新孔雀。","熱眠雨水飢拾蟲，翠尾盤泥金彩落。","多時人養不解飛，海山風黑何處歸。"]', '["可怜孔雀初得时，美人爲爾別开池。","池邊鳳凰作伴侶，羌声鸚鵡無言語。","雕籠玉架嫌不棲，夜夜思归向南舞。","如今憔悴人见惡，万里更求新孔雀。","熱眠雨水飢拾蟲，翠尾盤泥金彩落。","多时人養不解飞，海山风黑何处归。"]', '诗', 'shi', '', NULL, '傷韋令孔雀詞 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69e45825-c9d6-464b-aa58-098c19774d6c', '傷鄰家鸚鵡詞', '傷鄰家鸚鵡词', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["東家小女不惜錢，買得鸚鵡獨自憐。","自從死却家中女，無人更共鸚鵡語。","十日不飲一滴漿，淚漬綠毛頭似鼠。","舌關啞咽畜哀怨，開籠放飛離人眼。","短聲亦絕翠臆翻，新墓崔嵬舊巢遠。","此禽有志女有靈，定爲連理相並生。"]', '["东家小女不惜錢，買得鸚鵡独自怜。","自從死却家中女，無人更共鸚鵡語。","十日不饮一滴漿，泪漬綠毛头似鼠。","舌关啞咽畜哀怨，开籠放飞離人眼。","短声亦絕翠臆翻，新墓崔嵬旧巢远。","此禽有志女有靈，定爲連理相並生。"]', '诗', 'shi', '', NULL, '傷鄰家鸚鵡詞 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db2e0bcc-0147-45e2-ad79-3e571534a6b9', '春來曲', '春来曲', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["春欲來，每日望春門早開。","黃衫白馬帶塵土，逢著探春人却回。","御堤內園曉過急，九衢大宅家家入。","青帝少女染桃花，露妝初出紅猶濕。","光風暾暾蝶宛宛，遶樹氣匝枝柯軟。","可憐寒食街中郎，早起著得單衣裳。","少年即見春好處，似我白頭無好樹。"]', '["春欲来，每日望春门早开。","黄衫白马带塵土，逢著探春人却回。","御堤內园晓過急，九衢大宅家家入。","青帝少女染桃花，露妝初出紅猶濕。","光风暾暾蝶宛宛，遶樹氣匝枝柯軟。","可怜寒食街中郎，早起著得單衣裳。","少年即见春好处，似我白头無好樹。"]', '诗', 'shi', '', NULL, '春來曲 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fe2a594-673e-4ab3-a897-c11997fedeb7', '春去曲', '春去曲', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["春已去，花亦不知春去處。","緣岡繞澗却歸來，百回看著無花樹。","就中一夜東風惡，收紅拾紫無遺落。","老夫不比少年兒，不中數與春別離。"]', '["春已去，花亦不知春去处。","緣岡繞澗却归来，百回看著無花樹。","就中一夜东风惡，收紅拾紫無遺落。","老夫不比少年兒，不中數與春別離。"]', '诗', 'shi', '', NULL, '春去曲 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08932057-7ef8-459d-8868-5b8b4e9bad85', '東征行', '东征行', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["桐栢水西賊星落，梟雛夜飛林木惡。","相國刻日波濤清，當朝自請東南征。","舍人爲賓侍郎副，曉覺蓬萊欠珮聲。","玉階舞蹈謝旌節，生死向前山可穴。","同時賜馬幷賜衣，御樓看帶弓刀發。","馬前猛士三百人，金書左右紅旗新。","司庖常膳皆得對，好事將軍封爾身。","男兒生殺在手裏，營門老將皆憂死。","曈曈白日當南山，不立功名終不還。"]', '["桐栢水西賊星落，梟雛夜飞林木惡。","相国刻日波濤清，當朝自請东南征。","舍人爲賓侍郎副，晓覺蓬萊欠珮声。","玉階舞蹈謝旌節，生死向前山可穴。","同时賜马幷賜衣，御楼看带弓刀發。","马前猛士三百人，金书左右紅旗新。","司庖常膳皆得对，好事將軍封爾身。","男兒生殺在手裏，營门老將皆憂死。","曈曈白日當南山，不立功名終不還。"]', '诗', 'shi', '', NULL, '東征行 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bf453d9-38b0-44e5-85b9-f556c7785271', '荆門行', '荆门行', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["江邊行人暮悠悠，山頭殊未見荆州。","峴亭西南路多曲，櫟林深深石鏃鏃。","看炊紅米煮白魚，夜向雞鳴店家宿。","南中三月蚊蚋生，黃昏不聞人語聲。","生紗帷疎薄如霧，隔衣噆膚耳邊鳴。","欲明不待燈火起，喚得官船過蠻水。","女兒停客茆屋新，開門掃地桐花裏。","犬聲撲撲寒溪煙，人家燒竹種山田。","巴雲欲雨薰石熱，麋鹿度江蟲出穴。","大蛇過處一山腥，野牛驚跳雙角折。","斜分漢水橫千山，山青水綠荆門關。","向前問箇長沙路，舊是屈原沈溺處。","誰家丹旐已南來，逢著流人從此去。","月明山鳥多不棲，下枝飛上高枝啼。","主人念遠心不懌，羅衫臥對章臺夕。","紅燭交橫各自歸，酒醒還是他鄉客。","壯年留滯尚思家，況復白頭在天涯。"]', '["江邊行人暮悠悠，山头殊未见荆州。","峴亭西南路多曲，櫟林深深石鏃鏃。","看炊紅米煮白鱼，夜向雞鳴店家宿。","南中三月蚊蚋生，黄昏不闻人語声。","生紗帷疎薄如霧，隔衣噆膚耳邊鳴。","欲明不待灯火起，喚得官船過蠻水。","女兒停客茆屋新，开门掃地桐花裏。","犬声撲撲寒溪煙，人家燒竹種山田。","巴云欲雨薰石熱，麋鹿度江蟲出穴。","大蛇過处一山腥，野牛驚跳雙角折。","斜分漢水橫千山，山青水綠荆门关。","向前问箇长沙路，旧是屈原沈溺处。","誰家丹旐已南来，逢著流人從此去。","月明山鸟多不棲，下枝飞上高枝啼。","主人念远心不懌，羅衫臥对章台夕。","紅燭交橫各自归，酒醒還是他乡客。","壯年留滯尚思家，況复白头在天涯。"]', '诗', 'shi', '', NULL, '荆門行 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d3b99f2-568b-4c3c-a7a1-ec13ca148381', '鏡聽詞', '镜听词', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["重重摩挲嫁時鏡，夫壻遠行憑鏡聽。","回身不遣別人知，人意丁寧鏡神聖。","懷中收拾雙錦帶，恐畏街頭見驚怪。","嗟嗟際際下堂階，獨自竈前來跪拜。","出門願不聞悲哀，郎在任郎回未回。","月明地上人過盡，好語多同皆道來。","卷帷上牀喜不定，與郎裁衣失翻正。","可中三日得相見，重繡錦囊磨鏡面。"]', '["重重摩挲嫁时镜，夫壻远行憑镜听。","回身不遣別人知，人意丁寧镜神聖。","懷中收拾雙錦带，恐畏街头见驚怪。","嗟嗟際際下堂階，独自竈前来跪拜。","出门願不闻悲哀，郎在任郎回未回。","月明地上人過尽，好語多同皆道来。","卷帷上牀喜不定，與郎裁衣失翻正。","可中三日得相见，重繡錦囊磨镜面。"]', '诗', 'shi', '', NULL, '鏡聽詞 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7617e041-5807-442d-ae0f-591eea74c71d', '行宮詞', '行宮词', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["上陽宮到蓬萊殿，行宮巖巖遙相見。","向前天子行幸多，馬蹄車轍山川遍。","當時州縣每年修，皆留內人看玉案。","禁兵奪得明堂後，長閉桃源與綺繡。","開元歌舞古草頭，梁州樂人世嫌舊。","官家乏人作宮戶，不泥宮牆斫宮樹。","兩邊仗屋半崩摧，夜火入林燒殿柱。","休封中岳六十年，行宮不見人眼穿。"]', '["上陽宮到蓬萊殿，行宮巖巖遙相见。","向前天子行幸多，马蹄车轍山川遍。","當时州縣每年修，皆留內人看玉案。","禁兵奪得明堂後，长閉桃源與綺繡。","开元歌舞古草头，梁州乐人世嫌旧。","官家乏人作宮戶，不泥宮牆斫宮樹。","兩邊仗屋半崩摧，夜火入林燒殿柱。","休封中岳六十年，行宮不见人眼穿。"]', '诗', 'shi', '', NULL, '行宮詞 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83ebd852-25b4-44fa-a74e-76aba64b063f', '羽林行', '羽林行', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["長安惡少出名字，樓下劫商樓上醉。","天明下直明光宮，散入五陵松柏中。","百回殺人身合死，赦書尚有收城功。","九衢一日消息定，鄉吏籍中重改姓。","出來依舊屬羽林，立在殿前射飛禽。"]', '["长安惡少出名字，楼下劫商楼上醉。","天明下直明光宮，散入五陵松柏中。","百回殺人身合死，赦书尚有收城功。","九衢一日消息定，乡吏籍中重改姓。","出来依旧屬羽林，立在殿前射飞禽。"]', '诗', 'shi', '', NULL, '羽林行 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cbb6fb5-44cf-463b-bff1-33203d774c71', '射虎行', '射虎行', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["自去射虎得虎歸，官差射虎得虎遲。","獨行以死當虎命，兩人因疑終不定。","朝朝暮暮空手回，山下綠苗成道徑。","遠立不敢污箭鏃，聞死還來分虎肉。","惜留猛虎着深山，射殺恐畏終身閑。"]', '["自去射虎得虎归，官差射虎得虎遲。","独行以死當虎命，兩人因疑終不定。","朝朝暮暮空手回，山下綠苗成道徑。","远立不敢污箭鏃，闻死還来分虎肉。","惜留猛虎着深山，射殺恐畏終身闲。"]', '诗', 'shi', '', NULL, '射虎行 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49002be8-8bd7-4914-be68-291a13de9735', '遠將歸', '远將归', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["遠將歸，勝未別離時。","在家相見熱，新歸歡不足。","去願車輪遲，回思馬蹄速。","但令在舍相對貧，不向天涯金遶身。"]', '["远將归，勝未別離时。","在家相见熱，新归歡不足。","去願车輪遲，回思马蹄速。","但令在舍相对貧，不向天涯金遶身。"]', '诗', 'shi', '', NULL, '遠將歸 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1014dab5-7db0-482c-9f61-efcd3f2a7295', '尋橦歌', '尋橦歌', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["人間百戲皆可學，尋橦不比諸餘樂。","重梳短髻下金鈿，紅帽青巾各一邊。","身輕足捷勝男子，繞竿四面爭先緣。","習多依附攲竿滑，上下蹁躚皆著襪。","翻身垂頸欲落地，却住把腰初似歇。","大竿百夫擎不起，褭褭半在青雲裏。","纖腰女兒不動容，戴行直舞一曲終。","回頭但覺人眼見，矜難恐畏天無風。","險中更險何曾失，山鼠懸頭猿挂膝。","小垂一手當舞盤，斜慘雙蛾看落日。","斯須改變曲解新，貴欲歡他平地人。","散時滿面生顏色，行步依前無氣力。"]', '["人间百戲皆可学，尋橦不比諸餘乐。","重梳短髻下金鈿，紅帽青巾各一邊。","身轻足捷勝男子，繞竿四面爭先緣。","習多依附攲竿滑，上下蹁躚皆著襪。","翻身垂頸欲落地，却住把腰初似歇。","大竿百夫擎不起，褭褭半在青云裏。","纖腰女兒不动容，戴行直舞一曲終。","回头但覺人眼见，矜难恐畏天無风。","險中更險何曾失，山鼠懸头猿挂膝。","小垂一手當舞盤，斜慘雙蛾看落日。","斯須改变曲解新，貴欲歡他平地人。","散时满面生顏色，行步依前無氣力。"]', '诗', 'shi', '', NULL, '尋橦歌 王建 shi');
